const lessons = [
{num:1,time:"00:00:00,000 --> 00:00:04,120",arabic:"مَاذَا لَوْ لَمْ تَكُنْ أَكْثَرُ الْأَمَاكِنِ اسْتِثْنَائِيَّةً عَلَى كَوْكَبِ الْأَرْضِ",segs:[{ar:"مَاذَا لَوْ لَمْ تَكُنْ",uz:"agar ... bo‘lmaganida nima bo‘lardi"},{ar:"أَكْثَرُ الْأَمَاكِنِ اسْتِثْنَائِيَّةً",uz:"eng noyob joylar"},{ar:"عَلَى كَوْكَبِ الْأَرْضِ",uz:"Yer sayyorasidagi"}],full_uz:"Agar Yer sayyorasidagi eng noyob joylar...",note:"مَاذَا لَوْ — agar ... bo‘lganida nima bo‘lardi."},
{num:2,time:"00:00:04,120 --> 00:00:06,480",arabic:"مُجَرَّدَ وِجْهَاتٍ لِلسَّفَرِ",segs:null,full_uz:"Shunchaki sayohat maskanlari.",note:"وِجْهَةٌ — yo‘nalish, manzil, sayohat maskani."},
{num:3,time:"00:00:06,480 --> 00:00:11,220",arabic:"بَلْ تَجَارِبَ تُعِيدُ تَشْكِيلَ الطَّرِيقَةِ الَّتِي نَرَى بِهَا الْعَالَمَ",segs:[{ar:"بَلْ تَجَارِبَ",uz:"balki tajribalar"},{ar:"تُعِيدُ تَشْكِيلَ الطَّرِيقَةِ",uz:"qarash tarzimizni qayta shakllantiradigan"},{ar:"الَّتِي نَرَى بِهَا الْعَالَمَ",uz:"dunyoni qanday ko‘rishimizni"}],full_uz:"Balki dunyoni qanday ko‘rishimizni qayta shakllantiradigan tajribalar bo‘lganida nima bo‘lardi?",note:"إِعَادَةُ التَّشْكِيلِ — qayta shakllantirish."},
{num:4,time:"00:00:11,220 --> 00:00:13,780",arabic:"فِي أَرْجَاءِ هَذَا الْكَوْكَبِ",segs:null,full_uz:"Bu sayyoraning turli burchaklarida.",note:"أَرْجَاءٌ — tomonlar, burchaklar, kengliklar."},
{num:5,time:"00:00:13,780 --> 00:00:17,559",arabic:"تَنْتَشِرُ عَجَائِبُ تَبْدُو سُرْيَالِيَّةً",segs:[{ar:"تَنْتَشِرُ عَجَائِبُ",uz:"mo‘jizalar tarqalgan"},{ar:"تَبْدُو سُرْيَالِيَّةً",uz:"syurreal ko‘rinadigan"}],full_uz:"Syurreal ko‘rinadigan mo‘jizalar tarqalgan.",note:"سُرْيَالِيٌّ — syurreal, g‘ayrioddiy."},
{num:6,time:"00:00:17,559 --> 00:00:20,120",arabic:"إِلَى حَدٍّ يَصْعُبُ تَصْدِيقُهُ",segs:[{ar:"إِلَى حَدٍّ",uz:"shunday darajadaki"},{ar:"يَصْعُبُ تَصْدِيقُهُ",uz:"unga ishonish qiyin"}],full_uz:"Shunday darajadaki, unga ishonish qiyin.",note:null},
{num:7,time:"00:00:20,120 --> 00:00:23,519",arabic:"أَمَاكِنُ بِجَمَالِهَا أَوْ خُطُورَتِهَا",segs:[{ar:"أَمَاكِنُ",uz:"joylar"},{ar:"بِجَمَالِهَا أَوْ خُطُورَتِهَا",uz:"go‘zalligi yoki xavfliligi bilan"}],full_uz:"Go‘zalligi yoki xavfliligi bilan ajralib turadigan joylar.",note:"خُطُورَةٌ — xavflilik."},
{num:8,time:"00:00:23,519 --> 00:00:26,519",arabic:"وَكَأَنَّهَا وُجِدَتْ",segs:null,full_uz:"Go‘yo ular mavjud bo‘lgandek.",note:null},
{num:9,time:"00:00:26,519 --> 00:00:29,719",arabic:"لِتَخْتَبِرَ حُدُودَ الْخَيَالِ الْإِنْسَانِيِّ",segs:[{ar:"لِتَخْتَبِرَ حُدُودَ الْخَيَالِ",uz:"tasavvur chegaralarini sinash uchun"},{ar:"الْإِنْسَانِيِّ",uz:"insoniy"}],full_uz:"Insoniy tasavvur chegaralarini sinash uchun mavjud bo‘lgandek.",note:"يَخْتَبِرُ — sinamoq, tekshirmoq."},
{num:10,time:"00:00:29,719 --> 00:00:35,219",arabic:"فِي حَدِيقَةِ أَشِيكَاكَا لِلزُّهُورِ فِي الْيَابَانِ",segs:[{ar:"فِي حَدِيقَةِ أَشِيكَاكَا لِلزُّهُورِ",uz:"Ashikaga gullar bog‘ida"},{ar:"فِي الْيَابَانِ",uz:"Yaponiyada"}],full_uz:"Yaponiyadagi Ashikaga gullar bog‘ida.",note:null},
{num:11,time:"00:00:35,219 --> 00:00:39,399",arabic:"تَتَفَتَّحُ أَنْفَاقٌ كَامِلَةٌ مِنْ زُهُورِ الْوِسْتَرِيَا",segs:[{ar:"تَتَفَتَّحُ أَنْفَاقٌ كَامِلَةٌ",uz:"butun boshli yo‘laklar ochiladi"},{ar:"مِنْ زُهُورِ الْوِسْتَرِيَا",uz:"visteriya gullaridan"}],full_uz:"Visteriya gullaridan butun boshli yo‘laklar ochilib ketadi.",note:"تَتَفَتَّحُ — ochilmoq, gullamoq. أَنْفَاقٌ — yo‘laklar, tunnellar."},
{num:12,time:"00:00:39,399 --> 00:00:44,399",arabic:"تَنْسَابُ فِي مَوْجَاتٍ مُتَدَلِّيَةٍ مِنَ الْبَنَفْسَجِيِّ وَالْأَبْيَضِ",segs:[{ar:"تَنْسَابُ فِي مَوْجَاتٍ مُتَدَلِّيَةٍ",uz:"osilib turgan to‘lqinlar kabi oqadi"},{ar:"مِنَ الْبَنَفْسَجِيِّ وَالْأَبْيَضِ",uz:"binafsha va oq ranglarda"}],full_uz:"Ular binafsha va oq ranglardagi osilib turgan to‘lqinlar kabi oqadi.",note:"مُتَدَلٍّ — osilib turgan."},
{num:13,time:"00:00:44,399 --> 00:00:47,960",arabic:"مُتَوَهِّجَةً كَأَنَّهَا مَجَرَّاتٌ حَيَّةٌ",segs:[{ar:"مُتَوَهِّجَةً",uz:"yarqiragan holda"},{ar:"كَأَنَّهَا مَجَرَّاتٌ حَيَّةٌ",uz:"go‘yo tirik galaktikalardek"}],full_uz:"Go‘yo tirik galaktikalardek yarqiraydi.",note:"مُتَوَهِّجٌ — yarqiragan, nur sochayotgan."},
{num:14,time:"00:00:47,960 --> 00:00:53,460",arabic:"مَكَانٌ تَشْعُرُ فِيهِ وَكَأَنَّ الطَّبِيعَةَ صِيغَتْ بِحُلْمٍ دَقِيقٍ",segs:[{ar:"مَكَانٌ تَشْعُرُ فِيهِ",uz:"shunday joyki, unda his qilasiz"},{ar:"وَكَأَنَّ الطَّبِيعَةَ صِيغَتْ",uz:"go‘yo tabiat shakllantirilgandek"},{ar:"بِحُلْمٍ دَقِيقٍ",uz:"nozik bir tush bilan"}],full_uz:"Shunday joyki, go‘yo tabiat nozik bir tush bilan shakllantirilgandek his qilasiz.",note:"صَاغَ — shakl bermoq, yaratmoq."},
{num:15,time:"00:00:53,460 --> 00:00:55,480",arabic:"لَا بِصُدْفَةٍ عَابِرَةٍ",segs:null,full_uz:"O‘tkinchi tasodif bilan emas.",note:"عَابِرٌ — o‘tkinchi."},
{num:16,time:"00:00:55,480 --> 00:00:59,500",arabic:"وَعَلَى ارْتِفَاعَاتٍ شَاهِقَةٍ فَوْقَ مُنْحَدَرَاتِ الصِّينِ",segs:[{ar:"وَعَلَى ارْتِفَاعَاتٍ شَاهِقَةٍ",uz:"balandliklarda"},{ar:"فَوْقَ مُنْحَدَرَاتِ الصِّينِ",uz:"Xitoy qoyalari ustida"}],full_uz:"Xitoy qoyalari ustidagi balandliklarda.",note:"شَاهِقٌ — juda baland, osmono‘par."},
{num:17,time:"00:00:59,500 --> 00:01:06,819",arabic:"يَتَحَدَّى مَسَارُ فِيرَاتَا جَبَلَ يَانْدَانْغَ أَكْثَرَ الْمُغَامِرِينَ جُرْأَةً",segs:[{ar:"يَتَحَدَّى مَسَارُ فِيرَاتَا",uz:"Via ferrata yo‘li sinovga chorlaydi"},{ar:"جَبَلَ يَانْدَانْغَ",uz:"Yandang tog‘ini"},{ar:"أَكْثَرَ الْمُغَامِرِينَ جُرْأَةً",uz:"eng jasur sarguzashtchilarni"}],full_uz:"Yandang tog‘idagi Via ferrata yo‘li eng jasur sarguzashtchilarni sinovga chorlaydi.",note:"جُرْأَةٌ — jasorat, qo‘rqmaslik."},
{num:18,time:"00:01:06,819 --> 00:01:12,219",arabic:"كابِلَاتٌ فُولَاذِيَّةٌ تَتَشَبَّثُ بِحَوَافِّ صَخْرِيَّةٍ حَادَّةٍ",segs:[{ar:"كابِلَاتٌ فُولَاذِيَّةٌ",uz:"po‘lat kabellar"},{ar:"تَتَشَبَّثُ بِحَوَافِّ صَخْرِيَّةٍ حَادَّةٍ",uz:"o‘tkir qoyalar chetiga mahkam yopishadi"}],full_uz:"Po‘lat kabellar o‘tkir qoyalar chetiga mahkam yopishib turadi.",note:"فُولَاذِيٌّ — po‘latdan yasalgan. تَتَشَبَّثُ — mahkam yopishmoq."},
{num:19,time:"00:01:12,219 --> 00:01:16,939",arabic:"حَيْثُ تُصْبِحُ كُلُّ خُطْوَةٍ مُعَلَّقَةً بَيْنَ الْخَوْفِ وَالِانْبِهَارِ",segs:[{ar:"حَيْثُ تُصْبِحُ كُلُّ خُطْوَةٍ مُعَلَّقَةً",uz:"u yerda har bir qadam muallaq bo‘lib qoladi"},{ar:"بَيْنَ الْخَوْفِ وَالِانْبِهَارِ",uz:"qo‘rquv va hayrat orasida"}],full_uz:"U yerda har bir qadam qo‘rquv va hayrat orasida muallaq bo‘lib qoladi.",note:"الِانْبِهَارُ — hayrat, mahliyo bo‘lish."},
{num:20,time:"00:01:16,939 --> 00:01:20,560",arabic:"وَكُلُّ حَرَكَةٍ اخْتِبَارٌ لِلثَّبَاتِ وَالشَّجَاعَةِ",segs:[{ar:"وَكُلُّ حَرَكَةٍ",uz:"va har bir harakat"},{ar:"اخْتِبَارٌ لِلثَّبَاتِ وَالشَّجَاعَةِ",uz:"sobitlik va jasorat sinovidir"}],full_uz:"Va har bir harakat sobitlik va jasorat sinovidir.",note:"الثَّبَاتُ — sobitlik, barqarorlik."},
{num:21,time:"00:01:20,560 --> 00:01:23,680",arabic:"أَمَّا فِي الْفِلِبِّينِ",segs:null,full_uz:"Filippinda esa.",note:"أَمَّا — esa, ammo."},
{num:22,time:"00:01:23,680 --> 00:01:30,360",arabic:"فَتَفْتَحُ مِيَاهُ بُحَيْرَةِ بَيْسُوبَ الصَّافِيَةُ أَبْوَابَهَا لِلْعُشَّاقِ وَالْمُغَامِرِينَ مَعًا",segs:[{ar:"فَتَفْتَحُ مِيَاهُ بُحَيْرَةِ بَيْسُوبَ الصَّافِيَةُ أَبْوَابَهَا",uz:"Bisop ko‘lining tiniq suvlari o‘z eshiklarini ochadi"},{ar:"لِلْعُشَّاقِ وَالْمُغَامِرِينَ مَعًا",uz:"oshiq va sarguzashtchilar uchun birdek"}],full_uz:"Bisop ko‘lining tiniq suvlari o‘z eshiklarini oshiq va sarguzashtchilar uchun birdek ochadi.",note:"الْعُشَّاقُ — oshiq­lar, sevuvchilar."},
{num:23,time:"00:01:30,360 --> 00:01:33,880",arabic:"عَالَمٌ فِيرُوزِيٌّ لَامِعٌ تَحْتَ السَّطْحِ",segs:[{ar:"عَالَمٌ فِيرُوزِيٌّ لَامِعٌ",uz:"yarqiragan feruza rangli olam"},{ar:"تَحْتَ السَّطْحِ",uz:"sirt ostida"}],full_uz:"Sirt ostida yarqiragan feruza rangli olam.",note:null},
{num:24,time:"00:01:33,880 --> 00:01:37,020",arabic:"يَمْتَزِجُ فِيهِ الْهُدُوءُ بِالْمُغَامَرَةِ",segs:null,full_uz:"Unda sokinlik sarguzasht bilan uyg‘unlashadi.",note:"يَمْتَزِجُ — qorishmoq, uyg‘unlashmoq."},
{num:25,time:"00:01:37,020 --> 00:01:42,900",arabic:"كَيْفَ نَشَأَتْ مِثْلُ هَذِهِ الْعَجَائِبِ الْمُسْتَحِيلَةِ؟",segs:[{ar:"كَيْفَ نَشَأَتْ مِثْلُ هَذِهِ الْعَجَائِبِ",uz:"bunday mo‘jizalar qanday paydo bo‘ldi"},{ar:"الْمُسْتَحِيلَةِ",uz:"imkonsizdek tuyulgan"}],full_uz:"Bunday imkonsizdek tuyulgan mo‘jizalar qanday paydo bo‘ldi?",note:"نَشَأَ — paydo bo‘lmoq, vujudga kelmoq."},
{num:26,time:"00:01:42,900 --> 00:01:47,900",arabic:"وَمَاذَا تَكْشِفُ لَنَا عَنْ أَقْصَى حُدُودِ الْجَمَالِ وَالْقُوَّةِ عَلَى كَوْكَبِنَا؟",segs:[{ar:"وَمَاذَا تَكْشِفُ لَنَا",uz:"va bizga nimani ochib beradi"},{ar:"عَنْ أَقْصَى حُدُودِ الْجَمَالِ وَالْقُوَّةِ",uz:"go‘zallik va kuchning eng yuqori chegaralari haqida"},{ar:"عَلَى كَوْكَبِنَا",uz:"sayyoramizda"}],full_uz:"Va sayyoramizdagi go‘zallik va kuchning eng yuqori chegaralari haqida bizga nimani ochib beradi?",note:null},
{num:27,time:"00:01:47,900 --> 00:01:56,180",arabic:"انْضَمُّوا إِلَيْنَا فِي رِحْلَةٍ عَبْرَ أَمَاكِنَ لَا بُدَّ مِنْ مُشَاهَدَتِهَا مَرَّةً وَاحِدَةً عَلَى الْأَقَلِّ فِي الْعُمُرِ",segs:[{ar:"انْضَمُّوا إِلَيْنَا",uz:"bizga qo‘shiling"},{ar:"فِي رِحْلَةٍ عَبْرَ أَمَاكِنَ",uz:"joylar bo‘ylab sayohatda"},{ar:"لَا بُدَّ مِنْ مُشَاهَدَتِهَا",uz:"albatta ko‘rish kerak bo‘lgan"},{ar:"مَرَّةً وَاحِدَةً عَلَى الْأَقَلِّ فِي الْعُمُرِ",uz:"umrda hech bo‘lmaganda bir marta"}],full_uz:"Umrda hech bo‘lmaganda bir marta ko‘rish kerak bo‘lgan joylar bo‘ylab sayohatda bizga qo‘shiling.",note:"لَا بُدَّ مِنْ — albatta kerak, shart."},
{num:28,time:"00:01:56,180 --> 00:02:04,180",arabic:"أَمَاكِنُ يُصْبِحُ فِيهَا الْمُسْتَحِيلُ حَقِيقَةً مَلْمُوسَةً جَمِيلَةً وَلَا يُمْكِنُ إِنْكَارُهَا",segs:[{ar:"أَمَاكِنُ يُصْبِحُ فِيهَا الْمُسْتَحِيلُ",uz:"imkonsiz narsa haqiqatga aylanadigan joylar"},{ar:"حَقِيقَةً مَلْمُوسَةً جَمِيلَةً",uz:"go‘zal va ko‘rinarli haqiqatga"},{ar:"وَلَا يُمْكِنُ إِنْكَارُهَا",uz:"uni inkor etib bo‘lmaydi"}],full_uz:"Imkonsiz narsa go‘zal, ko‘rinarli va inkor etib bo‘lmaydigan haqiqatga aylanadigan joylar.",note:"مَلْمُوسٌ — sezilarli, ko‘rinarli, aniq."},
{num:29,time:"00:02:04,180 --> 00:02:09,259",arabic:"سِينُوتِي إِيكِيل",segs:null,full_uz:"Ik-Kil senoti.",note:null},
{num:30,time:"00:02:09,259 --> 00:02:15,240",arabic:"تَكَوَّنَتْ سِينُوتِي إِيكِيلَ عَلَى مَدَى مَا يُقَارِبُ عَشَرَةَ آلَافِ عَامٍ",segs:[{ar:"تَكَوَّنَتْ سِينُوتِي إِيكِيلَ",uz:"Ik-Kil senoti shakllangan"},{ar:"عَلَى مَدَى مَا يُقَارِبُ عَشَرَةَ آلَافِ عَامٍ",uz:"qariyb o‘n ming yil davomida"}],full_uz:"Ik-Kil senoti qariyb o‘n ming yil davomida shakllangan.",note:"تَكَوَّنَ — shakllanmoq, hosil bo‘lmoq."},
{num:31,time:"00:02:15,240 --> 00:02:18,780",arabic:"وَهُوَ حُفْرَةٌ دَائِرِيَّةٌ شِبْهُ مُثَالِيَّةٍ",segs:[{ar:"وَهُوَ حُفْرَةٌ دَائِرِيَّةٌ",uz:"u dumaloq chuqurlik"},{ar:"شِبْهُ مُثَالِيَّةٍ",uz:"deyarli mukammal"}],full_uz:"U deyarli mukammal dumaloq chuqurlikdir.",note:"شِبْهُ — deyarli, go‘yo."},
{num:32,time:"00:02:18,780 --> 00:02:22,920",arabic:"نَشَأَتْ حِينَ انْهَارَتْ طَبَقَاتُ الْحَجَرِ الْجِيرِيِّ الْقَدِيمَةُ",segs:[{ar:"نَشَأَتْ حِينَ انْهَارَتْ",uz:"... qulaganda paydo bo‘lgan"},{ar:"طَبَقَاتُ الْحَجَرِ الْجِيرِيِّ الْقَدِيمَةُ",uz:"qadimiy ohaktosh qatlamlari"}],full_uz:"Qadimiy ohaktosh qatlamlari qulaganda paydo bo‘lgan.",note:"انْهَارَ — qulamoq."},
{num:33,time:"00:02:22,920 --> 00:02:29,700",arabic:"كَشَفَتْ عَنْ نِظَامِ أَنْهَارٍ جَوْفِيَّةٍ فِي شِبْهِ جَزِيرَةِ يُوكْتَان",segs:[{ar:"كَشَفَتْ عَنْ نِظَامِ أَنْهَارٍ جَوْفِيَّةٍ",uz:"yer osti daryolari tizimini ochib berdi"},{ar:"فِي شِبْهِ جَزِيرَةِ يُوكْتَان",uz:"Yukatan yarimorolida"}],full_uz:"Yukatan yarimorolida yer osti daryolari tizimini ochib berdi.",note:"جَوْفِيٌّ — yer osti, ichki."},
{num:34,time:"00:02:29,700 --> 00:02:35,140",arabic:"يَبْلُغُ قُطْرُ هَذَا الْحَوْضِ الطَّبِيعِيِّ نَحْوَ أَرْبَعِينَ مِتْرًا",segs:[{ar:"يَبْلُغُ قُطْرُ هَذَا الْحَوْضِ الطَّبِيعِيِّ",uz:"bu tabiiy havzaning diametri yetadi"},{ar:"نَحْوَ أَرْبَعِينَ مِتْرًا",uz:"qariyb qirq metrga"}],full_uz:"Bu tabiiy havzaning diametri qariyb qirq metrga yetadi.",note:"قُطْرٌ — diametr."},
{num:35,time:"00:02:35,140 --> 00:02:39,939",arabic:"وَيَصِلُ عُمْقُهُ إِلَى أَكْثَرَ مِنْ خَمْسَةٍ وَعِشْرِينَ مِتْرًا",segs:[{ar:"وَيَصِلُ عُمْقُهُ",uz:"uning chuqurligi yetadi"},{ar:"إِلَى أَكْثَرَ مِنْ خَمْسَةٍ وَعِشْرِينَ مِتْرًا",uz:"yigirma besh metrdan ortiq"}],full_uz:"Uning chuqurligi yigirma besh metrdan ortiq.",note:null},
{num:36,time:"00:02:39,939 --> 00:02:48,300",arabic:"تَتَدَلَّى جُذُورُ النَّبَاتَاتِ مِنْ جُدْرَانِهِ الْعَمُودِيَّةِ كَأَنَّهَا ثُرَيَّاتٌ حَيَّةٌ",segs:[{ar:"تَتَدَلَّى جُذُورُ النَّبَاتَاتِ",uz:"o‘simlik ildizlari osilib turadi"},{ar:"مِنْ جُدْرَانِهِ الْعَمُودِيَّةِ",uz:"uning tik devorlaridan"},{ar:"كَأَنَّهَا ثُرَيَّاتٌ حَيَّةٌ",uz:"go‘yo tirik qandillardek"}],full_uz:"O‘simlik ildizlari uning tik devorlaridan go‘yo tirik qandillardek osilib turadi.",note:"ثُرَيَّةٌ — qandil, lyustra."},
{num:37,time:"00:02:48,300 --> 00:02:54,099",arabic:"يَنْزِلُ الزُّوَّارُ عَبْرَ أَكْثَرَ مِنْ تِسْعِينَ دَرَجَةً حَجَرِيَّةً",segs:[{ar:"يَنْزِلُ الزُّوَّارُ",uz:"ziyoratchilar tushadilar"},{ar:"عَبْرَ أَكْثَرَ مِنْ تِسْعِينَ دَرَجَةً حَجَرِيَّةً",uz:"to‘qsondan ortiq tosh zinadan"}],full_uz:"Ziyoratchilar to‘qsondan ortiq tosh zinadan tushadilar.",note:"دَرَجَةٌ — zina, pog‘ona."},
{num:38,time:"00:02:54,099 --> 00:02:59,199",arabic:"لِيَغُوصُوا فِي مِيَاهٍ كَانَتْ مُقَدَّسَةً لَدَى فَلْكِيِّي حَضَارَةِ الْمَايَا",segs:[{ar:"لِيَغُوصُوا فِي مِيَاهٍ",uz:"suvga sho‘ng‘ish uchun"},{ar:"كَانَتْ مُقَدَّسَةً",uz:"muqaddas bo‘lgan"},{ar:"لَدَى فَلْكِيِّي حَضَارَةِ الْمَايَا",uz:"Maya sivilizatsiyasi falakshunoslari uchun"}],full_uz:"Maya sivilizatsiyasi falakshunoslari uchun muqaddas bo‘lgan suvlarga sho‘ng‘ish uchun.",note:"فَلْكِيٌّ — falakshunos, astronom."},
{num:39,time:"00:02:59,199 --> 00:03:04,319",arabic:"وَمِنْ مَنَصَّاتٍ تَرْتَفِعُ عَشَرَاتِ الْأَقْدَامِ فَوْقَ السَّطْحِ",segs:[{ar:"وَمِنْ مَنَصَّاتٍ",uz:"va platformalardan"},{ar:"تَرْتَفِعُ عَشَرَاتِ الْأَقْدَامِ فَوْقَ السَّطْحِ",uz:"sirtidan o‘nlab fut baland ko‘tarilgan"}],full_uz:"Sirtidan o‘nlab fut baland platformalardan.",note:"مَنَصَّةٌ — platforma, maydoncha."},
{num:40,time:"00:03:04,319 --> 00:03:07,840",arabic:"يَقْفِزُ الْمُغَامِرُونَ إِلَى الْأَعْمَاقِ الزَّرْقَاءِ",segs:[{ar:"يَقْفِزُ الْمُغَامِرُونَ",uz:"sarguzashtchilar sakraydilar"},{ar:"إِلَى الْأَعْمَاقِ الزَّرْقَاءِ",uz:"moviy qa’rga"}],full_uz:"Sarguzashtchilar moviy qa’rga sakraydilar.",note:"الْأَعْمَاقُ — qa’r, chuqurliklar."},
{num:41,time:"00:03:07,840 --> 00:03:16,099",arabic:"فِي تَجْرِبَةٍ تَمْزِجُ بَيْنَ الْجِيُولُوجْيَا وَالتَّارِيخِ وَإِثَارَةِ السُّقُوطِ الْحُرِّ",segs:[{ar:"فِي تَجْرِبَةٍ تَمْزِجُ بَيْنَ الْجِيُولُوجْيَا وَالتَّارِيخِ",uz:"geologiya va tarixni uyg‘unlashtiradigan tajribada"},{ar:"وَإِثَارَةِ السُّقُوطِ الْحُرِّ",uz:"erkin qulash hayajoni bilan"}],full_uz:"Geologiya, tarix va erkin qulash hayajonini uyg‘unlashtiradigan tajribada.",note:"إِثَارَةٌ — hayajon, qo‘zg‘alish."},
{num:42,time:"00:03:16,099 --> 00:03:22,099",arabic:"حَدِيقَةُ أَشِيكَاغَا لِلزُّهُورِ فِي قَلْبِ مُقَاطَعَةِ تُوتْشِيغِي",segs:[{ar:"حَدِيقَةُ أَشِيكَاغَا لِلزُّهُورِ",uz:"Ashikaga gullar bog‘i"},{ar:"فِي قَلْبِ مُقَاطَعَةِ تُوتْشِيغِي",uz:"Tochigi prefekturasining qalbida"}],full_uz:"Tochigi prefekturasining qalbidagi Ashikaga gullar bog‘i.",note:null},
{num:43,time:"00:03:22,099 --> 00:03:27,400",arabic:"تَتَوَارَى حَدِيقَةُ أَشِيكَاغَا كَتُحْفَةٍ نَبَاتِيَّةٍ نَادِرَةٍ",segs:[{ar:"تَتَوَارَى حَدِيقَةُ أَشِيكَاغَا",uz:"Ashikaga bog‘i yashirinib yotadi"},{ar:"كَتُحْفَةٍ نَبَاتِيَّةٍ نَادِرَةٍ",uz:"noyob botanika durdonasidek"}],full_uz:"Ashikaga bog‘i noyob botanika durdonasidek yashirinib yotadi.",note:"تَتَوَارَى — yashirinmoq, ko‘zdan panada bo‘lmoq."},
{num:44,time:"00:03:27,400 --> 00:03:33,219",arabic:"حَيْثُ يَلْتَقِي الْعِلْمُ بِالتَّارِيخِ وَتَزْدَهِرُ الدَّهْشَةُ فِي كُلِّ زَاوِيَةٍ",segs:[{ar:"حَيْثُ يَلْتَقِي الْعِلْمُ بِالتَّارِيخِ",uz:"ilm tarix bilan uchrashadigan joyda"},{ar:"وَتَزْدَهِرُ الدَّهْشَةُ فِي كُلِّ زَاوِيَةٍ",uz:"va hayrat har bir burchakda gullab-yashnaydi"}],full_uz:"U yerda ilm tarix bilan uchrashadi, hayrat esa har bir burchakda gullab-yashnaydi.",note:"تَزْدَهِرُ — gullamoq, rivojlanmoq."},
{num:45,time:"00:03:33,219 --> 00:03:42,460",arabic:"هُنَا تَمْتَدُّ أَشْجَارُ الْوِسْتَرِيَا الَّتِي يَزِيدُ عُمْرُهَا عَنْ مِائَةٍ وَخَمْسِينَ عَامًا",segs:[{ar:"هُنَا تَمْتَدُّ أَشْجَارُ الْوِسْتَرِيَا",uz:"bu yerda visteriya daraxtlari cho‘zilib yotadi"},{ar:"الَّتِي يَزِيدُ عُمْرُهَا عَنْ مِائَةٍ وَخَمْسِينَ عَامًا",uz:"yoshi bir yuz ellik yildan oshgan"}],full_uz:"Bu yerda yoshi bir yuz ellik yildan oshgan visteriya daraxtlari cho‘zilib yotadi.",note:"يَزِيدُ عَنْ — ...dan oshmoq."},
{num:46,time:"00:03:42,460 --> 00:03:49,099",arabic:"مُشَكِّلَةً أَنْفَاقًا حَيَّةً مِنَ الضَّوْءِ الْوَرْدِيِّ وَالْبَنَفْسَجِيِّ وَالْأَبْيَضِ",segs:[{ar:"مُشَكِّلَةً أَنْفَاقًا حَيَّةً",uz:"tirik yo‘laklarni hosil qilib"},{ar:"مِنَ الضَّوْءِ الْوَرْدِيِّ وَالْبَنَفْسَجِيِّ وَالْأَبْيَضِ",uz:"pushti, binafsha va oq nurdan"}],full_uz:"Pushti, binafsha va oq nurdan tirik yo‘laklarni hosil qilib.",note:"مُشَكِّلَةٌ — hosil qiluvchi, shakllantiruvchi."},
{num:47,time:"00:03:51,900 --> 00:03:59,300",arabic:"مَعَ كُلِّ رَبِيعٍ يُحَوِّلُ مَهْرَجَانُ الْوِسْتَرِيَا الْكَبِيرُ الْحَدِيقَةَ إِلَى مُتَاهَةٍ مُضِيئَةٍ",segs:[{ar:"مَعَ كُلِّ رَبِيعٍ",uz:"har bahor"},{ar:"يُحَوِّلُ مَهْرَجَانُ الْوِسْتَرِيَا الْكَبِيرُ الْحَدِيقَةَ",uz:"katta Visteriya festivali bog‘ni aylantiradi"},{ar:"إِلَى مُتَاهَةٍ مُضِيئَةٍ",uz:"yorqin labirintga"}],full_uz:"Har bahor katta Visteriya festivali bog‘ni yorqin labirintga aylantiradi.",note:"مُتَاهَةٌ — labirint."},
{num:48,time:"00:03:59,300 --> 00:04:04,860",arabic:"يَسِيرُ الزُّوَّارُ تَحْتَ أَزْهَارٍ مُتَدَلِّيَةٍ كَأَنَّهَا نُجُومٌ مُعَلَّقَةٌ",segs:[{ar:"يَسِيرُ الزُّوَّارُ",uz:"ziyoratchilar yuradilar"},{ar:"تَحْتَ أَزْهَارٍ مُتَدَلِّيَةٍ",uz:"osilib turgan gullar ostida"},{ar:"كَأَنَّهَا نُجُومٌ مُعَلَّقَةٌ",uz:"go‘yo osilib turgan yulduzlardek"}],full_uz:"Ziyoratchilar go‘yo osilib turgan yulduzlardek gullar ostida yuradilar.",note:null},
{num:49,time:"00:04:04,860 --> 00:04:12,560",arabic:"يَصِفُهَا الْجُغْرَافِيُّونَ بِأَنَّهَا مِنْ أَكْثَرِ الْمَمَرَّاتِ الزَّهْرِيَّةِ حَيَوِيَّةً عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"يَصِفُهَا الْجُغْرَافِيُّونَ",uz:"geograflar uni tasvirlaydilar"},{ar:"بِأَنَّهَا مِنْ أَكْثَرِ الْمَمَرَّاتِ الزَّهْرِيَّةِ حَيَوِيَّةً",uz:"eng jonli gulli yo‘laklardan biri sifatida"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzida"}],full_uz:"Geograflar uni yer yuzidagi eng jonli gulli yo‘laklardan biri deb tasvirlaydilar.",note:"حَيَوِيٌّ — jonli, hayotga boy."},
{num:50,time:"00:04:12,560 --> 00:04:16,360",arabic:"حَيْثُ يَتَحَوَّلُ اللَّوْنُ إِلَى تَضَارِيسَ",segs:null,full_uz:"U yerda rang relyefga aylanadi.",note:"تَضَارِيسٌ — relyef, yer shakllari."},
{num:51,time:"00:04:16,360 --> 00:04:24,740",arabic:"وَتُصْبِحُ كُلُّ خُطْوَةٍ عُبُورًا إِلَى حُلْمٍ نَسَجَتْهُ الطَّبِيعَةُ عَبْرَ الزَّمَنِ",segs:[{ar:"وَتُصْبِحُ كُلُّ خُطْوَةٍ عُبُورًا إِلَى حُلْمٍ",uz:"har bir qadam tushga o‘tishga aylanadi"},{ar:"نَسَجَتْهُ الطَّبِيعَةُ عَبْرَ الزَّمَنِ",uz:"uni tabiat vaqt davomida to‘qigan"}],full_uz:"Har bir qadam tabiat vaqt davomida to‘qigan tushga o‘tishga aylanadi.",note:"نَسَجَ — to‘qimoq."},
{num:52,time:"00:04:24,740 --> 00:04:30,460",arabic:"مُنْتَزَهُ جِيُوشَايْكُو الْوَطَنِيُّ",segs:null,full_uz:"Jiuzhaigou milliy bog‘i.",note:null},
{num:53,time:"00:04:30,460 --> 00:04:35,079",arabic:"تَشَكَّلَ مُنْتَزَهُ جِيُوشَايْكُو عَلَى مَدَى آلَافِ السِّنِينَ",segs:[{ar:"تَشَكَّلَ مُنْتَزَهُ جِيُوشَايْكُو",uz:"Jiuzhaigou bog‘i shakllangan"},{ar:"عَلَى مَدَى آلَافِ السِّنِينَ",uz:"minglab yillar davomida"}],full_uz:"Jiuzhaigou bog‘i minglab yillar davomida shakllangan.",note:"تَشَكَّلَ — shakllanmoq."},
{num:54,time:"00:04:35,079 --> 00:04:40,180",arabic:"بِفِعْلِ الْحَرَكَاتِ التَّكْتُونِيَّةِ وَالتَّرَسُّبَاتِ الْغَنِيَّةِ بِالْكَالْسِيُومِ",segs:[{ar:"بِفِعْلِ الْحَرَكَاتِ التَّكْتُونِيَّةِ",uz:"tektonik harakatlar ta’sirida"},{ar:"وَالتَّرَسُّبَاتِ الْغَنِيَّةِ بِالْكَالْسِيُومِ",uz:"va kalsiyga boy cho‘kindilar bilan"}],full_uz:"Tektonik harakatlar va kalsiyga boy cho‘kindilar ta’sirida.",note:"تَرَسُّبَاتٌ — cho‘kindilar. تَكْتُونِيٌّ — tektonik."},
{num:55,time:"00:04:40,180 --> 00:04:45,759",arabic:"لِيَغْدُوَ أَحَدَ أَكْثَرِ الْمَشَاهِدِ الْجِيُولُوجِيَّةِ غَرَابَةً عَلَى الْأَرْضِ",segs:[{ar:"لِيَغْدُوَ أَحَدَ أَكْثَرِ الْمَشَاهِدِ الْجِيُولُوجِيَّةِ",uz:"eng g‘alati geologik manzaralardan biriga aylanish uchun"},{ar:"غَرَابَةً عَلَى الْأَرْضِ",uz:"yer yuzidagi g‘ayrioddiylardan"}],full_uz:"Yer yuzidagi eng g‘ayrioddiy geologik manzaralardan biriga aylangan.",note:"غَرَابَةٌ — g‘ayrioddiylik, g‘alatilık."},
{num:56,time:"00:04:45,759 --> 00:04:54,420",arabic:"أَكْثَرُ مِنْ مِائَةِ بُحَيْرَةٍ فِيرُوزِيَّةٍ تَنْتَشِرُ عَبْرَ الْوَادِي",segs:[{ar:"أَكْثَرُ مِنْ مِائَةِ بُحَيْرَةٍ فِيرُوزِيَّةٍ",uz:"yuzdan ortiq feruza rangli ko‘llar"},{ar:"تَنْتَشِرُ عَبْرَ الْوَادِي",uz:"vodiy bo‘ylab tarqalgan"}],full_uz:"Yuzdan ortiq feruza rangli ko‘l vodiy bo‘ylab tarqalgan.",note:"بُحَيْرَةٌ — ko‘l."},
{num:57,time:"00:04:54,420 --> 00:05:02,160",arabic:"تَتَلَوَّنُ بِدَرَجَاتِ الْأَزْرَقِ وَالْأَخْضَرِ نَتِيجَةَ الْمَعَادِنِ وَالطَّحَالِبِ الْمُعَلَّقَةِ",segs:[{ar:"تَتَلَوَّنُ بِدَرَجَاتِ الْأَزْرَقِ وَالْأَخْضَرِ",uz:"ko‘k va yashil tuslarga kiradi"},{ar:"نَتِيجَةَ الْمَعَادِنِ وَالطَّحَالِبِ الْمُعَلَّقَةِ",uz:"minerallar va muallaq suv o‘tlari sababli"}],full_uz:"Minerallar va muallaq suv o‘tlari sababli ko‘k va yashil tuslarga kiradi.",note:"طَحَالِبُ — suv o‘tlari, algalar. مُعَلَّقٌ — muallaq, osilib turgan."},
{num:58,time:"00:05:02,160 --> 00:05:05,160",arabic:"الَّتِي تَعْكِسُ ضَوْءَ الشَّمْسِ",segs:null,full_uz:"Quyosh nurini aks ettiradigan.",note:null},
{num:59,time:"00:05:05,160 --> 00:05:11,120",arabic:"تَتَدَفَّقُ عَشَرَاتُ الشَّلَّالَاتِ مِنْ طَبَقَةٍ إِلَى أُخْرَى",segs:[{ar:"تَتَدَفَّقُ عَشَرَاتُ الشَّلَّالَاتِ",uz:"o‘nlab sharsharalar oqib tushadi"},{ar:"مِنْ طَبَقَةٍ إِلَى أُخْرَى",uz:"bir pog‘onadan boshqasiga"}],full_uz:"O‘nlab sharsharalar bir pog‘onadan boshqasiga oqib tushadi.",note:"تَتَدَفَّقُ — oqib kelmoq, oqib tushmoq."},
{num:60,time:"00:05:11,120 --> 00:05:15,819",arabic:"مِنْ بَيْنِهَا شَلَّالٌ بِعَرْضٍ يُقَارِبُ خَمْسَةً وَأَرْبَعِينَ مِتْرًا",segs:[{ar:"مِنْ بَيْنِهَا شَلَّالٌ",uz:"ular orasida bir sharshara bor"},{ar:"بِعَرْضٍ يُقَارِبُ خَمْسَةً وَأَرْبَعِينَ مِتْرًا",uz:"eni qariyb qirq besh metr bo‘lgan"}],full_uz:"Ular orasida eni qariyb qirq besh metr bo‘lgan bir sharshara bor.",note:"عَرْضٌ — en, kenglik."},
{num:61,time:"00:05:15,819 --> 00:05:22,160",arabic:"تُحِيطُ بِهِ قِمَمٌ تَتَجَاوَزُ أَرْبَعَةَ آلَافٍ وَمِائَتَيْ مِتْرٍ ارْتِفَاعًا",segs:[{ar:"تُحِيطُ بِهِ قِمَمٌ",uz:"uni cho‘qqilar o‘rab turadi"},{ar:"تَتَجَاوَزُ أَرْبَعَةَ آلَافٍ وَمِائَتَيْ مِتْرٍ",uz:"to‘rt ming ikki yuz metrdan oshadigan"},{ar:"ارْتِفَاعًا",uz:"balandlikda"}],full_uz:"Uni balandligi to‘rt ming ikki yuz metrdan oshadigan cho‘qqilar o‘rab turadi.",note:"تَجَاوَزَ — oshib ketmoq."},
{num:62,time:"00:05:22,160 --> 00:05:27,500",arabic:"وَيَتَدَرَّجُ مُنَاخُهُ بَيْنَ بُرُودَةِ الْمُرْتَفَعَاتِ وَاعْتِدَالِ الْغَابَاتِ",segs:[{ar:"وَيَتَدَرَّجُ مُنَاخُهُ",uz:"uning iqlimi bosqichma-bosqich o‘zgaradi"},{ar:"بَيْنَ بُرُودَةِ الْمُرْتَفَعَاتِ",uz:"balandliklarning sovuqligi bilan"},{ar:"وَاعْتِدَالِ الْغَابَاتِ",uz:"o‘rmonlarning mo‘tadilligi o‘rtasida"}],full_uz:"Uning iqlimi balandliklarning sovuqligi bilan o‘rmonlarning mo‘tadilligi o‘rtasida o‘zgarib turadi.",note:"يَتَدَرَّجُ — bosqichma-bosqich o‘zgaradi. اعْتِدَالٌ — mo‘tadillik."},
{num:63,time:"00:05:27,500 --> 00:05:38,900",arabic:"كُلُّ نُقْطَةِ مُشَاهَدَةٍ تَكْشِفُ مَشْهَدًا يَبْدُو كَلَوْحَةٍ فَنِّيَّةٍ",segs:[{ar:"كُلُّ نُقْطَةِ مُشَاهَدَةٍ",uz:"har bir kuzatuv nuqtasi"},{ar:"تَكْشِفُ مَشْهَدًا",uz:"bir manzarani ochib beradi"},{ar:"يَبْدُو كَلَوْحَةٍ فَنِّيَّةٍ",uz:"san’at asaridek ko‘rinadigan"}],full_uz:"Har bir kuzatuv nuqtasi san’at asaridek ko‘rinadigan bir manzarani ochib beradi.",note:"نُقْطَةُ مُشَاهَدَةٍ — kuzatuv nuqtasi, tomosha joyi."},
{num:64,time:"00:05:38,900 --> 00:05:40,840",arabic:"مِيَاهٌ صَافِيَةٌ",segs:null,full_uz:"Tiniq suvlar.",note:null},
{num:65,time:"00:05:40,840 --> 00:05:44,960",arabic:"شَلَّالَاتٌ مُتَلَأْلِئَةٌ",segs:null,full_uz:"Yaltiragan sharsharalar.",note:"مُتَلَأْلِئٌ — yaltiragan, yarqiragan."},
{num:66,time:"00:05:44,960 --> 00:05:48,340",arabic:"وَانْعِكَاسَاتٌ تَشَكَّلَتْ عَبْرَ آلَافِ السِّنِينَ",segs:[{ar:"وَانْعِكَاسَاتٌ",uz:"va akslar"},{ar:"تَشَكَّلَتْ عَبْرَ آلَافِ السِّنِينَ",uz:"minglab yillar davomida shakllangan"}],full_uz:"Va minglab yillar davomida shakllangan akslar.",note:"انْعِكَاسٌ — aks, akslanish."},
{num:67,time:"00:05:48,339 --> 00:05:52,759",arabic:"لِتَكُونَ تُحْفَةً طَبِيعِيَّةً يَصْعُبُ تَصْدِيقُهَا",segs:[{ar:"لِتَكُونَ تُحْفَةً طَبِيعِيَّةً",uz:"tabiiy durdonaga aylanishi uchun"},{ar:"يَصْعُبُ تَصْدِيقُهَا",uz:"unga ishonish qiyin"}],full_uz:"Unga ishonish qiyin bo‘lgan tabiiy durdonaga aylanishi uchun.",note:"تُحْفَةٌ — durdona, noyob asar."},
{num:68,time:"00:05:52,759 --> 00:05:57,539",arabic:"مُورِينْ فِي سُوِيسْرَا",segs:null,full_uz:"Shveytsariyadagi Myurren.",note:null},
{num:69,time:"00:05:57,539 --> 00:06:01,439",arabic:"تَقَعُ مُورِينْ عَلَى شُرْفَةٍ أَلْبِيَّةٍ شَاهِقَةٍ",segs:[{ar:"تَقَعُ مُورِينْ",uz:"Myurren joylashgan"},{ar:"عَلَى شُرْفَةٍ أَلْبِيَّةٍ شَاهِقَةٍ",uz:"baland Alp balkonida"}],full_uz:"Myurren baland Alp balkonida joylashgan.",note:"شُرْفَةٌ — ayvon, balkon."},
{num:70,time:"00:06:01,439 --> 00:06:05,079",arabic:"عَلَى ارْتِفَاعٍ يَزِيدُ عَنْ أَلْفٍ وَسِتِّمِائَةِ مِتْرٍ",segs:[{ar:"عَلَى ارْتِفَاعٍ",uz:"balandlikda"},{ar:"يَزِيدُ عَنْ أَلْفٍ وَسِتِّمِائَةِ مِتْرٍ",uz:"ming olti yuz metrdan oshadigan"}],full_uz:"Ming olti yuz metrdan oshadigan balandlikda.",note:null},
{num:71,time:"00:06:05,079 --> 00:06:07,419",arabic:"فَوْقَ مُسْتَوَى سَطْحِ الْبَحْرِ",segs:null,full_uz:"Dengiz sathidan yuqorida.",note:"مُسْتَوَى سَطْحِ الْبَحْرِ — dengiz sathi."},
{num:72,time:"00:06:07,419 --> 00:06:12,019",arabic:"فِي قَلْبِ مِنْطَقَةِ الْأُوبَرْلَانْدِ الْبِرْنِيَّةِ السُّوِيسْرِيَّةِ",segs:[{ar:"فِي قَلْبِ مِنْطَقَةِ الْأُوبَرْلَانْدِ الْبِرْنِيَّةِ",uz:"Bern Oberland hududining qalbida"},{ar:"السُّوِيسْرِيَّةِ",uz:"Shveytsariyadagi"}],full_uz:"Shveytsariyadagi Bern Oberland hududining qalbida.",note:null},
{num:73,time:"00:06:12,019 --> 00:06:21,799",arabic:"هِيَ قَرْيَةٌ صَاغَتْهَا قُوَى الرَّفْعِ الْجِيُولُوجِيِّ وَنَحْتُ الْعُصُورِ الْجَلِيدِيَّةِ مَعًا",segs:[{ar:"هِيَ قَرْيَةٌ",uz:"u bir qishloq"},{ar:"صَاغَتْهَا قُوَى الرَّفْعِ الْجِيُولُوجِيِّ",uz:"uni geologik ko‘tarilish kuchlari shakllantirgan"},{ar:"وَنَحْتُ الْعُصُورِ الْجَلِيدِيَّةِ مَعًا",uz:"va muzlik davrlarining yemirilishi birgalikda"}],full_uz:"U geologik ko‘tarilish kuchlari va muzlik davrlarining yemirilishi birgalikda shakllantirgan qishloqdir.",note:"نَحْتٌ — o‘yilish, yemirilish orqali shakllanish."},
{num:74,time:"00:06:21,799 --> 00:06:29,719",arabic:"تَشَكَّلَتْ مَنْصَّتُهَا الصَّخْرِيَّةُ مَعَ تَرَاجُعِ الْأَنْهَارِ الْجَلِيدِيَّةِ قَبْلَ نَحْوِ أَحَدَ عَشَرَ أَلْفَ عَامٍ",segs:[{ar:"تَشَكَّلَتْ مَنْصَّتُهَا الصَّخْرِيَّةُ",uz:"uning tosh platformasi shakllangan"},{ar:"مَعَ تَرَاجُعِ الْأَنْهَارِ الْجَلِيدِيَّةِ",uz:"muzliklarning chekinishi bilan"},{ar:"قَبْلَ نَحْوِ أَحَدَ عَشَرَ أَلْفَ عَامٍ",uz:"taxminan o‘n bir ming yil oldin"}],full_uz:"Uning tosh platformasi muzliklar chekinishi bilan taxminan o‘n bir ming yil oldin shakllangan.",note:"تَرَاجَعَ — chekinmoq."},
{num:75,time:"00:06:29,719 --> 00:06:39,359",arabic:"تَارِكَةً حَافَّةً ضَيِّقَةً دِرَامِيَّةً تُطِلُّ مُبَاشَرَةً عَلَى قِمَمِ إِيغَرَ وَمُونْشِ وَيُونْغْفْرَاوَ الْأُسْطُورِيَّةِ",segs:[{ar:"تَارِكَةً حَافَّةً ضَيِّقَةً دِرَامِيَّةً",uz:"ta’sirchan tor bir qirni qoldirib"},{ar:"تُطِلُّ مُبَاشَرَةً عَلَى قِمَمِ إِيغَرَ وَمُونْشِ وَيُونْغْفْرَاوَ",uz:"Eiger, Mönch va Jungfrau cho‘qqilariga to‘g‘ridan-to‘g‘ri qaraydigan"},{ar:"الْأُسْطُورِيَّةِ",uz:"afsonaviy"}],full_uz:"Eiger, Mönch va Jungfrau afsonaviy cho‘qqilariga to‘g‘ridan-to‘g‘ri qaraydigan ta’sirchan tor bir qirni qoldirib.",note:"حَافَّةٌ — chekka, qir."},
{num:76,time:"00:06:39,360 --> 00:06:48,920",arabic:"تَتَشَبَّثُ الشَّالِيهَاتُ الْخَشَبِيَّةُ الَّتِي يَعُودُ بَعْضُهَا لِأَكْثَرَ مِنْ مِائَتَيْ عَامٍ",segs:[{ar:"تَتَشَبَّثُ الشَّالِيهَاتُ الْخَشَبِيَّةُ",uz:"yog‘och shalelar mahkam yopishib turadi"},{ar:"الَّتِي يَعُودُ بَعْضُهَا لِأَكْثَرَ مِنْ مِائَتَيْ عَامٍ",uz:"ba’zilarining yoshi ikki yuz yildan oshgan"}],full_uz:"Ba’zilarining yoshi ikki yuz yildan oshgan yog‘och shalelar mahkam yopishib turadi.",note:"شَالِيهٌ — Alp uslubidagi yog‘och uy."},
{num:77,time:"00:06:48,920 --> 00:06:53,160",arabic:"وَالْمَبْنِيَّةُ بِتَقْنِيَاتِ الْإِطَارِ الْخَشَبِيِّ التَّقْلِيدِيِّ",segs:null,full_uz:"Va an’anaviy yog‘och karkas usulida qurilgan.",note:"تَقْنِيَاتٌ — texnikalar, usullar."},
{num:78,time:"00:06:53,160 --> 00:06:59,139",arabic:"بِجَانِبِ الْجُرْفِ كَأَنَّهَا مُتْحَفٌ حَيٌّ لِلْعِمَارَةِ الْأَلْبِيَّةِ",segs:[{ar:"بِجَانِبِ الْجُرْفِ",uz:"jarlik yonida"},{ar:"كَأَنَّهَا مُتْحَفٌ حَيٌّ",uz:"go‘yo tirik muzeydek"},{ar:"لِلْعِمَارَةِ الْأَلْبِيَّةِ",uz:"Alp me’morchiligi uchun"}],full_uz:"Jarlik yonida go‘yo Alp me’morchiligining tirik muzeyidek.",note:"الْجُرْفُ — jarlik, tik qoya."},
{num:79,time:"00:06:59,139 --> 00:07:02,460",arabic:"لَا وُجُودَ لِلسَّيَّارَاتِ هُنَا",segs:null,full_uz:"Bu yerda mashinalar yo‘q.",note:null},
{num:80,time:"00:07:02,459 --> 00:07:14,599",arabic:"فَالتَّنَقُّلُ يَتِمُّ سَيْرًا عَلَى الْأَقْدَامِ عَبْرَ مَمَرَّاتٍ تَتَلَوَّى عَلَى مُنْحَدَرَاتٍ تَهْبِطُ قَرَابَةَ سِتِّمِائَةِ مِتْرٍ نَحْوَ الْوَادِي السَّحِيقِ",segs:[{ar:"فَالتَّنَقُّلُ يَتِمُّ سَيْرًا عَلَى الْأَقْدَامِ",uz:"shuning uchun harakat piyoda amalga oshiriladi"},{ar:"عَبْرَ مَمَرَّاتٍ تَتَلَوَّى عَلَى مُنْحَدَرَاتٍ",uz:"yonbag‘irlarda egri-bugri yo‘laklar orqali"},{ar:"تَهْبِطُ قَرَابَةَ سِتِّمِائَةِ مِتْرٍ",uz:"qariyb olti yuz metr pastga tushadigan"},{ar:"نَحْوَ الْوَادِي السَّحِيقِ",uz:"chuqur vodiy tomon"}],full_uz:"Shuning uchun harakat piyoda amalga oshiriladi: qariyb olti yuz metr pastga, chuqur vodiy tomon tushadigan yonbag‘irlardagi egri-bugri yo‘laklar orqali.",note:"التَّنَقُّلُ — harakatlanish. تَتَلَوَّى — egri-bugri bo‘lib cho‘zilmoq."},
{num:81,time:"00:07:14,599 --> 00:07:24,819",arabic:"يَمْتَزِجُ فِي مُورِينْ عَبَقُ الْجِيُولُوجْيَا الْقَدِيمَةِ مَعَ هُدُوءِ الْحِرْفَةِ الْبَشَرِيَّةِ وَجَلَالِ الْجُدْرَانِ الْجَبَلِيَّةِ",segs:[{ar:"يَمْتَزِجُ فِي مُورِينْ عَبَقُ الْجِيُولُوجْيَا الْقَدِيمَةِ",uz:"Myurrenda qadimiy geologiyaning nafasi qorishadi"},{ar:"مَعَ هُدُوءِ الْحِرْفَةِ الْبَشَرِيَّةِ",uz:"inson mehnatining sokinligi bilan"},{ar:"وَجَلَالِ الْجُدْرَانِ الْجَبَلِيَّةِ",uz:"va tog‘ devorlarining ulug‘vorligi bilan"}],full_uz:"Myurrenda qadimiy geologiyaning nafasi inson mehnatining sokinligi va tog‘ devorlarining ulug‘vorligi bilan qorishadi.",note:"عَبَقٌ — ifor, o‘ziga xos kuchli hid; bu yerda majozan qadimiylik nafasi."},
{num:82,time:"00:07:26,439 --> 00:07:30,819",arabic:"فَتَبْدُو كَمَنْصَّةٍ مُعَلَّقَةٍ بَيْنَ الْأَرْضِ وَالسَّمَاءِ",segs:[{ar:"فَتَبْدُو كَمَنْصَّةٍ مُعَلَّقَةٍ",uz:"shunda u muallaq platformadek ko‘rinadi"},{ar:"بَيْنَ الْأَرْضِ وَالسَّمَاءِ",uz:"yer va osmon orasida"}],full_uz:"Shunda u yer va osmon orasida muallaq turgan platformadek ko‘rinadi.",note:null},
{num:83,time:"00:07:30,819 --> 00:07:39,000",arabic:"بُحَيْرَةُ بَاك",segs:null,full_uz:"Bak ko‘li.",note:null},
{num:84,time:"00:07:39,000 --> 00:07:43,500",arabic:"مُخْتَبِئَةٌ عَالِيًا دَاخِلَ حَوْضٍ جَبَلِيٍّ مُنْعَزِلٍ",segs:[{ar:"مُخْتَبِئَةٌ عَالِيًا",uz:"balandda yashirinib yotgan"},{ar:"دَاخِلَ حَوْضٍ جَبَلِيٍّ مُنْعَزِلٍ",uz:"yolg‘iz tog‘ havzasi ichida"}],full_uz:"Yolg‘iz tog‘ havzasi ichida balandda yashirinib yotgan.",note:"مُخْتَبِئٌ — yashirinib turgan."},
{num:85,time:"00:07:43,500 --> 00:07:52,839",arabic:"تَتَلَأْلَأُ بُحَيْرَةُ بَيْسُوبُوكَ كَجَوْهَرَةٍ جِيُولُوجِيَّةٍ تَشَكَّلَتْ عَلَى مَدَى مَا يُقَارِبُ عَشَرَةَ آلَافِ عَامٍ",segs:[{ar:"تَتَلَأْلَأُ بُحَيْرَةُ بَيْسُوبُوكَ",uz:"Bisobok ko‘li yaltiraydi"},{ar:"كَجَوْهَرَةٍ جِيُولُوجِيَّةٍ",uz:"geologik gavhardek"},{ar:"تَشَكَّلَتْ عَلَى مَدَى مَا يُقَارِبُ عَشَرَةَ آلَافِ عَامٍ",uz:"qariyb o‘n ming yil davomida shakllangan"}],full_uz:"Bisobok ko‘li qariyb o‘n ming yil davomida shakllangan geologik gavhardek yaltiraydi.",note:"جَوْهَرَةٌ — javohir, gavhar."},
{num:86,time:"00:07:52,839 --> 00:07:59,759",arabic:"تَمْتَدُّ الْبُحَيْرَةُ لِنَحْوِ مِائَةٍ وَعَشَرَةِ أَمْتَارٍ عَرْضًا",segs:[{ar:"تَمْتَدُّ الْبُحَيْرَةُ",uz:"ko‘l cho‘zilib yotadi"},{ar:"لِنَحْوِ مِائَةٍ وَعَشَرَةِ أَمْتَارٍ عَرْضًا",uz:"eni taxminan bir yuz o‘n metr"}],full_uz:"Ko‘lning eni taxminan bir yuz o‘n metr.",note:null},
{num:87,time:"00:07:59,759 --> 00:08:02,959",arabic:"وَتَتَمَيَّزُ بِمِيَاهٍ فِي غَايَةِ الصَّفَاءِ",segs:[{ar:"وَتَتَمَيَّزُ بِمِيَاهٍ",uz:"va u ... suvlari bilan ajralib turadi"},{ar:"فِي غَايَةِ الصَّفَاءِ",uz:"nihoyatda tiniq"}],full_uz:"Va u nihoyatda tiniq suvlari bilan ajralib turadi.",note:"تَتَمَيَّزُ بِـ — ... bilan ajralib turmoq."},
{num:88,time:"00:08:02,959 --> 00:08:08,579",arabic:"حَتَّى إِنَّ عُلَمَاءَ الْأَحْيَاءِ يُؤَكِّدُونَ أَنَّ الرُّؤْيَةَ فِيهَا",segs:[{ar:"حَتَّى إِنَّ عُلَمَاءَ الْأَحْيَاءِ يُؤَكِّدُونَ",uz:"hatto biologlar ta’kidlaydilar"},{ar:"أَنَّ الرُّؤْيَةَ فِيهَا",uz:"unda ko‘rish"}],full_uz:"Hatto biologlar undagi ko‘rish imkoniyati...",note:"يُؤَكِّدُ — ta’kidlamoq."},
{num:89,time:"00:08:08,579 --> 00:08:11,819",arabic:"تَتَجَاوَزُ تِسْعَةَ أَمْتَارٍ عُمْقًا",segs:null,full_uz:"Chuqurlikda to‘qqiz metrdan oshishini ta’kidlaydilar.",note:"تَتَجَاوَزُ — oshib ketmoq."},
{num:90,time:"00:08:11,819 --> 00:08:18,719",arabic:"تَتَغَذَّى مِنْ يَنَابِيعَ غَنِيَّةٍ بِالْمَعَادِنِ",segs:[{ar:"تَتَغَذَّى مِنْ يَنَابِيعَ",uz:"u buloqlardan oziqlanadi"},{ar:"غَنِيَّةٍ بِالْمَعَادِنِ",uz:"minerallarga boy"}],full_uz:"U minerallarga boy buloqlardan oziqlanadi.",note:"تَتَغَذَّى مِنْ — ...dan oziqlanmoq."},
{num:91,time:"00:08:18,719 --> 00:08:25,819",arabic:"فَيَنْعَكِسُ عَلَى سَطْحِهَا مَشْهَدُ الْجُرُوفِ الصَّخْرِيَّةِ الْمُحِيطَةِ كَمِرْآةٍ مَصْقُولَةٍ",segs:[{ar:"فَيَنْعَكِسُ عَلَى سَطْحِهَا",uz:"shunda uning yuzasida aks etadi"},{ar:"مَشْهَدُ الْجُرُوفِ الصَّخْرِيَّةِ الْمُحِيطَةِ",uz:"atrofidagi qoyali jarliklar manzarasi"},{ar:"كَمِرْآةٍ مَصْقُولَةٍ",uz:"sayqallangan ko‘zgudek"}],full_uz:"Shunda uning yuzasida atrofidagi qoyali jarliklar manzarasi sayqallangan ko‘zgudek aks etadi.",note:"مَصْقُولٌ — sayqallangan."},
{num:92,time:"00:08:25,819 --> 00:08:33,460",arabic:"فِي فَصْلِ الصَّيْفِ تَنْسَابُ قَوَارِبُ الْأَزْوَاجِ بِهُدُوءٍ فَوْقَ زُرْقَةِ الْمَاءِ",segs:[{ar:"فِي فَصْلِ الصَّيْفِ",uz:"yoz faslida"},{ar:"تَنْسَابُ قَوَارِبُ الْأَزْوَاجِ",uz:"juftliklarning qayiqlari ravon suzadi"},{ar:"بِهُدُوءٍ فَوْقَ زُرْقَةِ الْمَاءِ",uz:"suvning moviyligi ustida sokinlik bilan"}],full_uz:"Yoz faslida juftliklarning qayiqlari suvning moviyligi ustida sokinlik bilan ravon suzadi.",note:null},
{num:93,time:"00:08:33,460 --> 00:08:38,740",arabic:"يَسْتَكْشِفُونَ مَنَاطِقَ دَافِئَةً ضَحْلَةً وَأُخْرَى بَارِدَةً أَعْمَقَ",segs:[{ar:"يَسْتَكْشِفُونَ مَنَاطِقَ دَافِئَةً ضَحْلَةً",uz:"ular iliq, sayoz hududlarni o‘rganadilar"},{ar:"وَأُخْرَى بَارِدَةً أَعْمَقَ",uz:"va boshqa sovuqroq, chuqurroq hududlarni"}],full_uz:"Ular iliq, sayoz hududlar va boshqa sovuqroq, chuqurroq hududlarni o‘rganadilar.",note:"ضَحْلٌ — sayoz."},
{num:94,time:"00:08:38,740 --> 00:08:42,259",arabic:"صَنَعَتْهَا تَيَّارَاتٌ جَبَلِيَّةٌ مُتَغَيِّرَةٌ",segs:[{ar:"صَنَعَتْهَا",uz:"ularni hosil qilgan"},{ar:"تَيَّارَاتٌ جَبَلِيَّةٌ مُتَغَيِّرَةٌ",uz:"o‘zgaruvchan tog‘ oqimlari"}],full_uz:"Ularni o‘zgaruvchan tog‘ oqimlari hosil qilgan.",note:"تَيَّارٌ — oqim."},
{num:95,time:"00:08:42,259 --> 00:08:49,439",arabic:"يُحِيطُ بِالْمَشْهَدِ صُخُورٌ مَكْسُوَّةٌ بِالطَّحَالِبِ وَضَبَابٌ صَبَاحِيٌّ خَفِيفٌ",segs:[{ar:"يُحِيطُ بِالْمَشْهَدِ صُخُورٌ مَكْسُوَّةٌ بِالطَّحَالِبِ",uz:"manzarani suv o‘tlari bilan qoplangan qoyalar o‘rab turadi"},{ar:"وَضَبَابٌ صَبَاحِيٌّ خَفِيفٌ",uz:"va yengil tonggi tuman"}],full_uz:"Manzarani suv o‘tlari bilan qoplangan qoyalar va yengil tonggi tuman o‘rab turadi.",note:"مَكْسُوٌّ بِـ — ... bilan qoplangan."},
{num:96,time:"00:08:49,439 --> 00:08:55,439",arabic:"فَيَتَحَوَّلُ الْمَكَانُ إِلَى لَوْحَةٍ تَبْدُو وَكَأَنَّهَا مَرْسُومَةٌ بِعِنَايَةٍ",segs:[{ar:"فَيَتَحَوَّلُ الْمَكَانُ إِلَى لَوْحَةٍ",uz:"shunda joy bir manzaraga aylanadi"},{ar:"تَبْدُو وَكَأَنَّهَا مَرْسُومَةٌ بِعِنَايَةٍ",uz:"go‘yo ehtiyotkorlik bilan chizilgandek ko‘rinadigan"}],full_uz:"Shunda bu joy go‘yo nihoyatda e’tibor bilan chizilgandek ko‘rinadigan bir manzaraga aylanadi.",note:"بِعِنَايَةٍ — e’tibor bilan, puxtalik bilan."},
{num:97,time:"00:08:55,440 --> 00:08:59,500",arabic:"لَيْسَتْ بَيْسُوبُوكُ مُجَرَّدَ وِجْهَةٍ",segs:[{ar:"لَيْسَتْ بَيْسُوبُوكُ",uz:"Bisobok shunchaki"},{ar:"مُجَرَّدَ وِجْهَةٍ",uz:"manzil emas"}],full_uz:"Bisobok shunchaki sayohat manzili emas.",note:"وِجْهَةٌ — manzil, yo‘nalish."},
{num:98,time:"00:08:59,500 --> 00:09:04,220",arabic:"بَلْ بَقَايَا حَيَّةٌ هَادِئَةٌ لِقُوَى الْأَرْضِ الْقَدِيمَةِ",segs:[{ar:"بَلْ بَقَايَا حَيَّةٌ هَادِئَةٌ",uz:"balki sokin tirik qoldiq"},{ar:"لِقُوَى الْأَرْضِ الْقَدِيمَةِ",uz:"qadimiy yer kuchlarining"}],full_uz:"Balki qadimiy yer kuchlarining sokin, tirik qoldig‘idir.",note:"بَقَايَا — qoldiqlar."},
{num:99,time:"00:09:04,220 --> 00:09:09,220",arabic:"تَدْعُو الزَّائِرَ إِلَى عَالَمٍ يَلْتَقِي فِيهِ الْعِلْمُ وَالسَّكِينَةُ",segs:[{ar:"تَدْعُو الزَّائِرَ إِلَى عَالَمٍ",uz:"ziyokorni bir olamga chorlaydi"},{ar:"يَلْتَقِي فِيهِ الْعِلْمُ وَالسَّكِينَةُ",uz:"unda ilm va sokinlik uchrashadigan"}],full_uz:"Ziyokorni ilm va sokinlik uchrashadigan bir olamga chorlaydi.",note:"تَدْعُو — chorlamoq, da’vat qilmoq."},
{num:100,time:"00:09:09,220 --> 00:09:11,500",arabic:"وَلَمْسَةً مِنَ الرُّومَانْسِيَّةِ",segs:null,full_uz:"Va ozgina romantika.",note:"لَمْسَةٌ — tegish, bir chimdim, nozik unsur."},
{num:101,time:"00:09:11,500 --> 00:09:19,000",arabic:"يَرْتَفِعُ جَبَلُ يَانْدَانْغَ أَكْثَرَ مِنْ ثَمَانِمِائَةِ مِتْرٍ فَوْقَ سَهْلِ شَرْقِ الصِّينِ",segs:[{ar:"يَرْتَفِعُ جَبَلُ يَانْدَانْغَ",uz:"Yandang tog‘i ko‘tariladi"},{ar:"أَكْثَرَ مِنْ ثَمَانِمِائَةِ مِتْرٍ",uz:"sakkiz yuz metrdan ortiq"},{ar:"فَوْقَ سَهْلِ شَرْقِ الصِّينِ",uz:"Sharqiy Xitoy tekisligidan"}],full_uz:"Yandang tog‘i Sharqiy Xitoy tekisligidan sakkiz yuz metrdan ortiq baland ko‘tariladi.",note:null},
{num:102,time:"00:09:19,000 --> 00:09:25,020",arabic:"وَيُعَدُّ تُحْفَةً جِيُولُوجِيَّةً تَشَكَّلَتْ خِلَالَ الْعَصْرِ الطَّبَاشِيرِيِّ",segs:[{ar:"وَيُعَدُّ تُحْفَةً جِيُولُوجِيَّةً",uz:"u geologik durdona hisoblanadi"},{ar:"تَشَكَّلَتْ خِلَالَ الْعَصْرِ الطَّبَاشِيرِيِّ",uz:"bo‘r davrida shakllangan"}],full_uz:"U bo‘r davrida shakllangan geologik durdona hisoblanadi.",note:"الْعَصْرُ الطَّبَاشِيرِيُّ — bo‘r davri."},
{num:103,time:"00:09:25,019 --> 00:09:27,960",arabic:"قَبْلَ أَكْثَرَ مِنْ سَبْعِينَ مِلْيُونَ سَنَةٍ",segs:null,full_uz:"Yetmish million yildan ko‘proq oldin.",note:null},
{num:104,time:"00:09:27,960 --> 00:09:33,019",arabic:"مُنْحَدَرَاتُهُ الْحَادَّةُ وَقِمَمُهُ الْمُسَنَّنَةُ",segs:null,full_uz:"Uning o‘tkir yonbag‘irlari va tishsimon cho‘qqilari.",note:"مُسَنَّنٌ — tishsimon, arrasimon."},
{num:105,time:"00:09:33,019 --> 00:09:35,600",arabic:"الْمَنْحُوتَةُ مِنْ صُخُورٍ بَرْكَانِيَّةٍ",segs:null,full_uz:"Vulqon jinslaridan o‘yilgan.",note:"مَنْحُوتٌ — o‘yilgan."},
{num:106,time:"00:09:35,600 --> 00:09:41,179",arabic:"تَرْسُمُ وَاحِدًا مِنْ أَكْثَرِ الْمَشَاهِدِ الطَّبِيعِيَّةِ دِرَامِيَّةً عَلَى الْأَرْضِ",segs:[{ar:"تَرْسُمُ وَاحِدًا مِنْ أَكْثَرِ الْمَشَاهِدِ الطَّبِيعِيَّةِ",uz:"tabiatning eng ta’sirchan manzaralaridan birini chizadi"},{ar:"دِرَامِيَّةً عَلَى الْأَرْضِ",uz:"yer yuzidagi"}],full_uz:"Yer yuzidagi tabiatning eng ta’sirchan manzaralaridan birini hosil qiladi.",note:"دِرَامِيٌّ — dramatik, ta’sirchan."},
{num:107,time:"00:09:41,179 --> 00:09:44,699",arabic:"مَسَارُ الْفِيرَاتَةِ فِي الْجَبَلِ",segs:[{ar:"مَسَارُ الْفِيرَاتَةِ",uz:"Via ferrata yo‘li"},{ar:"فِي الْجَبَلِ",uz:"tog‘dagi"}],full_uz:"Tog‘dagi Via ferrata yo‘li.",note:null},
{num:108,time:"00:09:44,699 --> 00:09:49,679",arabic:"يَمْنَحُ الْمُغَامِرِينَ طَرِيقًا مُعَلَّقًا عَلَى الْجُدْرَانِ الْعَمُودِيَّةِ",segs:[{ar:"يَمْنَحُ الْمُغَامِرِينَ طَرِيقًا مُعَلَّقًا",uz:"sarguzashtchilarga muallaq yo‘l beradi"},{ar:"عَلَى الْجُدْرَانِ الْعَمُودِيَّةِ",uz:"tik devorlar bo‘ylab"}],full_uz:"Sarguzashtchilarga tik devorlar bo‘ylab muallaq yo‘l beradi.",note:"مُعَلَّقٌ — osilgan, muallaq."},
{num:109,time:"00:09:49,679 --> 00:09:57,019",arabic:"مُسْتَخْدِمًا كَابِلَاتٍ وَسَلَالِمَ فُولَاذِيَّةً لِعُبُورِ ارْتِفَاعَاتٍ مُذْهِلَةٍ",segs:[{ar:"مُسْتَخْدِمًا كَابِلَاتٍ وَسَلَالِمَ فُولَاذِيَّةً",uz:"po‘lat kabellar va narvonlardan foydalanib"},{ar:"لِعُبُورِ ارْتِفَاعَاتٍ مُذْهِلَةٍ",uz:"hayratlanarli balandliklarni kesib o‘tish uchun"}],full_uz:"Hayratlanarli balandliklarni kesib o‘tish uchun po‘lat kabellar va narvonlardan foydalanadi.",note:"سُلَّمٌ — narvon."},
{num:110,time:"00:09:57,019 --> 00:10:04,359",arabic:"هُنَا يَتَشَبَّثُ الْمُتَسَلِّقُونَ بِمَسَارَاتٍ تَعْلُو مِئَاتِ الْأَمْتَارِ فَوْقَ الْوَادِي",segs:[{ar:"هُنَا يَتَشَبَّثُ الْمُتَسَلِّقُونَ بِمَسَارَاتٍ",uz:"bu yerda alpinistlar yo‘llarga mahkam yopishadilar"},{ar:"تَعْلُو مِئَاتِ الْأَمْتَارِ",uz:"yuzlab metr baland ko‘tarilgan"},{ar:"فَوْقَ الْوَادِي",uz:"vodiy ustida"}],full_uz:"Bu yerda alpinistlar vodiy ustidan yuzlab metr baland ko‘tarilgan yo‘llarga mahkam yopishadilar.",note:"يَتَشَبَّثُ — mahkam yopishmoq."},
{num:111,time:"00:10:04,359 --> 00:10:08,659",arabic:"حَيْثُ قَدْ يَكُونُ لِخَطَإٍ وَاحِدٍ عَوَاقِبُ خَطِيرَةٌ",segs:[{ar:"حَيْثُ قَدْ يَكُونُ لِخَطَإٍ وَاحِدٍ",uz:"u yerda bitta xatoning"},{ar:"عَوَاقِبُ خَطِيرَةٌ",uz:"jiddiy oqibatlari bo‘lishi mumkin"}],full_uz:"U yerda bitta xatoning jiddiy oqibatlari bo‘lishi mumkin.",note:"عَوَاقِبُ — oqibatlar."},
{num:112,time:"00:10:08,659 --> 00:10:11,959",arabic:"كَمَا تُؤَكِّدُ تَقَارِيرُ فِرَقِ الْإِنْقَاذِ",segs:[{ar:"كَمَا تُؤَكِّدُ تَقَارِيرُ",uz:"hisobotlari ham tasdiqlaganidek"},{ar:"فِرَقِ الْإِنْقَاذِ",uz:"qutqaruv guruhlarining"}],full_uz:"Qutqaruv guruhlari hisobotlari ham buni tasdiqlaydi.",note:"فِرَقُ الْإِنْقَاذِ — qutqaruv guruhlari."},
{num:113,time:"00:10:11,960 --> 00:10:20,720",arabic:"لَكِنْ مَنْ يَصِلُ إِلَى النِّهَايَةِ يُكَافَأُ بِمَشَاهِدَ بَانُورَامِيَّةٍ لِلشَّلَّالَاتِ وَالْأَبْرَاجِ الصَّخْرِيَّةِ",segs:[{ar:"لَكِنْ مَنْ يَصِلُ إِلَى النِّهَايَةِ",uz:"ammo oxiriga yetib borgan kishi"},{ar:"يُكَافَأُ بِمَشَاهِدَ بَانُورَامِيَّةٍ",uz:"panoramali manzaralar bilan mukofotlanadi"},{ar:"لِلشَّلَّالَاتِ وَالْأَبْرَاجِ الصَّخْرِيَّةِ",uz:"sharsharalar va qoyali minoralarning"}],full_uz:"Ammo oxiriga yetib borgan kishi sharsharalar va qoyali minoralarning panoramali manzaralari bilan mukofotlanadi.",note:"يُكَافَأُ — mukofotlanmoq."},
{num:114,time:"00:10:20,720 --> 00:10:23,320",arabic:"وَالْقِمَمِ الْمُغَطَّاةِ بِالضَّبَابِ",segs:null,full_uz:"Va tuman bilan qoplangan cho‘qqilar.",note:"مُغَطًّى بِـ — ... bilan qoplangan."},
{num:115,time:"00:10:23,320 --> 00:10:30,040",arabic:"شَهَادَةٌ حَيَّةٌ عَلَى شَجَاعَةِ الْإِنْسَانِ وَقُوَّةِ الْأَرْضِ عَبْرَ الْعُصُورِ",segs:[{ar:"شَهَادَةٌ حَيَّةٌ",uz:"tirik guvohlik"},{ar:"عَلَى شَجَاعَةِ الْإِنْسَانِ",uz:"inson jasoratiga"},{ar:"وَقُوَّةِ الْأَرْضِ عَبْرَ الْعُصُورِ",uz:"va asrlar davomida yerning qudratiga"}],full_uz:"Bu inson jasorati va asrlar davomida yerning qudratiga tirik guvohlikdir.",note:"شَهَادَةٌ — guvohlik, dalil."},
{num:116,time:"00:10:30,040 --> 00:10:32,560",arabic:"شَلَّالُ كُومْبِي",segs:null,full_uz:"Kumbi sharsharasi.",note:null},
{num:117,time:"00:10:32,560 --> 00:10:36,280",arabic:"تَكَوَّنَ شَلَّالُ كُومْبِي عَبْرَ آلَافِ السِّنِينَ",segs:[{ar:"تَكَوَّنَ شَلَّالُ كُومْبِي",uz:"Kumbi sharsharasi shakllangan"},{ar:"عَبْرَ آلَافِ السِّنِينَ",uz:"minglab yillar davomida"}],full_uz:"Kumbi sharsharasi minglab yillar davomida shakllangan.",note:"تَكَوَّنَ — shakllanmoq."},
{num:118,time:"00:10:36,279 --> 00:10:43,279",arabic:"حِينَ حَفَرَتْ أَمْطَارُ الرِّيَاحِ الْمُوسِمِيَّةِ مَجَارِيَ عَمِيقَةً فِي صُخُورِ الْبَازَلْتِ الْقَدِيمَةِ",segs:[{ar:"حِينَ حَفَرَتْ أَمْطَارُ الرِّيَاحِ الْمُوسِمِيَّةِ",uz:"musson yomg‘irlari o‘ygan paytda"},{ar:"مَجَارِيَ عَمِيقَةً",uz:"chuqur o‘zanlarni"},{ar:"فِي صُخُورِ الْبَازَلْتِ الْقَدِيمَةِ",uz:"qadimiy bazalt jinslarida"}],full_uz:"Musson yomg‘irlari qadimiy bazalt jinslarida chuqur o‘zanlarni o‘ygan paytda.",note:"مَجْرًى — o‘zan, oqim yo‘li. الرِّيَاحُ الْمُوسِمِيَّةُ — musson shamollari."},
{num:119,time:"00:10:43,279 --> 00:10:53,279",arabic:"يَنْدَفِعُ الْمَاءُ مِنْ ارْتِفَاعٍ يَزِيدُ عَلَى ثَلَاثِينَ مِتْرًا دَاخِلَ وَادٍ وَعِرٍ صَاغَهُ تَارِيخٌ بُرْكَانِيٌّ عَتِيقٌ",segs:[{ar:"يَنْدَفِعُ الْمَاءُ مِنْ ارْتِفَاعٍ",uz:"suv balandlikdan otilib tushadi"},{ar:"يَزِيدُ عَلَى ثَلَاثِينَ مِتْرًا",uz:"o‘ttiz metrdan oshadigan"},{ar:"دَاخِلَ وَادٍ وَعِرٍ",uz:"notekis vodiy ichiga"},{ar:"صَاغَهُ تَارِيخٌ بُرْكَانِيٌّ عَتِيقٌ",uz:"qadimiy vulqon tarixi shakllantirgan"}],full_uz:"Suv o‘ttiz metrdan oshadigan balandlikdan qadimiy vulqon tarixi shakllantirgan notekis vodiy ichiga otilib tushadi.",note:"وَعِرٌ — notekis, o‘tish qiyin. يَنْدَفِعُ — otilib chiqmoq."},
{num:120,time:"00:10:54,240 --> 00:11:04,439",arabic:"تَرْتَفِعُ الْجُرُوفُ الصَّخْرِيَّةُ الْمُتَرَاكِمَةُ طَبَقَةً بَعْدَ طَبَقَةٍ عَلَى مَدَى نَحْوِ سِتِّينَ مِلْيُونَ سَنَةٍ",segs:[{ar:"تَرْتَفِعُ الْجُرُوفُ الصَّخْرِيَّةُ الْمُتَرَاكِمَةُ",uz:"to‘planib borgan qoyali jarliklar ko‘tariladi"},{ar:"طَبَقَةً بَعْدَ طَبَقَةٍ",uz:"qatlamma-qatlam"},{ar:"عَلَى مَدَى نَحْوِ سِتِّينَ مِلْيُونَ سَنَةٍ",uz:"qariyb oltmish million yil davomida"}],full_uz:"To‘planib borgan qoyali jarliklar qariyb oltmish million yil davomida qatlamma-qatlam ko‘tarilib borgan.",note:"مُتَرَاكِمٌ — to‘planib borgan, qatlamlangan."},
{num:121,time:"00:11:04,440 --> 00:11:08,620",arabic:"كَجُدْرَانٍ دَاكِنَةٍ تُحِيطُ بِسَيْلٍ أَبْيَضَ هَادِرٍ",segs:[{ar:"كَجُدْرَانٍ دَاكِنَةٍ",uz:"qoramtir devorlardek"},{ar:"تُحِيطُ بِسَيْلٍ أَبْيَضَ هَادِرٍ",uz:"gumburlab oqayotgan oq selni o‘rab turadigan"}],full_uz:"Gumburlab oqayotgan oq selni o‘rab turgan qoramtir devorlardek.",note:"هَادِرٌ — gumburlab oqayotgan, shovqinli."},
{num:122,time:"00:11:08,620 --> 00:11:17,140",arabic:"فِي مَوْسِمِ الذِّرْوَةِ يَسْلُكُ الزُّوَّارُ مَسَارَاتٍ ضَيِّقَةً لِلْوُصُولِ إِلَى الْحَافَّةِ الْعُلْيَا",segs:[{ar:"فِي مَوْسِمِ الذِّرْوَةِ",uz:"eng yuqori mavsumda"},{ar:"يَسْلُكُ الزُّوَّارُ مَسَارَاتٍ ضَيِّقَةً",uz:"ziyoratchilar tor yo‘llardan boradilar"},{ar:"لِلْوُصُولِ إِلَى الْحَافَّةِ الْعُلْيَا",uz:"yuqori qirga yetib borish uchun"}],full_uz:"Eng yuqori mavsumda ziyoratchilar yuqori qirga yetib borish uchun tor yo‘llardan boradilar.",note:"مَوْسِمُ الذِّرْوَةِ — eng gavjum/yuqori mavsum."},
{num:123,time:"00:11:17,140 --> 00:11:23,700",arabic:"حَيْثُ يَبْدُو الْإِنْسَانُ صَغِيرًا أَمَامَ اتِّسَاعِ الْمَشْهَدِ",segs:[{ar:"حَيْثُ يَبْدُو الْإِنْسَانُ صَغِيرًا",uz:"u yerda inson kichik ko‘rinadi"},{ar:"أَمَامَ اتِّسَاعِ الْمَشْهَدِ",uz:"manzaraning kengligi oldida"}],full_uz:"U yerda inson manzaraning kengligi oldida kichik ko‘rinadi.",note:"اتِّسَاعٌ — kenglik, ulkanlik."},
{num:124,time:"00:11:23,700 --> 00:11:29,260",arabic:"بَيْنَ رَذَاذٍ مُتَطَايِرٍ وَجِبَالٍ تَمْتَدُّ بِلَا نِهَايَةٍ",segs:[{ar:"بَيْنَ رَذَاذٍ مُتَطَايِرٍ",uz:"uchib taralayotgan mayda suv tomchilari orasida"},{ar:"وَجِبَالٍ تَمْتَدُّ بِلَا نِهَايَةٍ",uz:"va cheksiz cho‘zilgan tog‘lar orasida"}],full_uz:"Uchib taralayotgan mayda suv tomchilari va cheksiz cho‘zilgan tog‘lar orasida.",note:"رَذَاذٌ — mayda suv tomchilari, sachragan suv."},
{num:125,time:"00:11:29,259 --> 00:11:37,259",arabic:"يَغْمُرُ الْمَنَاخُ الرَّطْبُ الْمَكَانَ بِخُضْرَةٍ كَثِيفَةٍ",segs:[{ar:"يَغْمُرُ الْمَنَاخُ الرَّطْبُ الْمَكَانَ",uz:"nam iqlim joyni qoplaydi"},{ar:"بِخُضْرَةٍ كَثِيفَةٍ",uz:"qalin yam-yashil o‘simliklar bilan"}],full_uz:"Nam iqlim joyni qalin yam-yashil o‘simliklar bilan qoplaydi.",note:"يَغْمُرُ — qoplamoq, to‘ldirmoq."},
{num:126,time:"00:11:41,259 --> 00:11:49,740",arabic:"وَمِنَ الْأَعْلَى يَنْكَشِفُ الشَّلَّالُ كَمُدَرَّجٍ طَبِيعِيٍّ مِنَ الصَّخْرِ وَالضَّبَابِ وَصَدَى الرَّعْدِ",segs:[{ar:"وَمِنَ الْأَعْلَى يَنْكَشِفُ الشَّلَّالُ",uz:"yuqoridan sharshara namoyon bo‘ladi"},{ar:"كَمُدَرَّجٍ طَبِيعِيٍّ",uz:"tabiiy amfiteatrdek"},{ar:"مِنَ الصَّخْرِ وَالضَّبَابِ وَصَدَى الرَّعْدِ",uz:"tosh, tuman va momaqaldiroq aks-sadosidan"}],full_uz:"Yuqoridan sharshara tosh, tuman va momaqaldiroq aks-sadosidan iborat tabiiy amfiteatrdek namoyon bo‘ladi.",note:"يَنْكَشِفُ — namoyon bo‘lmoq, ochilib ko‘rinmoq. صَدَى الرَّعْدِ — momaqaldiroq aks-sadosi."},
{num:127,time:"00:11:49,740 --> 00:11:53,940",arabic:"إِنَّهَا عَجِيبَةٌ مُسْتَحِيلَةٌ",segs:null,full_uz:"Bu imkonsizdek tuyuladigan ajoyibot.",note:"عَجِيبَةٌ — ajoyibot, hayratlanarli narsa."},
{num:128,time:"00:11:53,940 --> 00:12:00,799",arabic:"يَلْتَقِي فِيهَا عِلْمُ الْأَرْضِ وَالْخَطَرُ وَالْجَمَالُ الْآسِرُ فِي مَشْهَدٍ لَا يُنْسَى",segs:[{ar:"يَلْتَقِي فِيهَا عِلْمُ الْأَرْضِ وَالْخَطَرُ",uz:"unda geologiya ilmi va xavf uchrashadi"},{ar:"وَالْجَمَالُ الْآسِرُ",uz:"va maftunkor go‘zallik"},{ar:"فِي مَشْهَدٍ لَا يُنْسَى",uz:"unutilmas manzarada"}],full_uz:"Unda geologiya ilmi, xavf va maftunkor go‘zallik unutilmas manzarada uchrashadi.",note:"آسِرٌ — maftunkor, o‘ziga rom qiluvchi."},
{num:129,time:"00:12:00,799 --> 00:12:05,000",arabic:"نَبْعُ الْعَيْنِ الزَّرْقَاءِ",segs:null,full_uz:"Moviy Ko‘z bulog‘i.",note:null},
{num:130,time:"00:12:05,000 --> 00:12:10,080",arabic:"مُخْتَبِئًا تَحْتَ جِبَالِ جَنُوبِ أَلْبَانْيَا الْمَكْسُوَّةِ بِالْغَابَاتِ",segs:[{ar:"مُخْتَبِئًا تَحْتَ جِبَالِ جَنُوبِ أَلْبَانْيَا",uz:"Albaniyaning janubiy tog‘lari ostida yashirinib"},{ar:"الْمَكْسُوَّةِ بِالْغَابَاتِ",uz:"o‘rmonlar bilan qoplangan"}],full_uz:"Albaniyaning o‘rmonlar bilan qoplangan janubiy tog‘lari ostida yashirinib yotgan.",note:null},
{num:131,time:"00:12:10,080 --> 00:12:15,299",arabic:"يَظْهَرُ نَبْعُ الْعَيْنِ الزَّرْقَاءِ كَأَعْجُوبَةٍ جِيُولُوجِيَّةٍ",segs:[{ar:"يَظْهَرُ نَبْعُ الْعَيْنِ الزَّرْقَاءِ",uz:"Moviy Ko‘z bulog‘i ko‘rinadi"},{ar:"كَأَعْجُوبَةٍ جِيُولُوجِيَّةٍ",uz:"geologik ajoyibot sifatida"}],full_uz:"Moviy Ko‘z bulog‘i geologik ajoyibot sifatida namoyon bo‘ladi.",note:null},
{num:132,time:"00:12:15,299 --> 00:12:19,819",arabic:"حَيْثُ تَنْدَفِعُ مِيَاهٌ جَلِيدِيَّةٌ مِنْ تَجْوِيفٍ كَارْسْتِيٍّ",segs:[{ar:"حَيْثُ تَنْدَفِعُ مِيَاهٌ جَلِيدِيَّةٌ",uz:"u yerda muzdek suv otilib chiqadi"},{ar:"مِنْ تَجْوِيفٍ كَارْسْتِيٍّ",uz:"karst bo‘shlig‘idan"}],full_uz:"U yerda muzdek suv karst bo‘shlig‘idan otilib chiqadi.",note:"جَلِيدِيٌّ — muzdek, muzlikka oid. تَجْوِيفٌ كَارْسْتِيٌّ — karst bo‘shlig‘i."},
{num:133,time:"00:12:19,819 --> 00:12:22,879",arabic:"يَتَجَاوَزُ عُمْقُهُ خَمْسِينَ مِتْرًا",segs:null,full_uz:"Uning chuqurligi ellik metrdan oshadi.",note:null},
{num:134,time:"00:12:22,879 --> 00:12:26,339",arabic:"عُمْقٌ لَمْ يَبْلُغْهُ الْغَوَّاصُونَ حَتَّى الْيَوْمِ",segs:[{ar:"عُمْقٌ لَمْ يَبْلُغْهُ الْغَوَّاصُونَ",uz:"g‘avvoslar yetib bormagan chuqurlik"},{ar:"حَتَّى الْيَوْمِ",uz:"bugungi kungacha"}],full_uz:"Bugungi kungacha g‘avvoslar yetib bormagan chuqurlik.",note:"بَلَغَ — yetib bormoq."},
{num:135,time:"00:12:26,339 --> 00:12:32,379",arabic:"يَتَغَذَّى النَّبْعُ بِضَغْطٍ جَوْفِيٍّ",segs:[{ar:"يَتَغَذَّى النَّبْعُ",uz:"buloq oziqlanadi"},{ar:"بِضَغْطٍ جَوْفِيٍّ",uz:"yer osti bosimi bilan"}],full_uz:"Buloq yer osti bosimi bilan oziqlanadi.",note:"ضَغْطٌ جَوْفِيٌّ — yer osti bosimi."},
{num:136,time:"00:12:32,379 --> 00:12:36,759",arabic:"يُعَادِلُ أَكْثَرَ مِنْ أَلْفٍ وَتِسْعِمِائَةِ لِتْرٍ فِي الثَّانِيَةِ",segs:[{ar:"يُعَادِلُ أَكْثَرَ مِنْ أَلْفٍ وَتِسْعِمِائَةِ لِتْرٍ",uz:"bir ming to‘qqiz yuz litrdan ortiqni tashkil etadi"},{ar:"فِي الثَّانِيَةِ",uz:"bir soniyada"}],full_uz:"Bu bir soniyada bir ming to‘qqiz yuz litrdan ortiqni tashkil etadi.",note:"يُعَادِلُ — teng bo‘lmoq, tashkil etmoq."},
{num:137,time:"00:12:36,759 --> 00:12:43,959",arabic:"لِيُشَكِّلَ بِرْكَةً طَبِيعِيَّةً تَتَدَرَّجُ أَلْوَانُهَا بَيْنَ الْيَاقُوتِ وَالْأَخْضَرِ الزُّمُرُّدِيِّ",segs:[{ar:"لِيُشَكِّلَ بِرْكَةً طَبِيعِيَّةً",uz:"tabiiy hovuz hosil qilib"},{ar:"تَتَدَرَّجُ أَلْوَانُهَا",uz:"uning ranglari o‘zgarib boradi"},{ar:"بَيْنَ الْيَاقُوتِ وَالْأَخْضَرِ الزُّمُرُّدِيِّ",uz:"yoqut va zumrad yashili orasida"}],full_uz:"Tabiiy hovuz hosil qilib, uning ranglari yoqut va zumrad yashili orasida o‘zgarib boradi.",note:"الزُّمُرُّدُ — zumrad."},
{num:138,time:"00:12:43,960 --> 00:12:50,080",arabic:"يَعُودُ أَصْلُ هَذَا الْمَكَانِ إِلَى عَشَرَاتِ آلَافِ السِّنِينَ",segs:[{ar:"يَعُودُ أَصْلُ هَذَا الْمَكَانِ",uz:"bu joyning kelib chiqishi borib taqaladi"},{ar:"إِلَى عَشَرَاتِ آلَافِ السِّنِينَ",uz:"o‘n minglab yillar oldinga"}],full_uz:"Bu joyning kelib chiqishi o‘n minglab yillar oldinga borib taqaladi.",note:"أَصْلٌ — kelib chiqish, asos."},
{num:139,time:"00:12:50,080 --> 00:12:55,780",arabic:"نَحَتَتْهُ إِذَابَةُ الْحَجَرِ الْجِيرِيِّ وَحَرَكَاتُ الْقِشْرَةِ الْأَرْضِيَّةِ",segs:[{ar:"نَحَتَتْهُ إِذَابَةُ الْحَجَرِ الْجِيرِيِّ",uz:"uni ohaktoshning erishi o‘ygan"},{ar:"وَحَرَكَاتُ الْقِشْرَةِ الْأَرْضِيَّةِ",uz:"va yer po‘stining harakatlari"}],full_uz:"Uni ohaktoshning erishi va yer po‘stining harakatlari shakllantirgan.",note:"إِذَابَةٌ — eritish, erish. الْقِشْرَةُ الْأَرْضِيَّةُ — yer po‘sti."},
{num:140,time:"00:12:55,780 --> 00:13:00,259",arabic:"مَشْهَدٌ صَامِتٌ، بَارِدٌ، وَآسِرٌ",segs:null,full_uz:"Sokin, sovuq va maftunkor manzara.",note:null},
{num:141,time:"00:13:00,259 --> 00:13:04,340",arabic:"نَافِذَةٌ مَفْتُوحَةٌ عَلَى قَلْبِ الْأَرْضِ نَفْسِهِ",segs:[{ar:"نَافِذَةٌ مَفْتُوحَةٌ",uz:"ochiq deraza"},{ar:"عَلَى قَلْبِ الْأَرْضِ نَفْسِهِ",uz:"yerning o‘z qalbiga"}],full_uz:"Yerning o‘z qalbiga ochilgan deraza.",note:null},
{num:142,time:"00:13:07,340 --> 00:13:11,820",arabic:"الْيَوْمَ يَخُوضُ الزُّوَّارُ مِيَاهَهَا الْمُتَجَمِّدَةَ",segs:[{ar:"الْيَوْمَ يَخُوضُ الزُّوَّارُ",uz:"bugun ziyoratchilar kechib o‘tadilar"},{ar:"مِيَاهَهَا الْمُتَجَمِّدَةَ",uz:"uning muzdek suvlaridan"}],full_uz:"Bugun ziyoratchilar uning muzdek suvlaridan kechib o‘tadilar.",note:"يَخُوضُ — suvga kirib kechmoq."},
{num:143,time:"00:13:11,820 --> 00:13:15,700",arabic:"الَّتِي لَا تَتَجَاوَزُ أَرْبَعَ دَرَجَاتٍ مِئَوِيَّةٍ",segs:null,full_uz:"Harorati to‘rt daraja Selsiydan oshmaydigan.",note:"دَرَجَةٌ مِئَوِيَّةٌ — Selsiy darajasi."},
{num:144,time:"00:13:15,700 --> 00:13:18,760",arabic:"فَيَشْعُرُونَ بِقُوَّةِ الْأَرْضِ الْخَامِ",segs:[{ar:"فَيَشْعُرُونَ بِقُوَّةِ الْأَرْضِ",uz:"shunda ular yerning qudratini his qiladilar"},{ar:"الْخَامِ",uz:"sof, xom holatdagi"}],full_uz:"Shunda ular yerning sof, xom qudratini his qiladilar.",note:"خَامٌ — xom, tabiiy, ishlov berilmagan."},
{num:145,time:"00:13:18,760 --> 00:13:22,840",arabic:"وَهِيَ تَتَنَفَّسُ مِنَ الْأَعْمَاقِ الْمُظْلِمَةِ إِلَى السَّطْحِ",segs:[{ar:"وَهِيَ تَتَنَفَّسُ",uz:"u nafas oladi"},{ar:"مِنَ الْأَعْمَاقِ الْمُظْلِمَةِ إِلَى السَّطْحِ",uz:"qorong‘i qa’ridan sirtga tomon"}],full_uz:"U qorong‘i qa’ridan sirtga tomon nafas olayotgandek.",note:null},
{num:146,time:"00:13:22,840 --> 00:13:27,000",arabic:"بَلْدَةُ فُورُونْغ",segs:null,full_uz:"Furong shaharchasi.",note:null},
{num:147,time:"00:13:27,000 --> 00:13:30,240",arabic:"مَنْحُوتَةٌ فِي مُنْحَدَرَاتِ غَرْبِ هُونَان",segs:null,full_uz:"Xunan g‘arbidagi yonbag‘irlarga o‘yilgan.",note:"مَنْحُوتٌ — o‘yilgan."},
{num:148,time:"00:13:30,240 --> 00:13:35,600",arabic:"تَقِفُ بَلْدَةُ فُورُونْغَ مُنْذُ أَكْثَرَ مِنْ أَلْفِ عَامٍ",segs:[{ar:"تَقِفُ بَلْدَةُ فُورُونْغَ",uz:"Furong shaharchasi qad rostlab turibdi"},{ar:"مُنْذُ أَكْثَرَ مِنْ أَلْفِ عَامٍ",uz:"ming yildan ortiq vaqtdan beri"}],full_uz:"Furong shaharchasi ming yildan ortiq vaqtdan beri qad rostlab turibdi.",note:null},
{num:149,time:"00:13:35,600 --> 00:13:42,820",arabic:"شَكَّلَتْهَا الْأَنْهَارُ الَّتِي شَقَّتِ الْحَجَرَ الرَّمْلِيَّ عَبْرَ عُصُورٍ لَا تُحْصَى",segs:[{ar:"شَكَّلَتْهَا الْأَنْهَارُ",uz:"uni daryolar shakllantirgan"},{ar:"الَّتِي شَقَّتِ الْحَجَرَ الرَّمْلِيَّ",uz:"qumtoshni yorib o‘tgan"},{ar:"عَبْرَ عُصُورٍ لَا تُحْصَى",uz:"hisobsiz davrlar davomida"}],full_uz:"Uni hisobsiz davrlar davomida qumtoshni yorib o‘tgan daryolar shakllantirgan.",note:"شَقَّ — yorib o‘tmoq."},
{num:150,time:"00:13:42,820 --> 00:13:47,360",arabic:"تَصْطَفُّ مَنَازِلُ خَشَبِيَّةٌ مَبْنِيَّةٌ عَلَى رَكَائِزَ",segs:[{ar:"تَصْطَفُّ مَنَازِلُ خَشَبِيَّةٌ",uz:"yog‘och uylar tizilib turadi"},{ar:"مَبْنِيَّةٌ عَلَى رَكَائِزَ",uz:"ustunlar ustiga qurilgan"}],full_uz:"Ustunlar ustiga qurilgan yog‘och uylar tizilib turadi.",note:"رَكَائِزُ — tayanchlar, ustunlar."},
{num:151,time:"00:13:47,360 --> 00:13:50,680",arabic:"يَعُودُ بَعْضُهَا لِأَكْثَرَ مِنْ ثَلَاثَةِ قُرُونٍ",segs:null,full_uz:"Ba’zilarining yoshi uch asrdan oshadi.",note:"قَرْنٌ — asr."},
{num:152,time:"00:13:50,680 --> 00:13:54,700",arabic:"عَلَى الْحَوَافِّ الْمُطِلَّةِ عَلَى شَلَّالِ فُورُونْغَ الْهَادِرِ",segs:[{ar:"عَلَى الْحَوَافِّ الْمُطِلَّةِ",uz:"qarab turgan chekkalarda"},{ar:"عَلَى شَلَّالِ فُورُونْغَ الْهَادِرِ",uz:"gumburlab oqayotgan Furong sharsharasiga"}],full_uz:"Gumburlab oqayotgan Furong sharsharasiga qaragan chekkalarda.",note:"مُطِلٌّ عَلَى — qarab turgan, manzarasi tushadigan."},
{num:153,time:"00:13:54,700 --> 00:14:01,200",arabic:"الَّذِي يَهْبِطُ قَرَابَةَ ثَلَاثِينَ مِتْرًا إِلَى بِرْكَةٍ بِلَوْنِ الْيَشْمِ فِي الْأَسْفَلِ",segs:[{ar:"الَّذِي يَهْبِطُ قَرَابَةَ ثَلَاثِينَ مِتْرًا",uz:"u qariyb o‘ttiz metr pastga tushadi"},{ar:"إِلَى بِرْكَةٍ بِلَوْنِ الْيَشْمِ",uz:"nefrit rangli hovuzga"},{ar:"فِي الْأَسْفَلِ",uz:"pastda"}],full_uz:"U qariyb o‘ttiz metr pastga, quyida joylashgan nefrit rangli hovuzga tushadi.",note:"الْيَشْمُ — nefrit, jade."},
{num:154,time:"00:14:01,200 --> 00:14:08,379",arabic:"مَعَ حُلُولِ الْمَسَاءِ تَتَوَهَّجُ الشَّوَارِعُ الْمُضَاءَةُ بِالْفَوَانِيسِ فَوْقَ الْجُسُورِ الْحَجَرِيَّةِ",segs:[{ar:"مَعَ حُلُولِ الْمَسَاءِ",uz:"kech kirishi bilan"},{ar:"تَتَوَهَّجُ الشَّوَارِعُ الْمُضَاءَةُ بِالْفَوَانِيسِ",uz:"fonuslar bilan yoritilgan ko‘chalar yarqiraydi"},{ar:"فَوْقَ الْجُسُورِ الْحَجَرِيَّةِ",uz:"tosh ko‘priklar ustida"}],full_uz:"Kech kirishi bilan tosh ko‘priklar ustidagi fonuslar bilan yoritilgan ko‘chalar yarqiraydi.",note:"مَعَ حُلُولِ — ... kirishi bilan."},
{num:155,time:"00:14:08,379 --> 00:14:13,840",arabic:"وَيَتَجَوَّلُ الزُّوَّارُ فِي الْأَزِقَّةِ الضَّيِّقَةِ الْمُطِلَّةِ عَلَى الشَّلَّالِ الْمُضَاءَةِ",segs:[{ar:"وَيَتَجَوَّلُ الزُّوَّارُ فِي الْأَزِقَّةِ الضَّيِّقَةِ",uz:"ziyoratchilar tor ko‘chalarda kezadilar"},{ar:"الْمُطِلَّةِ عَلَى الشَّلَّالِ الْمُضَاءَةِ",uz:"yoritilgan sharsharaga qaragan"}],full_uz:"Ziyoratchilar yoritilgan sharsharaga qaragan tor ko‘chalarda kezadilar.",note:null},
{num:156,time:"00:14:13,840 --> 00:14:19,200",arabic:"هَذَا التَّمَازُجُ بَيْنَ الْجِيُولُوجْيَا وَالتَّارِيخِ وَالْعِمَارَةِ",segs:[{ar:"هَذَا التَّمَازُجُ",uz:"bu uyg‘unlashuv"},{ar:"بَيْنَ الْجِيُولُوجْيَا وَالتَّارِيخِ وَالْعِمَارَةِ",uz:"geologiya, tarix va me’morchilik o‘rtasidagi"}],full_uz:"Geologiya, tarix va me’morchilik o‘rtasidagi bu uyg‘unlashuv.",note:"تَمَازُجٌ — qorishish, uyg‘unlashuv."},
{num:157,time:"00:14:19,780 --> 00:14:23,560",arabic:"يَخْلُقُ مَشْهَدًا يَبْدُو فِيهِ الزَّمَنُ مُعَلَّقًا",segs:[{ar:"يَخْلُقُ مَشْهَدًا",uz:"bir manzara yaratadi"},{ar:"يَبْدُو فِيهِ الزَّمَنُ مُعَلَّقًا",uz:"unda zamon muallaqdek ko‘rinadi"}],full_uz:"Unda zamon muallaqdek ko‘rinadigan bir manzara yaratadi.",note:null},
{num:158,time:"00:14:23,559 --> 00:14:31,219",arabic:"قَرْيَةٌ جَبَلِيَّةٌ تَحَوَّلَتْ إِلَى تُحْفَةٍ مُتَلَأْلِئَةٍ مِنَ الْمَاءِ وَالضَّوْءِ وَالِاكْتِشَافِ الْهَادِئِ",segs:[{ar:"قَرْيَةٌ جَبَلِيَّةٌ تَحَوَّلَتْ إِلَى تُحْفَةٍ مُتَلَأْلِئَةٍ",uz:"tog‘ qishlog‘i yarqiragan durdonaga aylangan"},{ar:"مِنَ الْمَاءِ وَالضَّوْءِ وَالِاكْتِشَافِ الْهَادِئِ",uz:"suv, nur va sokin kashfiyotdan iborat"}],full_uz:"Tog‘ qishlog‘i suv, nur va sokin kashfiyotdan iborat yarqiragan durdonaga aylangan.",note:"الِاكْتِشَافُ — kashfiyot, kashf qilish."},
{num:159,time:"00:14:31,219 --> 00:14:35,019",arabic:"لَافِيرْتِيزْو، سُوِيسْرَا",segs:null,full_uz:"Lavertezzо, Shveytsariya.",note:null},
{num:160,time:"00:14:35,019 --> 00:14:39,339",arabic:"تَقَعُ لَافِيرْتِيزْو فِي وَادِي فِيرْزَاسْكَا بِسُوِيسْرَا",segs:[{ar:"تَقَعُ لَافِيرْتِيزْو",uz:"Lavertezzо joylashgan"},{ar:"فِي وَادِي فِيرْزَاسْكَا بِسُوِيسْرَا",uz:"Shveytsariyadagi Verzasca vodiysida"}],full_uz:"Lavertezzо Shveytsariyadagi Verzasca vodiysida joylashgan.",note:null},
{num:161,time:"00:14:39,339 --> 00:14:46,419",arabic:"قَرْيَةٌ نَحَتَتْهَا أَكْثَرُ مِنْ ثَلَاثِينَ مِلْيُونَ سَنَةٍ مِنَ الِارْتِفَاعَاتِ الْأَلْبِيَّةِ",segs:[{ar:"قَرْيَةٌ نَحَتَتْهَا",uz:"shakllantirgan qishloq"},{ar:"أَكْثَرُ مِنْ ثَلَاثِينَ مِلْيُونَ سَنَةٍ",uz:"o‘ttiz million yildan ortiq"},{ar:"مِنَ الِارْتِفَاعَاتِ الْأَلْبِيَّةِ",uz:"Alp tog‘larining ko‘tarilishlari bilan"}],full_uz:"Alp tog‘larining ko‘tarilishlari natijasida o‘ttiz million yildan ortiq vaqt davomida shakllangan qishloq.",note:"الِارْتِفَاعَاتُ — ko‘tarilishlar, balandlashishlar."},
{num:162,time:"00:14:46,419 --> 00:14:51,859",arabic:"يَشُقُّ نَهْرُ فِيرْزَاسْكَا بِرْكَتَهُ الزُّمُرُّدِيَّةَ الْمَسْقُولَةَ",segs:[{ar:"يَشُقُّ نَهْرُ فِيرْزَاسْكَا",uz:"Verzasca daryosi yorib o‘tadi"},{ar:"بِرْكَتَهُ الزُّمُرُّدِيَّةَ الْمَسْقُولَةَ",uz:"sayqallangan zumrad rangli hovuzini"}],full_uz:"Verzasca daryosi sayqallangan zumrad rangli hovuzni yorib o‘tadi.",note:"مَسْقُولٌ — sayqallangan."},
{num:163,time:"00:14:51,860 --> 00:15:01,440",arabic:"عَبْرَ صُخُورٍ نَاعِمَةٍ صَقَلَتْهَا الْأَنْهَارُ الْجَلِيدِيَّةُ الَّتِي بَلَغَ سُمْكُهَا يَوْمًا مَا أَكْثَرَ مِنْ كِيلُومِتْرٍ",segs:[{ar:"عَبْرَ صُخُورٍ نَاعِمَةٍ",uz:"yumshoq qoyalar orasidan"},{ar:"صَقَلَتْهَا الْأَنْهَارُ الْجَلِيدِيَّةُ",uz:"muzliklar sayqallagan"},{ar:"الَّتِي بَلَغَ سُمْكُهَا يَوْمًا مَا",uz:"bir vaqtlar qalinligi yetgan"},{ar:"أَكْثَرَ مِنْ كِيلُومِتْرٍ",uz:"bir kilometrdan ortiq"}],full_uz:"Bir vaqtlar qalinligi bir kilometrdan ortiq bo‘lgan muzliklar sayqallagan yumshoq qoyalar orasidan.",note:"صَقَلَ — sayqallamoq, silliqlamoq."},
{num:164,time:"00:15:01,440 --> 00:15:13,980",arabic:"يَهَيْمِنُ جِسْرُ بُونْتِي دِي سَالْتِي مُزْدَوِجُ الْقَوْسِ الْمُشَيَّدُ فِي الْقَرْنِ السَّابِعَ عَشَرَ عَلَى الْمَشْهَدِ بِحِجَارَتِهِ الْخَالِدَةِ",segs:[{ar:"يَهَيْمِنُ جِسْرُ بُونْتِي دِي سَالْتِي",uz:"Ponte dei Salti ko‘prigi hukmron turadi"},{ar:"مُزْدَوِجُ الْقَوْسِ",uz:"ikki ravoqli"},{ar:"الْمُشَيَّدُ فِي الْقَرْنِ السَّابِعَ عَشَرَ",uz:"o‘n yettinchi asrda qurilgan"},{ar:"عَلَى الْمَشْهَدِ بِحِجَارَتِهِ الْخَالِدَةِ",uz:"abadiydek ko‘ringan toshlari bilan manzarada"}],full_uz:"O‘n yettinchi asrda qurilgan ikki ravoqli Ponte dei Salti ko‘prigi abadiydek ko‘ringan toshlari bilan manzarada hukmron turadi.",note:"يَهَيْمِنُ عَلَى — ustunlik qilmoq, hukmron turmoq."},
{num:165,time:"00:15:13,980 --> 00:15:18,960",arabic:"يَتَجَوَّلُ الزُّوَّارُ فِي الْأَزِقَّةِ الْمَرْصُوفَةِ",segs:[{ar:"يَتَجَوَّلُ الزُّوَّارُ",uz:"ziyoratchilar kezib yuradilar"},{ar:"فِي الْأَزِقَّةِ الْمَرْصُوفَةِ",uz:"tosh yotqizilgan tor ko‘chalarda"}],full_uz:"Ziyoratchilar tosh yotqizilgan tor ko‘chalarda kezib yuradilar.",note:"مَرْصُوفٌ — tosh yotqizilgan, qoplangan."},
{num:166,time:"00:15:21,860 --> 00:15:32,659",arabic:"ثُمَّ يَنْزِلُونَ إِلَى أَحْوَاضِ النَّهْرِ الطَّبِيعِيَّةِ حَيْثُ تَبْقَى الْمِيَاهُ بَارِدَةً عِنْدَ نَحْوِ عَشَرِ دَرَجَاتٍ مِئَوِيَّةٍ حَتَّى فِي عِزِّ الصَّيْفِ",segs:[{ar:"ثُمَّ يَنْزِلُونَ إِلَى أَحْوَاضِ النَّهْرِ الطَّبِيعِيَّةِ",uz:"so‘ng daryoning tabiiy hovuzlariga tushadilar"},{ar:"حَيْثُ تَبْقَى الْمِيَاهُ بَارِدَةً",uz:"u yerda suv sovuq bo‘lib qoladi"},{ar:"عِنْدَ نَحْوِ عَشَرِ دَرَجَاتٍ مِئَوِيَّةٍ",uz:"taxminan o‘n daraja Selsiyda"},{ar:"حَتَّى فِي عِزِّ الصَّيْفِ",uz:"yozning qizg‘in paytida ham"}],full_uz:"So‘ng daryoning tabiiy hovuzlariga tushadilar; u yerda hatto yozning qizg‘in paytida ham suv harorati taxminan o‘n daraja Selsiyda qoladi.",note:"عِزُّ الصَّيْفِ — yozning eng issiq/qizg‘in payti."},
{num:167,time:"00:15:32,659 --> 00:15:43,100",arabic:"فِي هَذَا الْمَزِيجِ الْهَادِئِ مِنَ الْجِيُولُوجْيَا الْعَتِيقَةِ وَالْعِمَارَةِ الْخَالِدَةِ تَبْدُو لَافِيرْتِيزْو كَصُورَةٍ حَيَّةٍ",segs:[{ar:"فِي هَذَا الْمَزِيجِ الْهَادِئِ",uz:"bu sokin uyg‘unlikda"},{ar:"مِنَ الْجِيُولُوجْيَا الْعَتِيقَةِ وَالْعِمَارَةِ الْخَالِدَةِ",uz:"qadimiy geologiya va abadiydek me’morchilikdan iborat"},{ar:"تَبْدُو لَافِيرْتِيزْو كَصُورَةٍ حَيَّةٍ",uz:"Lavertezzо tirik suratdek ko‘rinadi"}],full_uz:"Qadimiy geologiya va abadiydek me’morchilikdan iborat bu sokin uyg‘unlikda Lavertezzо tirik suratdek ko‘rinadi.",note:null},
{num:168,time:"00:15:43,100 --> 00:15:50,840",arabic:"لَادِغْ فِي سَيْشِل",segs:null,full_uz:"La-Dig, Seyshel.",note:null},
{num:169,time:"00:15:50,840 --> 00:15:58,580",arabic:"تَكَوَّنَتْ لَادِغْ مِنْ صُخُورِ الْجِرَانِيتِ الَّتِي يَعُودُ عُمْرُهَا لِأَكْثَرَ مِنْ سِتِّمِائَةِ مِلْيُونِ عَامٍ",segs:[{ar:"تَكَوَّنَتْ لَادِغْ مِنْ صُخُورِ الْجِرَانِيتِ",uz:"La-Dig granit jinslaridan shakllangan"},{ar:"الَّتِي يَعُودُ عُمْرُهَا لِأَكْثَرَ مِنْ سِتِّمِائَةِ مِلْيُونِ عَامٍ",uz:"ularning yoshi olti yuz million yildan ortiq"}],full_uz:"La-Dig yoshi olti yuz million yildan ortiq bo‘lgan granit jinslaridan shakllangan.",note:"جِرَانِيتٌ — granit."},
{num:170,time:"00:15:58,580 --> 00:16:02,580",arabic:"مَا يَجْعَلُهَا مِنْ أَقْدَمِ الْأَجْزَاءِ الْمَكْشُوفَةِ",segs:[{ar:"مَا يَجْعَلُهَا مِنْ أَقْدَمِ الْأَجْزَاءِ",uz:"bu uni eng qadimiy qismlardan biriga aylantiradi"},{ar:"الْمَكْشُوفَةِ",uz:"yer yuzasida ochiq ko‘rinib turgan"}],full_uz:"Bu uni yer yuzasida ochiq ko‘rinib turgan eng qadimiy qismlardan biriga aylantiradi.",note:"مَكْشُوفٌ — ochiq, yer yuzasiga chiqib turgan."},
{num:171,time:"00:16:02,580 --> 00:16:08,420",arabic:"مِنْ قِشْرَةِ الْأَرْضِ الَّتِي لَا تَزَالُ تَتَشَكَّلُ تَحْتَ تَأْثِيرِ الْبَحْرِ",segs:[{ar:"مِنْ قِشْرَةِ الْأَرْضِ",uz:"yer po‘stidan"},{ar:"الَّتِي لَا تَزَالُ تَتَشَكَّلُ",uz:"hamon shakllanib borayotgan"},{ar:"تَحْتَ تَأْثِيرِ الْبَحْرِ",uz:"dengiz ta’siri ostida"}],full_uz:"Dengiz ta’siri ostida hamon shakllanib borayotgan yer po‘stining bir qismidan.",note:"قِشْرَةُ الْأَرْضِ — yer po‘sti. تَأْثِيرٌ — ta’sir."},
{num:172,time:"00:16:08,419 --> 00:16:15,419",arabic:"سَاحِلُهَا الْأُسْطُورِيُّ وَخَاصَّةً شَاطِئُ أَنَاسْ سُورْسَ دَارْغَان",segs:[{ar:"سَاحِلُهَا الْأُسْطُورِيُّ",uz:"uning afsonaviy sohili"},{ar:"وَخَاصَّةً شَاطِئُ أَنَاسْ سُورْسَ دَارْغَان",uz:"ayniqsa Anse Source d’Argent plyaji"}],full_uz:"Uning afsonaviy sohili, ayniqsa Anse Source d’Argent plyaji.",note:null},
{num:173,time:"00:16:15,419 --> 00:16:22,259",arabic:"يَعْرِضُ صُخُورًا عِمْلَاقَةً تَرْتَفِعُ أَعْلَى مِنْ مَبْنًى مِنْ ثَلَاثَةِ طَوَابِقَ",segs:[{ar:"يَعْرِضُ صُخُورًا عِمْلَاقَةً",uz:"ulkan qoyalarni namoyon qiladi"},{ar:"تَرْتَفِعُ أَعْلَى مِنْ مَبْنًى مِنْ ثَلَاثَةِ طَوَابِقَ",uz:"uch qavatli binodan ham baland ko‘tarilgan"}],full_uz:"Uch qavatli binodan ham baland ko‘tarilgan ulkan qoyalarni namoyon qiladi.",note:"عِمْلَاقٌ — ulkan, bahaybat."},
{num:174,time:"00:16:22,259 --> 00:16:30,179",arabic:"مُنْحَنَيَاتُ هَذِهِ الصُّخُورِ صَقَلَتْهَا أَمْلَاحُ الْبَحْرِ وَحَرَكَةُ الْمَدِّ وَالْجَزْرِ",segs:[{ar:"مُنْحَنَيَاتُ هَذِهِ الصُّخُورِ",uz:"bu qoyalar egri shakllari"},{ar:"صَقَلَتْهَا أَمْلَاحُ الْبَحْرِ",uz:"dengiz tuzlari ularni sayqallagan"},{ar:"وَحَرَكَةُ الْمَدِّ وَالْجَزْرِ",uz:"va suvning ko‘tarilib-qaytish harakati"}],full_uz:"Bu qoyalar egri shakllarini dengiz tuzlari va suvning ko‘tarilib-qaytish harakati sayqallagan.",note:"الْمَدُّ وَالْجَزْرُ — suvning ko‘tarilishi va qaytishi. صَقَلَ — sayqallamoq."},
{num:175,time:"00:16:30,179 --> 00:16:35,500",arabic:"وَالِامْتِدَادُ الْحَرَارِيُّ الْمُسْتَمِرُّ عَبْرَ الْعُصُورِ",segs:null,full_uz:"Va asrlar davom etgan uzluksiz issiqlik kengayishi.",note:"الِامْتِدَادُ الْحَرَارِيُّ — issiqlik kengayishi."},
{num:176,time:"00:16:35,500 --> 00:16:40,960",arabic:"تَقَعُ الْجَزِيرَةُ فِي مِيَاهِ الْمُحِيطِ الْهِنْدِيِّ الدَّافِئَةِ",segs:[{ar:"تَقَعُ الْجَزِيرَةُ",uz:"orol joylashgan"},{ar:"فِي مِيَاهِ الْمُحِيطِ الْهِنْدِيِّ الدَّافِئَةِ",uz:"Hind okeanining iliq suvlarida"}],full_uz:"Orol Hind okeanining iliq suvlarida joylashgan.",note:null},
{num:177,time:"00:16:40,960 --> 00:16:47,659",arabic:"حَيْثُ تَتَرَاوَحُ دَرَجَاتُ الْحَرَارَةِ بَيْنَ سَبْعٍ وَعِشْرِينَ وَسِتٍّ وَعِشْرِينَ دَرَجَةً مِئَوِيَّةً",segs:[{ar:"حَيْثُ تَتَرَاوَحُ دَرَجَاتُ الْحَرَارَةِ",uz:"u yerda harorat darajalari o‘zgaradi"},{ar:"بَيْنَ سَبْعٍ وَعِشْرِينَ وَسِتٍّ وَعِشْرِينَ دَرَجَةً مِئَوِيَّةً",uz:"27 va 26 daraja Selsiy orasida"}],full_uz:"U yerda harorat 27 va 26 daraja Selsiy orasida o‘zgarib turadi.",note:"تَتَرَاوَحُ بَيْنَ ... وَ... — ... bilan ... orasida o‘zgarib turmoq."},
{num:178,time:"00:16:47,659 --> 00:16:53,379",arabic:"مُكَوِّنَةً بُحَيْرَاتٍ صَافِيَةً مِثَالِيَّةً لِلسِّبَاحَةِ وَالْغَوْصِ السَّطْحِيِّ",segs:[{ar:"مُكَوِّنَةً بُحَيْرَاتٍ صَافِيَةً",uz:"tiniq ko‘llarni hosil qilib"},{ar:"مِثَالِيَّةً لِلسِّبَاحَةِ وَالْغَوْصِ السَّطْحِيِّ",uz:"suzish va sayoz sho‘ng‘ish uchun juda qulay"}],full_uz:"Suzish va sayoz sho‘ng‘ish uchun juda qulay tiniq ko‘llarni hosil qilib.",note:"الْغَوْصُ السَّطْحِيُّ — sayoz sho‘ng‘ish, snorkeling."},
{num:179,time:"00:16:53,379 --> 00:17:00,539",arabic:"تَتَوَهَّجُ الرِّمَالُ الْوَرْدِيَّةُ وَالْبَيْضَاءُ تَحْتَ الضَّوْءِ الِاسْتِوَائِيِّ الْقَوِيِّ",segs:[{ar:"تَتَوَهَّجُ الرِّمَالُ الْوَرْدِيَّةُ وَالْبَيْضَاءُ",uz:"pushti va oq qumlar yarqiraydi"},{ar:"تَحْتَ الضَّوْءِ الِاسْتِوَائِيِّ الْقَوِيِّ",uz:"kuchli tropik nur ostida"}],full_uz:"Pushti va oq qumlar kuchli tropik nur ostida yarqiraydi.",note:"الِاسْتِوَائِيُّ — tropik."},
{num:180,time:"00:17:00,539 --> 00:17:06,139",arabic:"بَيْنَمَا تَحْمِي الشُّعُبُ الْمَرْجَانِيَّةُ الضَّحْلَةُ السَّاحِلَةَ مِنَ الْأَمْوَاجِ الْعَاتِيَةِ",segs:[{ar:"بَيْنَمَا تَحْمِي الشُّعُبُ الْمَرْجَانِيَّةُ الضَّحْلَةُ السَّاحِلَةَ",uz:"sayoz marjon riflari sohilni himoya qiladi"},{ar:"مِنَ الْأَمْوَاجِ الْعَاتِيَةِ",uz:"kuchli to‘lqinlardan"}],full_uz:"Sayoz marjon riflari sohilni kuchli to‘lqinlardan himoya qiladi.",note:"الشُّعُبُ الْمَرْجَانِيَّةُ — marjon riflari. عَاتٍ — kuchli, shiddatli."},
{num:181,time:"00:17:06,139 --> 00:17:14,539",arabic:"هَذَا الِانْسِجَامُ النَّادِرُ بَيْنَ جِيُولُوجْيَا سَحِيقَةٍ وَبِحَارٍ اسْتِوَائِيَّةٍ هَادِئَةٍ",segs:[{ar:"هَذَا الِانْسِجَامُ النَّادِرُ",uz:"bu noyob uyg‘unlik"},{ar:"بَيْنَ جِيُولُوجْيَا سَحِيقَةٍ",uz:"qadimiy geologiya bilan"},{ar:"وَبِحَارٍ اسْتِوَائِيَّةٍ هَادِئَةٍ",uz:"sokin tropik dengizlar o‘rtasidagi"}],full_uz:"Bu qadimiy geologiya va sokin tropik dengizlar o‘rtasidagi noyob uyg‘unlik.",note:"سَحِيقٌ — nihoyatda qadimiy, juda uzoq o‘tmishga oid."},
{num:182,time:"00:17:15,200 --> 00:17:20,720",arabic:"يَجْعَلُ لَادِغْ وَاحِدَةً مِنْ أَكْثَرِ الشَّوَاطِئِ سُرْيَالِيَّةً عَلَى كَوْكَبِ الْأَرْضِ",segs:[{ar:"يَجْعَلُ لَادِغْ وَاحِدَةً",uz:"La-Digni ...lardan biriga aylantiradi"},{ar:"مِنْ أَكْثَرِ الشَّوَاطِئِ سُرْيَالِيَّةً",uz:"eng syurreal sohillardan"},{ar:"عَلَى كَوْكَبِ الْأَرْضِ",uz:"Yer sayyorasidagi"}],full_uz:"Bu La-Digni Yer sayyorasidagi eng syurreal sohillardan biriga aylantiradi.",note:"يَجْعَلُ — aylantirmoq."},
{num:183,time:"00:17:20,720 --> 00:17:26,039",arabic:"قَرْيَةُ جَانْفِيَهْ الْعَائِمَةُ",segs:null,full_uz:"Suzib turuvchi Janfiye qishlog‘i.",note:null},
{num:184,time:"00:17:26,039 --> 00:17:28,539",arabic:"فَوْقَ مِيَاهِ بُحَيْرَةِ نُوكْ الْهَادِئَةِ",segs:null,full_uz:"Sokin Nok ko‘lining suvlari ustida.",note:null},
{num:185,time:"00:17:29,079 --> 00:17:36,680",arabic:"تَقِفُ قَرْيَةُ جَانْفِيَةَ كَوَاحِدَةٍ مِنْ أَكْبَرِ الْقُرَى الْمَبْنِيَّةِ عَلَى رَكَائِزَ خَشَبِيَّةٍ فِي الْعَالَمِ",segs:[{ar:"تَقِفُ قَرْيَةُ جَانْفِيَةَ",uz:"Janfiye qishlog‘i qad rostlab turadi"},{ar:"كَوَاحِدَةٍ مِنْ أَكْبَرِ الْقُرَى",uz:"eng katta qishloqlardan biri sifatida"},{ar:"الْمَبْنِيَّةِ عَلَى رَكَائِزَ خَشَبِيَّةٍ فِي الْعَالَمِ",uz:"dunyoda yog‘och tayanchlar ustiga qurilgan"}],full_uz:"Janfiye qishlog‘i dunyodagi yog‘och tayanchlar ustiga qurilgan eng katta qishloqlardan biri sifatida qad rostlab turadi.",note:"رَكَائِزُ — tayanchlar, ustunlar."},
{num:186,time:"00:17:36,680 --> 00:17:45,000",arabic:"مُسْتَوْطَنَةٌ مَائِيَّةٌ تَعُودُ جُذُورُهَا إِلَى أَكْثَرَ مِنْ أَرْبَعَةِ قُرُونٍ",segs:[{ar:"مُسْتَوْطَنَةٌ مَائِيَّةٌ",uz:"suv ustidagi manzilgoh"},{ar:"تَعُودُ جُذُورُهَا",uz:"uning ildizlari borib taqaladi"},{ar:"إِلَى أَكْثَرَ مِنْ أَرْبَعَةِ قُرُونٍ",uz:"to‘rt asrdan ham ko‘proq vaqtga"}],full_uz:"Ildizlari to‘rt asrdan ham ko‘proq vaqtga borib taqaladigan suv ustidagi manzilgoh.",note:"مُسْتَوْطَنَةٌ — manzilgoh, aholi yashash joyi."},
{num:187,time:"00:17:45,000 --> 00:17:52,579",arabic:"أَكْثَرُ مِنْ ثَلَاثَةِ آلَافِ مَنْزِلٍ شُيِّدَتْ فَوْقَ أَعْمِدَةٍ مَغْرُوسَةٍ عَمِيقًا فِي قَاعِ الْبُحَيْرَةِ",segs:[{ar:"أَكْثَرُ مِنْ ثَلَاثَةِ آلَافِ مَنْزِلٍ",uz:"uch mingdan ortiq uy"},{ar:"شُيِّدَتْ فَوْقَ أَعْمِدَةٍ",uz:"ustunlar ustiga qurilgan"},{ar:"مَغْرُوسَةٍ عَمِيقًا فِي قَاعِ الْبُحَيْرَةِ",uz:"ko‘l tubiga chuqur qoqilgan"}],full_uz:"Ko‘l tubiga chuqur qoqilgan ustunlar ustiga uch mingdan ortiq uy qurilgan.",note:"شُيِّدَ — qurilmoq, bunyod etilmoq. مَغْرُوسٌ — qoqilgan, yerga sanchilgan."},
{num:188,time:"00:17:52,579 --> 00:18:01,599",arabic:"لِتُشَكِّلَ مُتَاهَةً عَائِمَةً صَاغَتْهَا الْجُغْرَافِيَا وَضَرُورَاتُ الْبَقَاءِ",segs:[{ar:"لِتُشَكِّلَ مُتَاهَةً عَائِمَةً",uz:"suzib turuvchi labirint hosil qilib"},{ar:"صَاغَتْهَا الْجُغْرَافِيَا",uz:"uni geografiya shakllantirgan"},{ar:"وَضَرُورَاتُ الْبَقَاءِ",uz:"va omon qolish zaruratlari"}],full_uz:"Geografiya va omon qolish zaruratlari shakllantirgan suzib turuvchi labirintni hosil qilib.",note:"ضَرُورَاتٌ — zaruratlar, ehtiyojlar."},
{num:189,time:"00:18:01,599 --> 00:18:08,059",arabic:"يَعُودُ أَصْلُهَا إِلَى مُجْتَمَعَاتٍ لَجَأَتْ إِلَى الْمِيَاهِ",segs:[{ar:"يَعُودُ أَصْلُهَا",uz:"uning kelib chiqishi borib taqaladi"},{ar:"إِلَى مُجْتَمَعَاتٍ لَجَأَتْ إِلَى الْمِيَاهِ",uz:"suvga panoh topgan jamoalarga"}],full_uz:"Uning kelib chiqishi suvga panoh topgan jamoalarga borib taqaladi.",note:"لَجَأَ إِلَى — ...ga panoh topmoq."},
{num:190,time:"00:18:08,059 --> 00:18:11,379",arabic:"هَارِبَةً مِنْ غَزَوَاتٍ سَاحِلِيَّةٍ قَدِيمَةٍ",segs:null,full_uz:"Qadimiy qirg‘oq bosqinlaridan qochib.",note:"غَزْوَةٌ — bosqin, hujum."},
{num:191,time:"00:18:11,379 --> 00:18:15,379",arabic:"مُحَوِّلَةً الْبُحَيْرَةَ الضَّحْلَةَ إِلَى حِصْنٍ طَبِيعِيٍّ",segs:[{ar:"مُحَوِّلَةً الْبُحَيْرَةَ الضَّحْلَةَ",uz:"sayoz ko‘lni aylantirib"},{ar:"إِلَى حِصْنٍ طَبِيعِيٍّ",uz:"tabiiy qal’aga"}],full_uz:"Sayoz ko‘lni tabiiy qal’aga aylantirib.",note:"حِصْنٌ طَبِيعِيٌّ — tabiiy qal’a."},
{num:192,time:"00:18:15,379 --> 00:18:21,399",arabic:"الْيَوْمَ تَجْرِي الْحَيَاةُ بِالْكَامِلِ فَوْقَ الْمَاءِ",segs:[{ar:"الْيَوْمَ تَجْرِي الْحَيَاةُ",uz:"bugun hayot kechadi"},{ar:"بِالْكَامِلِ فَوْقَ الْمَاءِ",uz:"to‘liq suv ustida"}],full_uz:"Bugun hayot to‘liq suv ustida kechadi.",note:null},
{num:193,time:"00:18:21,400 --> 00:18:25,100",arabic:"الْعَائِلَاتُ تَتَنَقَّلُ بِقَوَارِبَ ضَيِّقَةٍ",segs:[{ar:"الْعَائِلَاتُ تَتَنَقَّلُ",uz:"oilalar qatnab yuradi"},{ar:"بِقَوَارِبَ ضَيِّقَةٍ",uz:"tor qayiqlarda"}],full_uz:"Oilalar tor qayiqlarda qatnab yuradi.",note:"تَتَنَقَّلُ — qatnab yurmoq, harakatlanmoq."},
{num:194,time:"00:18:25,100 --> 00:18:29,140",arabic:"الْأَطْفَالُ يُبْحِرُونَ نَحْوَ مَدَارِسَ عَائِمَةٍ",segs:[{ar:"الْأَطْفَالُ يُبْحِرُونَ",uz:"bolalar qayiqda suzib boradilar"},{ar:"نَحْوَ مَدَارِسَ عَائِمَةٍ",uz:"suzib yuruvchi maktablarga"}],full_uz:"Bolalar suzib yuruvchi maktablarga qayiqda boradilar.",note:"يُبْحِرُ — qayiqda suzmoq."},
{num:195,time:"00:18:29,140 --> 00:18:36,259",arabic:"وَالْأَسْوَاقُ تَنْتَقِلُ بَيْنَ الْبُيُوتِ بِهُدُوءٍ",segs:[{ar:"وَالْأَسْوَاقُ تَنْتَقِلُ",uz:"bozorlar ko‘chib yuradi"},{ar:"بَيْنَ الْبُيُوتِ بِهُدُوءٍ",uz:"uylar orasida sokinlik bilan"}],full_uz:"Bozorlar uylar orasida sokinlik bilan ko‘chib yuradi.",note:"تَنْتَقِلُ — ko‘chmoq, bir joydan boshqasiga o‘tmoq."},
{num:196,time:"00:18:36,259 --> 00:18:42,200",arabic:"هَذَا التَّلَاحُمُ النَّادِرُ بَيْنَ الْعِمَارَةِ وَالْبِيئَةِ",segs:[{ar:"هَذَا التَّلَاحُمُ النَّادِرُ",uz:"bu noyob uyg‘unlik"},{ar:"بَيْنَ الْعِمَارَةِ وَالْبِيئَةِ",uz:"me’morchilik va atrof-muhit o‘rtasidagi"}],full_uz:"Me’morchilik va atrof-muhit o‘rtasidagi bu noyob uyg‘unlik.",note:"تَلَاحُمٌ — chambarchas uyg‘unlashuv, birikish."},
{num:197,time:"00:18:42,200 --> 00:18:47,960",arabic:"يَجْعَلُ غَامْ فِيَيْهْ شَاهِدًا حَيًّا عَلَى قُدْرَةِ الْإِنْسَانِ عَلَى التَّكَيُّفِ",segs:[{ar:"يَجْعَلُ غَامْ فِيَيْهْ شَاهِدًا حَيًّا",uz:"Gam Viehni tirik guvohga aylantiradi"},{ar:"عَلَى قُدْرَةِ الْإِنْسَانِ عَلَى التَّكَيُّفِ",uz:"insonning moslasha olish qobiliyatiga"}],full_uz:"Bu Gam Viehni insonning moslasha olish qobiliyatiga tirik guvohga aylantiradi.",note:"التَّكَيُّفُ — moslashish."},
{num:198,time:"00:18:47,960 --> 00:18:51,019",arabic:"وَعَجِيبَةً تَبْدُو مُسْتَحِيلَةً",segs:null,full_uz:"Va imkonsizdek ko‘rinadigan ajoyibot.",note:"عَجِيبَةٌ — ajoyibot."},
{num:199,time:"00:18:51,019 --> 00:18:53,519",arabic:"صَاغَهَا التَّارِيخُ وَالِابْتِكَارُ",segs:null,full_uz:"Uni tarix va yangilik yaratgan.",note:"الِابْتِكَارُ — yangilik, innovatsiya."},
{num:200,time:"00:18:53,519 --> 00:18:55,960",arabic:"وَإِيقَاعُ الْبُحَيْرَةِ الْيَوْمِيُّ",segs:null,full_uz:"Va ko‘lning kundalik ritmi.",note:"إِيقَاعٌ — ritm, marom."},
{num:201,time:"00:18:56,960 --> 00:19:03,019",arabic:"شَلَّالُ بَانْجُوك",segs:null,full_uz:"Ban Giok sharsharasi.",note:null},
{num:202,time:"00:19:03,019 --> 00:19:07,160",arabic:"نَحَتَ شَلَّالُ بَانْجُوكَ عَبْرَ آلَافِ السِّنِينَ",segs:[{ar:"نَحَتَ شَلَّالُ بَانْجُوكَ",uz:"Ban Giok sharsharasi o‘yilgan"},{ar:"عَبْرَ آلَافِ السِّنِينَ",uz:"minglab yillar davomida"}],full_uz:"Ban Giok sharsharasi minglab yillar davomida shakllangan.",note:"نَحَتَ — o‘yib shakllantirmoq."},
{num:203,time:"00:19:07,160 --> 00:19:10,960",arabic:"بِفِعْلِ التَّآكُلِ الْهَادِئِ لِلْحَجَرِ الْجِيرِيِّ",segs:[{ar:"بِفِعْلِ التَّآكُلِ الْهَادِئِ",uz:"sokin yemirilish ta’sirida"},{ar:"لِلْحَجَرِ الْجِيرِيِّ",uz:"ohaktoshning"}],full_uz:"Ohaktoshning sokin yemirilishi ta’sirida.",note:"التَّآكُلُ — yemirilish, eroziya."},
{num:204,time:"00:19:10,960 --> 00:19:18,880",arabic:"لِيَنْسَابَ الْيَوْمَ عَلَى الْحُدُودِ الشَّمَالِيَّةِ لِفِيتْنَام",segs:[{ar:"لِيَنْسَابَ الْيَوْمَ",uz:"bugun oqib borishi uchun"},{ar:"عَلَى الْحُدُودِ الشَّمَالِيَّةِ لِفِيتْنَام",uz:"Vyetnamning shimoliy chegarasida"}],full_uz:"Bugun Vyetnamning shimoliy chegarasida oqib boradi.",note:"يَنْسَابُ — ravon oqmoq."},
{num:205,time:"00:19:18,880 --> 00:19:22,819",arabic:"فِي سِلْسِلَةِ مُدَرَّجَاتٍ مَائِيَّةٍ مُذْهِلَةٍ",segs:[{ar:"فِي سِلْسِلَةِ مُدَرَّجَاتٍ مَائِيَّةٍ",uz:"suvli pog‘onalar tizimida"},{ar:"مُذْهِلَةٍ",uz:"hayratlanarli"}],full_uz:"Hayratlanarli suvli pog‘onalar tizimida.",note:"مُدَرَّجَاتٌ — pog‘onalar, terassalar."},
{num:206,time:"00:19:22,819 --> 00:19:26,380",arabic:"تَمْتَدُّ قَرَابَةَ تِسْعِينَ مِتْرًا عَرْضًا",segs:[{ar:"تَمْتَدُّ",uz:"cho‘zilib yotadi"},{ar:"قَرَابَةَ تِسْعِينَ مِتْرًا عَرْضًا",uz:"eni qariyb to‘qson metr"}],full_uz:"Uning eni qariyb to‘qson metr.",note:null},
{num:207,time:"00:19:26,380 --> 00:19:34,200",arabic:"تُغَذِّيهِ مِيَاهُ نَهْرِ كْوَايْسُون",segs:null,full_uz:"Uni Kwayson daryosi suvlari oziqlantiradi.",note:"غَذَّى — oziqlantirmoq, suv bilan ta’minlamoq."},
{num:208,time:"00:19:34,200 --> 00:19:41,140",arabic:"حَيْثُ تَهْبِطُ تَيَّارَاتُهُ الْمُزْدَوِجَةُ مِنْ ارْتِفَاعٍ يَزِيدُ عَلَى سَبْعَةٍ وَعِشْرِينَ مِتْرًا",segs:[{ar:"حَيْثُ تَهْبِطُ تَيَّارَاتُهُ الْمُزْدَوِجَةُ",uz:"u yerda uning ikki oqimi tushadi"},{ar:"مِنْ ارْتِفَاعٍ يَزِيدُ عَلَى سَبْعَةٍ وَعِشْرِينَ مِتْرًا",uz:"yigirma yetti metrdan ortiq balandlikdan"}],full_uz:"U yerda uning ikki oqimi yigirma yetti metrdan ortiq balandlikdan tushadi.",note:"مُزْدَوِجٌ — ikki qismli, juft. تَيَّارٌ — oqim."},
{num:209,time:"00:19:41,140 --> 00:19:48,200",arabic:"نَاشِرَةً ضَبَابًا تَتَكَوَّنُ فِيهِ أَقْوَاسُ قُزَحٍ فَوْقَ بِرَكٍ زُمُرُّدِيَّةٍ",segs:[{ar:"نَاشِرَةً ضَبَابًا",uz:"tuman taratib"},{ar:"تَتَكَوَّنُ فِيهِ أَقْوَاسُ قُزَحٍ",uz:"unda kamalaklar hosil bo‘ladi"},{ar:"فَوْقَ بِرَكٍ زُمُرُّدِيَّةٍ",uz:"zumrad rangli hovuzlar ustida"}],full_uz:"Tuman taratib, unda zumrad rangli hovuzlar ustida kamalaklar hosil bo‘ladi.",note:"نَاشِرٌ — tarqatuvchi. قَوْسُ قُزَحٍ — kamalak."},
{num:210,time:"00:19:48,200 --> 00:19:59,000",arabic:"يَصِفُهُ الْجُغْرَافِيُّونَ بِأَنَّهُ أَحَدُ أَكْثَرِ شَلَّالَاتِ آسِيَا تَمَاثُلًا وَانْسِجَامًا فِي شَكْلِهِ الطَّبِيعِيِّ",segs:[{ar:"يَصِفُهُ الْجُغْرَافِيُّونَ",uz:"geograflar uni tasvirlaydilar"},{ar:"بِأَنَّهُ أَحَدُ أَكْثَرِ شَلَّالَاتِ آسِيَا تَمَاثُلًا وَانْسِجَامًا",uz:"Osiyodagi shakli eng mutanosib va uyg‘un sharsharalardan biri sifatida"},{ar:"فِي شَكْلِهِ الطَّبِيعِيِّ",uz:"tabiiy shaklida"}],full_uz:"Geograflar uni tabiiy shakli jihatidan Osiyodagi eng mutanosib va uyg‘un sharsharalardan biri deb tasvirlaydilar.",note:"تَمَاثُلٌ — mutanosiblik, simmetriya. انْسِجَامٌ — uyg‘unlik."},
{num:211,time:"00:19:59,000 --> 00:20:05,559",arabic:"فِي كُلِّ مَوْسِمٍ يَقْصِدُ آلَافُ الزُّوَّارِ قَاعِدَتَهُ",segs:[{ar:"فِي كُلِّ مَوْسِمٍ",uz:"har mavsumda"},{ar:"يَقْصِدُ آلَافُ الزُّوَّارِ قَاعِدَتَهُ",uz:"minglab ziyoratchilar uning etagiga yo‘l oladilar"}],full_uz:"Har mavsumda minglab ziyoratchilar uning etagiga yo‘l oladilar.",note:"يَقْصِدُ — yo‘l olmoq, qasd qilmoq. قَاعِدَةُ الشَّلَّالِ — sharshara etagi."},
{num:212,time:"00:20:05,559 --> 00:20:12,119",arabic:"يَعْبُرُونَ مَمَرَّاتٍ خَشَبِيَّةً أَوْ يَنْزَلِقُونَ بِقَوَارِبَ خَيْزُرَانٍ صَغِيرَةٍ",segs:[{ar:"يَعْبُرُونَ مَمَرَّاتٍ خَشَبِيَّةً",uz:"yog‘och yo‘laklardan o‘tadilar"},{ar:"أَوْ يَنْزَلِقُونَ بِقَوَارِبَ خَيْزُرَانٍ صَغِيرَةٍ",uz:"yoki kichik bambuk qayiqlarda sirg‘alib boradilar"}],full_uz:"Ular yog‘och yo‘laklardan o‘tadilar yoki kichik bambuk qayiqlarda sirg‘alib boradilar.",note:"يَنْزَلِقُ — sirg‘almoq."},
{num:213,time:"00:20:12,119 --> 00:20:15,220",arabic:"لِيُلَامِسُوا رَذَاذَهُ الْبَارِدَ",segs:[{ar:"لِيُلَامِسُوا",uz:"tegish uchun"},{ar:"رَذَاذَهُ الْبَارِدَ",uz:"uning sovuq sachragan suv tomchilariga"}],full_uz:"Uning sovuq suv tomchilariga tegish uchun.",note:"لَامَسَ — tegmoq. رَذَاذٌ — mayda suv tomchilari."},
{num:214,time:"00:20:15,220 --> 00:20:22,019",arabic:"تُحِيطُ بِهِ قِمَمٌ كِلْسِيَّةٌ تَشَكَّلَتْ عَبْرَ مَلَايِينَ السِّنِينَ",segs:[{ar:"تُحِيطُ بِهِ قِمَمٌ كِلْسِيَّةٌ",uz:"uni ohaktoshli cho‘qqilar o‘rab turadi"},{ar:"تَشَكَّلَتْ عَبْرَ مَلَايِينَ السِّنِينَ",uz:"millionlab yillar davomida shakllangan"}],full_uz:"Uni millionlab yillar davomida shakllangan ohaktoshli cho‘qqilar o‘rab turadi.",note:"كِلْسِيٌّ — ohaktoshga oid."},
{num:215,time:"00:20:22,019 --> 00:20:25,259",arabic:"لِيَبْدُوَ الْمَشْهَدُ شِعْرِيًّا مِنْ كُلِّ زَاوِيَةٍ",segs:[{ar:"لِيَبْدُوَ الْمَشْهَدُ شِعْرِيًّا",uz:"manzara she’riy ko‘rinsin"},{ar:"مِنْ كُلِّ زَاوِيَةٍ",uz:"har bir burchakdan"}],full_uz:"Manzara har bir burchakdan she’riy ko‘rinadi.",note:"شِعْرِيٌّ — she’riy, poetik."},
{num:216,time:"00:20:25,259 --> 00:20:30,140",arabic:"عَجِيبَةٌ صَاغَهَا الْمَاءُ وَالزَّمَنُ فِي هُدُوءٍ مُتَوَاصِلٍ",segs:[{ar:"عَجِيبَةٌ",uz:"ajoyibot"},{ar:"صَاغَهَا الْمَاءُ وَالزَّمَنُ",uz:"uni suv va zamon shakllantirgan"},{ar:"فِي هُدُوءٍ مُتَوَاصِلٍ",uz:"uzluksiz sokinlikda"}],full_uz:"Suv va zamon uzluksiz sokinlikda shakllantirgan ajoyibot.",note:"مُتَوَاصِلٌ — uzluksiz, davomli."},
{num:217,time:"00:20:30,140 --> 00:20:38,079",arabic:"جُزُرُ الْأُورُوسِ الْعَائِمَةُ",segs:null,full_uz:"Suzuvchi Uros orollari.",note:null},
{num:218,time:"00:20:38,079 --> 00:20:44,960",arabic:"عَلَى ارْتِفَاعٍ يَزِيدُ عَنْ ثَلَاثَةِ آلَافٍ وَثَمَانِمِائَةِ مِتْرٍ فِي جِبَالِ الْأَنْدِيزِ",segs:[{ar:"عَلَى ارْتِفَاعٍ يَزِيدُ عَنْ ثَلَاثَةِ آلَافٍ وَثَمَانِمِائَةِ مِتْرٍ",uz:"uch ming sakkiz yuz metrdan oshadigan balandlikda"},{ar:"فِي جِبَالِ الْأَنْدِيزِ",uz:"And tog‘larida"}],full_uz:"And tog‘larida uch ming sakkiz yuz metrdan oshadigan balandlikda.",note:null},
{num:219,time:"00:20:44,960 --> 00:20:51,259",arabic:"تَطْفُو جُزُرُ الْأُورُوسِ فَوْقَ سَطْحِ بُحَيْرَةِ تِيتِيكَاكَا الْمُتَلَأْلِئَةِ",segs:[{ar:"تَطْفُو جُزُرُ الْأُورُوسِ",uz:"Uros orollari suzib turadi"},{ar:"فَوْقَ سَطْحِ بُحَيْرَةِ تِيتِيكَاكَا الْمُتَلَأْلِئَةِ",uz:"yarqiragan Titikaka ko‘li yuzasida"}],full_uz:"Uros orollari yarqiragan Titikaka ko‘li yuzasida suzib turadi.",note:"تَطْفُو — suv yuzida suzmoq."},
{num:220,time:"00:20:51,259 --> 00:20:55,200",arabic:"أَعْلَى بُحَيْرَةٍ صَالِحَةٍ لِلْمِلَاحَةِ فِي الْعَالَمِ",segs:[{ar:"أَعْلَى بُحَيْرَةٍ",uz:"eng baland ko‘l"},{ar:"صَالِحَةٍ لِلْمِلَاحَةِ فِي الْعَالَمِ",uz:"dunyoda kemachilik uchun yaroqli"}],full_uz:"Dunyoda kemachilik uchun yaroqli eng baland ko‘l.",note:"الْمِلَاحَةُ — kemachilik, suv transporti."},
{num:221,time:"00:20:55,200 --> 00:21:03,000",arabic:"هَذِهِ الْجُزُرُ لَيْسَتْ مِنْ صُنْعِ الطَّبِيعَةِ بَلْ بُنِيَتْ بِالْكَامِلِ بِأَيْدِي الْبَشَرِ",segs:[{ar:"هَذِهِ الْجُزُرُ لَيْسَتْ مِنْ صُنْعِ الطَّبِيعَةِ",uz:"bu orollar tabiat tomonidan yaratilmagan"},{ar:"بَلْ بُنِيَتْ بِالْكَامِلِ بِأَيْدِي الْبَشَرِ",uz:"balki butunlay inson qo‘llari bilan qurilgan"}],full_uz:"Bu orollar tabiat tomonidan yaratilmagan, balki butunlay inson qo‘llari bilan qurilgan.",note:"بُنِيَتْ بِأَيْدِي الْبَشَرِ — insonlar qo‘llari bilan qurilgan."},
{num:222,time:"00:21:03,000 --> 00:21:11,440",arabic:"مِنْ طَبَقَاتٍ مُتَرَاكِمَةٍ مِنَ الْقَصَبِ تُجَدَّدُ كُلَّ ثَلَاثَةٍ إِلَى أَرْبَعَةِ أَشْهُرٍ كَيْ تَبْقَى طَافِيَةً",segs:[{ar:"مِنْ طَبَقَاتٍ مُتَرَاكِمَةٍ مِنَ الْقَصَبِ",uz:"to‘planib yotgan qamish qatlamlaridan"},{ar:"تُجَدَّدُ كُلَّ ثَلَاثَةٍ إِلَى أَرْبَعَةِ أَشْهُرٍ",uz:"har uch-to‘rt oyda yangilanadigan"},{ar:"كَيْ تَبْقَى طَافِيَةً",uz:"suv yuzida suzib turishi uchun"}],full_uz:"Ular suv yuzida suzib turishi uchun har uch-to‘rt oyda yangilanadigan to‘planib yotgan qamish qatlamlaridan qurilgan.",note:"قَصَبٌ — qamish. تَجَدَّدَ — yangilanmoq. طَافٍ — suv yuzida suzib turgan."},
{num:223,time:"00:21:11,440 --> 00:21:17,500",arabic:"يَصِلُ عَرْضُ بَعْضِ الْجُزُرِ إِلَى نَحْوِ ثَلَاثِينَ مِتْرًا",segs:[{ar:"يَصِلُ عَرْضُ بَعْضِ الْجُزُرِ",uz:"ba’zi orollarning eni yetadi"},{ar:"إِلَى نَحْوِ ثَلَاثِينَ مِتْرًا",uz:"taxminan o‘ttiz metrga"}],full_uz:"Ba’zi orollarning eni taxminan o‘ttiz metrga yetadi.",note:null},
{num:224,time:"00:21:17,500 --> 00:21:20,700",arabic:"تُثَبَّتُ بِالْحِبَالِ وَالْأَوْتَادِ الْخَشَبِيَّةِ",segs:null,full_uz:"Ular arqonlar va yog‘och qoziqlar bilan mahkamlanadi.",note:"تُثَبَّتُ — mahkamlanadi. وَتَدٌ — qoziq."},
{num:225,time:"00:21:20,700 --> 00:21:25,299",arabic:"لَكِنَّهَا تَظَلُّ فِي حَرَكَةٍ دَائِمَةٍ مَعَ الرِّيَاحِ وَالْمِيَاهِ",segs:[{ar:"لَكِنَّهَا تَظَلُّ فِي حَرَكَةٍ دَائِمَةٍ",uz:"ammo ular doimo harakatda qoladi"},{ar:"مَعَ الرِّيَاحِ وَالْمِيَاهِ",uz:"shamol va suvlar bilan"}],full_uz:"Ammo ular shamol va suvlar bilan doimo harakatda qoladi.",note:"تَظَلُّ — davom etmoq, holatda qolmoq."},
{num:226,time:"00:21:25,299 --> 00:21:29,680",arabic:"لِأَكْثَرَ مِنْ خَمْسَةِ قُرُونٍ",segs:null,full_uz:"Besh asrdan ortiq vaqt davomida.",note:null},
{num:227,time:"00:21:29,680 --> 00:21:34,140",arabic:"عَاشَ شَعْبُ الْأُورُوسِ حَيَاةً عَائِمَةً مُكْتَفِيَةً ذَاتِيًّا",segs:[{ar:"عَاشَ شَعْبُ الْأُورُوسِ",uz:"Uros xalqi yashagan"},{ar:"حَيَاةً عَائِمَةً مُكْتَفِيَةً ذَاتِيًّا",uz:"o‘zini o‘zi ta’minlaydigan suzuvchi hayot kechirib"}],full_uz:"Uros xalqi o‘zini o‘zi ta’minlaydigan suzuvchi hayot kechirgan.",note:"مُكْتَفٍ ذَاتِيًّا — o‘zini o‘zi ta’minlaydigan."},
{num:228,time:"00:21:34,140 --> 00:21:40,299",arabic:"شَيَّدُوا مَنَازِلَهُمْ وَمَدَارِسَهُمْ وَأَبْرَاجَ الْمُرَاقَبَةِ فَوْقَ الْمَاءِ",segs:[{ar:"شَيَّدُوا مَنَازِلَهُمْ وَمَدَارِسَهُمْ",uz:"ular uylar va maktablarini qurdilar"},{ar:"وَأَبْرَاجَ الْمُرَاقَبَةِ",uz:"va kuzatuv minoralarini"},{ar:"فَوْقَ الْمَاءِ",uz:"suv ustida"}],full_uz:"Ular uylar, maktablar va kuzatuv minoralarini suv ustida qurdilar.",note:"شَيَّدَ — bunyod etmoq. بُرْجُ الْمُرَاقَبَةِ — kuzatuv minorasi."},
{num:229,time:"00:21:40,299 --> 00:21:45,059",arabic:"حَضَارَةٌ غَيْرُ مُحْتَمَلَةٍ",segs:null,full_uz:"Tasavvur qilish qiyin bo‘lgan sivilizatsiya.",note:"مُحْتَمَلٌ — ehtimoliy, mumkin bo‘lgan; bu yerda matn ma’nosi biroz noaniq."},
{num:230,time:"00:21:45,059 --> 00:21:47,480",arabic:"ارْتَفَعَتْ مِنَ الْقَصَبِ وَالصَّبْرِ",segs:null,full_uz:"Qamish va sabrdan bunyod bo‘lgan.",note:"ارْتَفَعَتْ — ko‘tarildi, qad rostladi."},
{num:231,time:"00:21:47,480 --> 00:21:51,980",arabic:"وَنَبَضَ بِهَا بُحَيْرَةٌ مُعَلَّقَةٌ فِي السَّمَاءِ",segs:[{ar:"وَنَبَضَ بِهَا",uz:"va uning ichida jo‘sh urdi"},{ar:"بُحَيْرَةٌ مُعَلَّقَةٌ فِي السَّمَاءِ",uz:"osmonda muallaq turgan ko‘l"}],full_uz:"Va uning ichida go‘yo osmonda muallaq turgan ko‘l jo‘sh urdi.",note:"مُعَلَّقٌ — muallaq, osilib turgan. Bu jumla manba matnida uslubiy jihatdan noaniq."},
{num:232,time:"00:21:51,980 --> 00:21:57,019",arabic:"مُرْتَفَعَاتُ كَامِيرُونَ فِي مَالَيْزِيَا",segs:null,full_uz:"Malayziyadagi Kameron tog‘liklari.",note:null},
{num:233,time:"00:21:57,019 --> 00:22:03,639",arabic:"تَمْتَدُّ مُرْتَفَعَاتُ كَامِيرُونَ عَلَى طُولِ سِلْسِلَةِ تِيتْوَانْكْسَا الْجَبَلِيَّةِ",segs:[{ar:"تَمْتَدُّ مُرْتَفَعَاتُ كَامِيرُونَ",uz:"Kameron tog‘liklari cho‘zilib yotadi"},{ar:"عَلَى طُولِ سِلْسِلَةِ تِيتْوَانْكْسَا الْجَبَلِيَّةِ",uz:"Titiwangsa tog‘ tizmasi bo‘ylab"}],full_uz:"Kameron tog‘liklari Titiwangsa tog‘ tizmasi bo‘ylab cho‘zilib yotadi.",note:null},
{num:234,time:"00:22:03,639 --> 00:22:10,759",arabic:"هَضْبَةٌ شَاسِعَةٌ نَحَتَتْهَا أَكْثَرُ مِنْ مِائَةِ مِلْيُونِ سَنَةٍ مِنَ الِارْتِفَاعَاتِ التَّكْتُونِيَّةِ",segs:[{ar:"هَضْبَةٌ شَاسِعَةٌ",uz:"ulkan plato"},{ar:"نَحَتَتْهَا أَكْثَرُ مِنْ مِائَةِ مِلْيُونِ سَنَةٍ",uz:"uni yuz million yildan ortiq vaqt shakllantirgan"},{ar:"مِنَ الِارْتِفَاعَاتِ التَّكْتُونِيَّةِ",uz:"tektonik ko‘tarilishlar bilan"}],full_uz:"Tektonik ko‘tarilishlar natijasida yuz million yildan ortiq vaqt davomida shakllangan ulkan plato.",note:"هَضْبَةٌ — plato, yassi tog‘lik."},
{num:235,time:"00:22:10,759 --> 00:22:13,019",arabic:"وَأَمْطَارِ الرِّيَاحِ الْمُوسِمِيَّةِ",segs:null,full_uz:"Va musson yomg‘irlari.",note:null},
{num:236,time:"00:22:13,019 --> 00:22:20,099",arabic:"تَرْتَفِعُ إِلَى نَحْوِ أَلْفٍ وَثَمَانِمِائَةِ مِتْرٍ",segs:null,full_uz:"U qariyb bir ming sakkiz yuz metr balandlikka ko‘tariladi.",note:null},
{num:237,time:"00:22:20,099 --> 00:22:23,619",arabic:"مُتَحَدِّيَةً حَرَارَةَ الْمَنَاطِقِ الِاسْتِوَائِيَّةِ",segs:[{ar:"مُتَحَدِّيَةً حَرَارَةَ",uz:"issiqligiga qarshi turib"},{ar:"الْمَنَاطِقِ الِاسْتِوَائِيَّةِ",uz:"tropik hududlarning"}],full_uz:"Tropik hududlarning issiqligiga qarshi turib.",note:"مُتَحَدٍّ — qarshi turuvchi."},
{num:238,time:"00:22:23,619 --> 00:22:26,240",arabic:"بِدَرَجَاتِ حَرَارَةٍ مُعْتَدِلَةٍ",segs:null,full_uz:"Mo‘tadil harorat bilan.",note:"مُعْتَدِلٌ — mo‘tadil."},
{num:239,time:"00:22:26,240 --> 00:22:30,019",arabic:"لَا تَتَجَاوَزُ أَوَائِلَ الْعِشْرِينَ مِئَوِيًّا",segs:null,full_uz:"Selsiy bo‘yicha yigirmalarning boshidan oshmaydi.",note:"أَوَائِلُ الْعِشْرِينَ — yigirmalarning dastlabki darajalari."},
{num:240,time:"00:22:30,019 --> 00:22:36,500",arabic:"لِتَصْنَعَ وَاحِدًا مِنْ أَغْرَبِ الْمُنَاخَاتِ الْمَحَلِّيَّةِ فِي جَنُوبِ شَرْقِ آسِيَا",segs:[{ar:"لِتَصْنَعَ وَاحِدًا مِنْ أَغْرَبِ الْمُنَاخَاتِ الْمَحَلِّيَّةِ",uz:"eng g‘alati mahalliy iqlimlardan birini hosil qilib"},{ar:"فِي جَنُوبِ شَرْقِ آسِيَا",uz:"Janubi-Sharqiy Osiyoda"}],full_uz:"Janubi-Sharqiy Osiyodagi eng g‘alati mahalliy iqlimlardan birini hosil qiladi.",note:"الْمَنَاخُ الْمَحَلِّيُّ — mahalliy iqlim."},
{num:241,time:"00:22:36,500 --> 00:22:43,180",arabic:"عِنْدَمَا وَصَلَ الْمَسَّاحُونَ الْبِرِيطَانِيُّونَ فِي عِشْرِينِيَّاتِ الْقَرْنِ الْمَاضِي",segs:[{ar:"عِنْدَمَا وَصَلَ الْمَسَّاحُونَ الْبِرِيطَانِيُّونَ",uz:"britaniyalik geodezistlar kelganida"},{ar:"فِي عِشْرِينِيَّاتِ الْقَرْنِ الْمَاضِي",uz:"o‘tgan asrning 1920-yillarida"}],full_uz:"O‘tgan asrning 1920-yillarida britaniyalik geodezistlar kelganida.",note:"الْمَسَّاحُونَ — geodezistlar, o‘lchovchilar."},
{num:242,time:"00:22:43,180 --> 00:22:48,539",arabic:"حَوَّلُوا هَذِهِ التِّلَالَةَ الْمُتَمَوِّجَةَ إِلَى مَزَارِعَ مُدَرَّجَةٍ",segs:[{ar:"حَوَّلُوا هَذِهِ التِّلَالَةَ الْمُتَمَوِّجَةَ",uz:"bu to‘lqinsimon tepaliklarni aylantirdilar"},{ar:"إِلَى مَزَارِعَ مُدَرَّجَةٍ",uz:"terrasali xo‘jaliklarga"}],full_uz:"Ular bu to‘lqinsimon tepaliklarni terrasali xo‘jaliklarga aylantirdilar.",note:"مُدَرَّجٌ — pog‘onali, terrasali."},
{num:243,time:"00:22:48,539 --> 00:22:54,779",arabic:"وَاضِعِينَ الْأَسَاسَ لِصِنَاعَةِ الشَّايِ الَّتِي تُغَطِّي الْيَوْمَ آلَافَ الْهَكْتَارَاتِ",segs:[{ar:"وَاضِعِينَ الْأَسَاسَ لِصِنَاعَةِ الشَّايِ",uz:"choy sanoatiga asos solib"},{ar:"الَّتِي تُغَطِّي الْيَوْمَ آلَافَ الْهَكْتَارَاتِ",uz:"bugun minglab gektarni egallagan"}],full_uz:"Bugun minglab gektarni egallagan choy sanoatiga asos solib.",note:"وَضَعَ الْأَسَاسَ لِـ — ...ga asos solmoq."},
{num:244,time:"00:22:54,779 --> 00:23:02,559",arabic:"كُلُّ مُدَرَّجٍ زُمُرُّدِيٍّ يَتْبَعُ انْحِنَاءَاتِ الْمُنْحَدَرَاتِ الْغَرَانِيتِيَّةِ الْقَدِيمَةِ",segs:[{ar:"كُلُّ مُدَرَّجٍ زُمُرُّدِيٍّ",uz:"har bir zumrad rangli terassa"},{ar:"يَتْبَعُ انْحِنَاءَاتِ الْمُنْحَدَرَاتِ الْغَرَانِيتِيَّةِ الْقَدِيمَةِ",uz:"qadimiy granit yonbag‘irlarining egri chiziqlariga ergashadi"}],full_uz:"Har bir zumrad rangli terassa qadimiy granit yonbag‘irlarining egri chiziqlariga ergashadi.",note:"انْحِنَاءٌ — egri chiziq, bukilish."},
{num:245,time:"00:23:02,559 --> 00:23:06,839",arabic:"كَخَرِيطَةٍ حَيَّةٍ لِتَارِيخِ الْأَرْضِ الْعَمِيقِ",segs:[{ar:"كَخَرِيطَةٍ حَيَّةٍ",uz:"tirik xaritadek"},{ar:"لِتَارِيخِ الْأَرْضِ الْعَمِيقِ",uz:"yerning chuqur tarixi uchun"}],full_uz:"Yerning chuqur tarixi aks etgan tirik xaritadek.",note:null},
{num:246,time:"00:23:06,839 --> 00:23:14,659",arabic:"الْيَوْمَ يَتَجَوَّلُ الزُّوَّارُ بَيْنَ الْوِدْيَانِ الْبَارِدَةِ الْمَكْسُوَّةِ بِأَوْرَاقِ الشَّايِ",segs:[{ar:"الْيَوْمَ يَتَجَوَّلُ الزُّوَّارُ",uz:"bugun ziyoratchilar kezadilar"},{ar:"بَيْنَ الْوِدْيَانِ الْبَارِدَةِ",uz:"sovuq vodiylar orasida"},{ar:"الْمَكْسُوَّةِ بِأَوْرَاقِ الشَّايِ",uz:"choy barglari bilan qoplangan"}],full_uz:"Bugun ziyoratchilar choy barglari bilan qoplangan sovuq vodiylar orasida kezadilar.",note:null},
{num:247,time:"00:23:14,659 --> 00:23:20,259",arabic:"شَاهِدِينَ كَيْفَ تَمْتَزِجُ الْجِيُولُوجْيَا وَالْمُنَاخُ وَالْعَمَلُ الْبَشَرِيُّ",segs:[{ar:"شَاهِدِينَ كَيْفَ تَمْتَزِجُ",uz:"qanday uyg‘unlashishini ko‘rib"},{ar:"الْجِيُولُوجْيَا وَالْمُنَاخُ وَالْعَمَلُ الْبَشَرِيُّ",uz:"geologiya, iqlim va inson mehnatining"}],full_uz:"Geologiya, iqlim va inson mehnatining qanday uyg‘unlashishini ko‘rib.",note:null},
{num:248,time:"00:23:20,259 --> 00:23:25,700",arabic:"فِي وَاحِدٍ مِنْ أَكْثَرِ الْمَنَاظِرِ الزِّرَاعِيَّةِ هُدُوءًا عَلَى كَوْكَبِنَا",segs:[{ar:"فِي وَاحِدٍ مِنْ أَكْثَرِ الْمَنَاظِرِ الزِّرَاعِيَّةِ هُدُوءًا",uz:"eng sokin qishloq xo‘jaligi manzaralaridan birida"},{ar:"عَلَى كَوْكَبِنَا",uz:"sayyoramizda"}],full_uz:"Sayyoramizdagi eng sokin qishloq xo‘jaligi manzaralaridan birida.",note:null},
{num:249,time:"00:23:25,700 --> 00:23:32,500",arabic:"جَزِيرَةُ مُورِيَا تَنْهَضُ مُورِيَا مِنْ جَنُوبِ الْمُحِيطِ الْهَادِئِ",segs:[{ar:"جَزِيرَةُ مُورِيَا",uz:"Muriya oroli"},{ar:"تَنْهَضُ مُورِيَا مِنْ جَنُوبِ الْمُحِيطِ الْهَادِئِ",uz:"Janubiy Tinch okeanidan qad rostlaydi"}],full_uz:"Muriya oroli Janubiy Tinch okeanidan qad rostlaydi.",note:"Manba jumlasida «جَزِيرَةُ مُورِيَا تَنْهَضُ مُورِيَا» shaklida takror bor."},
{num:250,time:"00:23:32,500 --> 00:23:35,059",arabic:"كَتَاجٍ زُمُرُّدِيٍّ مُتَشَظٍّ",segs:null,full_uz:"Parchalangan zumrad tojidek.",note:"مُتَشَظٍّ — parchalanib ketgan."},
{num:251,time:"00:23:35,059 --> 00:23:41,759",arabic:"تُحْفَةٌ جِيُولُوجِيَّةٌ صَاغَهَا بُرْكَانٌ انْهَارَ قَبْلَ أَكْثَرَ مِنْ مِلْيُونَيْ عَامٍ",segs:[{ar:"تُحْفَةٌ جِيُولُوجِيَّةٌ",uz:"geologik durdona"},{ar:"صَاغَهَا بُرْكَانٌ انْهَارَ",uz:"uni qulagan vulqon shakllantirgan"},{ar:"قَبْلَ أَكْثَرَ مِنْ مِلْيُونَيْ عَامٍ",uz:"ikki million yildan ko‘proq oldin"}],full_uz:"Ikki million yildan ko‘proq oldin qulagan vulqon shakllantirgan geologik durdona.",note:"انْهَارَ — qulamoq."},
{num:252,time:"00:23:41,759 --> 00:23:45,500",arabic:"قِمَمُهَا الثَّمَانِيَةُ الْحَادَّةُ",segs:null,full_uz:"Uning sakkizta o‘tkir cho‘qqisi.",note:null},
{num:253,time:"00:23:45,500 --> 00:23:51,960",arabic:"وَبُحَيْرَتُهَا الَّتِي تَمْتَدُّ عَلَى مَسَاحَةٍ تُقَارِبُ مِائَةَ كِيلُومِتْرٍ مُرَبَّعٍ",segs:[{ar:"وَبُحَيْرَتُهَا",uz:"va uning ko‘li"},{ar:"الَّتِي تَمْتَدُّ عَلَى مَسَاحَةٍ",uz:"maydonni egallaydigan"},{ar:"تُقَارِبُ مِائَةَ كِيلُومِتْرٍ مُرَبَّعٍ",uz:"qariyb yuz kvadrat kilometr"}],full_uz:"Va qariyb yuz kvadrat kilometr maydonni egallaydigan ko‘li.",note:"مَسَاحَةٌ — maydon."},
{num:254,time:"00:23:51,960 --> 00:23:58,380",arabic:"تُشَكِّلُ وَاحِدًا مِنْ أَكْثَرِ الْمُدَرَّجَاتِ الطَّبِيعِيَّةِ كَمَالًا عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"تُشَكِّلُ وَاحِدًا مِنْ أَكْثَرِ الْمُدَرَّجَاتِ الطَّبِيعِيَّةِ كَمَالًا",uz:"eng mukammal tabiiy terassalardan birini hosil qiladi"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzida"}],full_uz:"Yer yuzidagi eng mukammal tabiiy terassalardan birini hosil qiladi.",note:"كَمَالٌ — mukammallik."},
{num:255,time:"00:23:58,380 --> 00:24:07,200",arabic:"عَلَى طُولِ الشَّاطِئِ تَقِفُ الْأَكْوَاخُ الْعَائِمَةُ فَوْقَ رَكَائِزَ خَشَبِيَّةٍ مَغْرُوسَةٍ فِي الشُّعُبِ الْمَرْجَانِيَّةِ",segs:[{ar:"عَلَى طُولِ الشَّاطِئِ",uz:"sohil bo‘ylab"},{ar:"تَقِفُ الْأَكْوَاخُ الْعَائِمَةُ",uz:"suzuvchi kulbalar qad rostlaydi"},{ar:"فَوْقَ رَكَائِزَ خَشَبِيَّةٍ مَغْرُوسَةٍ",uz:"qoqilgan yog‘och tayanchlar ustida"},{ar:"فِي الشُّعُبِ الْمَرْجَانِيَّةِ",uz:"marjon riflariga"}],full_uz:"Sohil bo‘ylab marjon riflariga qoqilgan yog‘och tayanchlar ustida suzuvchi kulbalar qad rostlaydi.",note:"أَكْوَاخٌ — kulbalar. رَكَائِزُ — tayanchlar."},
{num:256,time:"00:24:07,200 --> 00:24:15,319",arabic:"صَدًى مِعْمَارِيًّا حَدِيثًا لِمَنَازِلِ بُولِينِيزِيَا الْقَدِيمَةِ الْمَبْنِيَّةِ عَلَى الْأَعْمِدَةِ",segs:[{ar:"صَدًى مِعْمَارِيًّا حَدِيثًا",uz:"zamonaviy me’moriy aks-sado"},{ar:"لِمَنَازِلِ بُولِينِيزِيَا الْقَدِيمَةِ",uz:"qadimgi Polineziya uylarining"},{ar:"الْمَبْنِيَّةِ عَلَى الْأَعْمِدَةِ",uz:"ustunlar ustiga qurilgan"}],full_uz:"Ustunlar ustiga qurilgan qadimgi Polineziya uylarining zamonaviy me’moriy aks-sadosi.",note:"صَدًى — aks-sado, bu yerda majozan o‘xshashlik."},
{num:257,time:"00:24:15,319 --> 00:24:21,240",arabic:"تَجْذِبُ قَنَوَاتُ الْجَزِيرَةِ أَسْمَاكَ قُرُوشِ الشُّعُبِ",segs:[{ar:"تَجْذِبُ قَنَوَاتُ الْجَزِيرَةِ",uz:"orol kanallari jalb qiladi"},{ar:"أَسْمَاكَ قُرُوشِ الشُّعُبِ",uz:"rif akulalarini"}],full_uz:"Orol kanallari rif akulalarini jalb qiladi.",note:"تَجْذِبُ — jalb qilmoq."},
{num:258,time:"00:24:21,240 --> 00:24:25,279",arabic:"ذَاتَ الْأَطْرَافِ السَّوْدَاءِ وَقُرُوشَ اللَّيْمُونِ",segs:[{ar:"ذَاتَ الْأَطْرَافِ السَّوْدَاءِ",uz:"qora uchli"},{ar:"وَقُرُوشَ اللَّيْمُونِ",uz:"va limon akulalarini"}],full_uz:"Qora uchli rif akulalari va limon akulalarini.",note:"قُرُوشُ اللَّيْمُونِ — limon akulalari."},
{num:259,time:"00:24:25,279 --> 00:24:30,240",arabic:"فِي لِقَاءَاتٍ آمِنَةٍ وَقَرِيبَةٍ تُدْهِشُ الزُّوَّارَ",segs:[{ar:"فِي لِقَاءَاتٍ آمِنَةٍ وَقَرِيبَةٍ",uz:"xavfsiz va yaqin uchrashuvlarda"},{ar:"تُدْهِشُ الزُّوَّارَ",uz:"ziyoratchilarni hayratga soladigan"}],full_uz:"Ziyoratchilarni hayratga soladigan xavfsiz va yaqin uchrashuvlarda.",note:"تُدْهِشُ — hayratga solmoq."},
{num:260,time:"00:24:30,240 --> 00:24:35,200",arabic:"سَوَاءٌ وَهُمْ يَجْدِفُونَ فَوْقَ مِيَاهٍ صَافِيَةٍ كَالزُّجَاجِ",segs:[{ar:"سَوَاءٌ وَهُمْ يَجْدِفُونَ",uz:"ular qayiq eshkak eshib ketayotgan bo‘ladimi"},{ar:"فَوْقَ مِيَاهٍ صَافِيَةٍ كَالزُّجَاجِ",uz:"shishadek tiniq suvlar ustida"}],full_uz:"Ular shishadek tiniq suvlarda eshkak eshib ketayotgan bo‘ladimi...",note:"يَجْدِفُ — eshkak eshmoq."},
{num:261,time:"00:24:35,200 --> 00:24:39,539",arabic:"أَوْ يَتَسَلَّقُونَ مُنْحَدَرَاتِ الْفُوَّهَةِ الْبُرْكَانِيَّةِ",segs:[{ar:"أَوْ يَتَسَلَّقُونَ",uz:"yoki ular ko‘tarilayotgan bo‘ladimi"},{ar:"مُنْحَدَرَاتِ الْفُوَّهَةِ الْبُرْكَانِيَّةِ",uz:"vulqon krateri yonbag‘irlariga"}],full_uz:"Yoki vulqon krateri yonbag‘irlariga ko‘tarilayotgan bo‘ladimi...",note:"الْفُوَّهَةُ الْبُرْكَانِيَّةُ — vulqon krateri."},
{num:262,time:"00:24:39,539 --> 00:24:47,680",arabic:"تَكْشِفُ مُورِيَا عَنْ نَفْسِهَا كَتَنَاغُمٍ نَادِرٍ بَيْنَ الْجِيُولُوجْيَا الْجَامِحَةِ",segs:[{ar:"تَكْشِفُ مُورِيَا عَنْ نَفْسِهَا",uz:"Muriya o‘zini namoyon qiladi"},{ar:"كَتَنَاغُمٍ نَادِرٍ",uz:"noyob uyg‘unlik sifatida"},{ar:"بَيْنَ الْجِيُولُوجْيَا الْجَامِحَةِ",uz:"jo‘shqin geologiya o‘rtasidagi"}],full_uz:"Muriya o‘zini jo‘shqin geologiya o‘rtasidagi noyob uyg‘unlik sifatida namoyon qiladi.",note:"جَامِحٌ — jo‘shqin, jilovlanmagan."},
{num:263,time:"00:24:47,680 --> 00:24:49,720",arabic:"وَثَقَافَةِ جَزِيرِيَّةٍ",segs:null,full_uz:"Va orol madaniyati.",note:null},
{num:264,time:"00:24:49,720 --> 00:24:52,900",arabic:"وَنَبْضِ الْمُحِيطِ الْحَيِّ",segs:null,full_uz:"Va tirik okeanning jo‘shqinligi.",note:"نَبْضٌ — urish, jo‘shqinlik."},
{num:265,time:"00:24:52,900 --> 00:24:56,920",arabic:"كُهُوفُ دَرَاخْ فِي مَايُورْكَا",segs:null,full_uz:"Mayorkadagi Drax g‘orlari.",note:null},
{num:266,time:"00:24:56,920 --> 00:25:00,880",arabic:"تَشَكَّلَتْ كُهُوفُ دَرَاخْ عَبْرَ مَلَايِينَ السِّنِينَ",segs:[{ar:"تَشَكَّلَتْ كُهُوفُ دَرَاخْ",uz:"Drax g‘orlari shakllangan"},{ar:"عَبْرَ مَلَايِينَ السِّنِينَ",uz:"millionlab yillar davomida"}],full_uz:"Drax g‘orlari millionlab yillar davomida shakllangan.",note:null},
{num:267,time:"00:25:00,880 --> 00:25:04,880",arabic:"نَتِيجَةَ ذَوَبَانِ الْحَجَرِ الْجِيرِيِّ بِبُطْءٍ",segs:[{ar:"نَتِيجَةَ ذَوَبَانِ الْحَجَرِ الْجِيرِيِّ",uz:"ohaktoshning erishi natijasida"},{ar:"بِبُطْءٍ",uz:"sekin-asta"}],full_uz:"Ohaktoshning sekin-asta erishi natijasida.",note:"ذَوَبَانٌ — erish."},
{num:268,time:"00:25:04,880 --> 00:25:10,279",arabic:"لِتَغْدُوَ عَالَمًا تَحْتَ الْأَرْضِ",segs:[{ar:"لِتَغْدُوَ عَالَمًا",uz:"bir olamga aylanishi uchun"},{ar:"تَحْتَ الْأَرْضِ",uz:"yer ostidagi"}],full_uz:"Yer ostidagi bir olamga aylanishi uchun.",note:"غَدَا — aylanmoq, bo‘lmoq."},
{num:269,time:"00:25:10,279 --> 00:25:14,839",arabic:"تَتَحَوَّلُ فِيهِ الْجِيُولُوجْيَا إِلَى عِمَارَةٍ طَبِيعِيَّةٍ",segs:[{ar:"تَتَحَوَّلُ فِيهِ الْجِيُولُوجْيَا",uz:"unda geologiya aylanadi"},{ar:"إِلَى عِمَارَةٍ طَبِيعِيَّةٍ",uz:"tabiiy me’morchilikka"}],full_uz:"Unda geologiya tabiiy me’morchilikka aylanadi.",note:"عِمَارَةٌ طَبِيعِيَّةٌ — tabiiy me’morchilik."},
{num:270,time:"00:25:14,839 --> 00:25:22,500",arabic:"تَمْتَدُّ الْأَنْفَاقُ لِمَسَافَةٍ تُقَارِبُ ثَلَاثَةَ كِيلُومِتْرَاتٍ تَحْتَ السَّاحِلِ الشَّرْقِيِّ لِلْجَزِيرَةِ",segs:[{ar:"تَمْتَدُّ الْأَنْفَاقُ لِمَسَافَةٍ",uz:"tunnellar masofaga cho‘ziladi"},{ar:"تُقَارِبُ ثَلَاثَةَ كِيلُومِتْرَاتٍ",uz:"qariyb uch kilometr bo‘lgan"},{ar:"تَحْتَ السَّاحِلِ الشَّرْقِيِّ لِلْجَزِيرَةِ",uz:"orolning sharqiy sohili ostida"}],full_uz:"Tunnellar orolning sharqiy sohili ostida qariyb uch kilometr masofaga cho‘ziladi.",note:null},
{num:271,time:"00:25:22,500 --> 00:25:28,779",arabic:"فِي دَاخِلِهَا تَرْتَفِعُ الصَّوَاعِدُ وَالْهَوَابِطُ",segs:null,full_uz:"Ularning ichida stalagmitlar va stalaktitlar ko‘tarilib turadi.",note:"الصَّوَاعِدُ — stalagmitlar. الْهَوَابِطُ — stalaktitlar."},
{num:272,time:"00:25:28,779 --> 00:25:31,500",arabic:"مَنْحُوتَةً قَطْرَةً بَعْدَ قَطْرَةٍ",segs:null,full_uz:"Tomchi ortidan tomchi o‘yilgan.",note:"قَطْرَةً بَعْدَ قَطْرَةٍ — tomchi ortidan tomchi."},
{num:273,time:"00:25:31,500 --> 00:25:35,619",arabic:"وَبَعْضُهَا يَعُودُ إِلَى أَكْثَرَ مِنْ مِائَةِ أَلْفِ عَامٍ",segs:[{ar:"وَبَعْضُهَا يَعُودُ",uz:"ularning ba’zilari borib taqaladi"},{ar:"إِلَى أَكْثَرَ مِنْ مِائَةِ أَلْفِ عَامٍ",uz:"yuz ming yildan ortiq vaqtga"}],full_uz:"Ularning ba’zilari yuz ming yildan ortiq vaqtga borib taqaladi.",note:null},
{num:274,time:"00:25:35,619 --> 00:25:39,740",arabic:"فِي قَلْبِ هَذَا النِّظَامِ",segs:null,full_uz:"Bu tizimning qalbida.",note:"نِظَامٌ — tizim."},
{num:275,time:"00:25:39,740 --> 00:25:45,359",arabic:"تَقَعُ بُحَيْرَةُ مَارْتِيلْ إِحْدَى أَكْبَرِ الْبُحَيْرَاتِ الْجَوْفِيَّةِ فِي الْعَالَمِ",segs:[{ar:"تَقَعُ بُحَيْرَةُ مَارْتِيلْ",uz:"Martel ko‘li joylashgan"},{ar:"إِحْدَى أَكْبَرِ الْبُحَيْرَاتِ الْجَوْفِيَّةِ فِي الْعَالَمِ",uz:"dunyodagi eng katta yer osti ko‘llaridan biri"}],full_uz:"Martel ko‘li, dunyodagi eng katta yer osti ko‘llaridan biri, joylashgan.",note:"جَوْفِيٌّ — yer osti, ichki."},
{num:276,time:"00:25:45,359 --> 00:25:49,279",arabic:"بِطُولٍ يَزِيدُ عَنْ مِائَةِ مِتْرٍ",segs:null,full_uz:"Uzunligi yuz metrdan ortiq.",note:null},
{num:277,time:"00:25:49,279 --> 00:25:55,019",arabic:"يَعْبُرُهَا الزُّوَّارُ بِالْقَوَارِبِ فَوْقَ سَطْحِهَا الدَّاكِنِ الْهَادِئِ",segs:[{ar:"يَعْبُرُهَا الزُّوَّارُ بِالْقَوَارِبِ",uz:"ziyoratchilar uni qayiqlarda kesib o‘tadilar"},{ar:"فَوْقَ سَطْحِهَا الدَّاكِنِ الْهَادِئِ",uz:"uning qoramtir sokin yuzasi ustida"}],full_uz:"Ziyoratchilar uning qoramtir sokin yuzasi ustidan qayiqlarda kesib o‘tadilar.",note:"الدَّاكِنُ — to‘q, qoramtir."},
{num:278,time:"00:25:55,019 --> 00:26:03,779",arabic:"بَيْنَمَا تَكْشِفُ الْإِضَاءَةُ الْخَافِتَةُ أَعْمِدَةً حَجَرِيَّةً مُلْتَوِيَةً كَأَنَّهَا صَوَاعِقُ مُتَجَمِّدَةٌ",segs:[{ar:"بَيْنَمَا تَكْشِفُ الْإِضَاءَةُ الْخَافِتَةُ",uz:"ayni paytda xira yoritish ochib beradi"},{ar:"أَعْمِدَةً حَجَرِيَّةً مُلْتَوِيَةً",uz:"burama tosh ustunlarni"},{ar:"كَأَنَّهَا صَوَاعِقُ مُتَجَمِّدَةٌ",uz:"go‘yo muzlab qolgan chaqmoqlardek"}],full_uz:"Ayni paytda xira yoritish go‘yo muzlab qolgan chaqmoqlardek burama tosh ustunlarni namoyon qiladi.",note:"خَافِتٌ — xira, sust. مُلْتَوٍ — burama, egri. صَاعِقَةٌ — chaqmoq, yashin."},
{num:279,time:"00:26:03,779 --> 00:26:11,139",arabic:"كُلُّ خُطْوَةٍ دَاخِلَ هَذِهِ الْمُتَاهَةِ الْقَدِيمَةِ هِيَ عُبُورٌ عَبْرَ الزَّمَنِ",segs:[{ar:"كُلُّ خُطْوَةٍ دَاخِلَ هَذِهِ الْمُتَاهَةِ الْقَدِيمَةِ",uz:"bu qadimiy labirint ichidagi har bir qadam"},{ar:"هِيَ عُبُورٌ عَبْرَ الزَّمَنِ",uz:"zamon orqali o‘tishdir"}],full_uz:"Bu qadimiy labirint ichidagi har bir qadam zamon orqali o‘tishdir.",note:"عُبُورٌ — o‘tish."},
{num:280,time:"00:26:11,139 --> 00:26:14,720",arabic:"حَيْثُ يَلْتَقِي الْعِلْمُ بِالتَّارِيخِ",segs:null,full_uz:"U yerda ilm tarix bilan uchrashadi.",note:"يَلْتَقِي بِـ — ... bilan uchrashmoq."},
{num:281,time:"00:26:14,720 --> 00:26:20,700",arabic:"وَتَسُودُ رَهْبَةُ الصَّمْتِ تَحْتَ ثِقَةِ الْأَرْضِ نَفْسِهَا",segs:[{ar:"وَتَسُودُ رَهْبَةُ الصَّمْتِ",uz:"sukunat haybati hukmron bo‘ladi"},{ar:"تَحْتَ ثِقَةِ الْأَرْضِ نَفْسِهَا",uz:"yerning o‘ziga bo‘lgan ishonch ostida"}],full_uz:"Sukunat haybati yerning o‘ziga bo‘lgan ishonch ostida hukmron bo‘ladi.",note:"رَهْبَةٌ — haybat, qo‘rquv aralash ulug‘vorlik. Matnning «ثِقَةِ الْأَرْضِ» qismi ma’no jihatidan noodatiy."},
{num:282,time:"00:26:20,700 --> 00:26:24,920",arabic:"قِمَّةُ إِيكِيلْ دُومِيدِي",segs:null,full_uz:"Ekil Domidi cho‘qqisi.",note:null},
{num:283,time:"00:26:24,920 --> 00:26:29,980",arabic:"تَشَكَّلَتْ إِيكِيلْ دُومِيدِي عَبْرَ مَلَايِينَ السِّنِينَ",segs:[{ar:"تَشَكَّلَتْ إِيكِيلْ دُومِيدِي",uz:"Ekil Domidi shakllangan"},{ar:"عَبْرَ مَلَايِينَ السِّنِينَ",uz:"millionlab yillar davomida"}],full_uz:"Ekil Domidi millionlab yillar davomida shakllangan.",note:"تَشَكَّلَ — shakllanmoq."},
{num:284,time:"00:26:29,980 --> 00:26:34,720",arabic:"نَتِيجَةَ الرَّفْعِ التَّكْتُونِيِّ وَالنَّحْتِ الْجَلِيدِيِّ الْمُسْتَمِرِّ",segs:[{ar:"نَتِيجَةَ الرَّفْعِ التَّكْتُونِيِّ",uz:"tektonik ko‘tarilish natijasida"},{ar:"وَالنَّحْتِ الْجَلِيدِيِّ الْمُسْتَمِرِّ",uz:"va uzluksiz muzlik yemirilishi"}],full_uz:"Tektonik ko‘tarilish va uzluksiz muzlik yemirilishi natijasida.",note:"الرَّفْعُ التَّكْتُونِيُّ — tektonik ko‘tarilish. النَّحْتُ الْجَلِيدِيُّ — muzlik eroziyasi."},
{num:285,time:"00:26:34,720 --> 00:26:39,480",arabic:"لِتَرْتَفِعَ أَكْثَرَ مِنْ ثَلَاثَةِ آلَافٍ وَثَمَانِمِائَةِ مِتْرٍ",segs:null,full_uz:"U uch ming sakkiz yuz metrdan ortiq balandlikka ko‘tariladi.",note:null},
{num:286,time:"00:26:39,480 --> 00:26:41,500",arabic:"فَوْقَ وَادِي شَامُونِي",segs:null,full_uz:"Shamoni vodiysi ustida.",note:null},
{num:287,time:"00:26:41,500 --> 00:26:46,019",arabic:"رُمْحٌ مِنَ الْجِرَانِيتِ يَخْتَرِقُ سَمَاءَ الْأَلْبِ",segs:[{ar:"رُمْحٌ مِنَ الْجِرَانِيتِ",uz:"granitdan bir nayza"},{ar:"يَخْتَرِقُ سَمَاءَ الْأَلْبِ",uz:"Alp osmonini teshib o‘tadi"}],full_uz:"Alp osmonini teshib turgan granit nayza.",note:"رُمْحٌ — nayza, sanchqi."},
{num:288,time:"00:26:46,019 --> 00:26:54,920",arabic:"هُنَا تَنْخَفِضُ دَرَجَاتُ الْحَرَارَةِ إِلَى مَا دُونَ ثَلَاثِينَ دَرَجَةً مِئَوِيَّةً تَحْتَ الصِّفْرِ",segs:[{ar:"هُنَا تَنْخَفِضُ دَرَجَاتُ الْحَرَارَةِ",uz:"bu yerda harorat pasayadi"},{ar:"إِلَى مَا دُونَ ثَلَاثِينَ دَرَجَةً مِئَوِيَّةً",uz:"minus o‘ttiz darajadan ham pastga"},{ar:"تَحْتَ الصِّفْرِ",uz:"noldan past"}],full_uz:"Bu yerda harorat minus o‘ttiz darajadan ham pastga tushadi.",note:"مَا دُونَ — dan past. تَحْتَ الصِّفْرِ — noldan past."},
{num:289,time:"00:26:54,920 --> 00:27:01,840",arabic:"وَتَهُبُّ رِيَاحٌ قَوِيَّةٌ تُشَكِّلُ الثُّلُوجَ فِي أَمْوَاجٍ جَلِيدِيَّةٍ حَادَّةٍ",segs:[{ar:"وَتَهُبُّ رِيَاحٌ قَوِيَّةٌ",uz:"va kuchli shamollar esadi"},{ar:"تُشَكِّلُ الثُّلُوجَ",uz:"qorlarni shakllantiradigan"},{ar:"فِي أَمْوَاجٍ جَلِيدِيَّةٍ حَادَّةٍ",uz:"o‘tkir muz to‘lqinlariga"}],full_uz:"Va kuchli shamollar qorni o‘tkir muz to‘lqinlariga aylantirib esadi.",note:"تَهُبُّ — shamol esmoq. أَمْوَاجٌ جَلِيدِيَّةٌ — muz to‘lqinlari."},
{num:290,time:"00:27:01,840 --> 00:27:05,160",arabic:"لِلْوُصُولِ إِلَى الْقِمَّةِ",segs:null,full_uz:"Cho‘qqiga yetib borish uchun.",note:null},
{num:291,time:"00:27:05,160 --> 00:27:11,320",arabic:"يَسْتَقِلُّ الزُّوَّارُ تِلْفَرِيكًا يَصْعَدُ قَرَابَةَ خَمْسَةِ كِيلُومِتْرَاتٍ عَمُودِيًّا",segs:[{ar:"يَسْتَقِلُّ الزُّوَّارُ تِلْفَرِيكًا",uz:"ziyoratchilar kanat yo‘liga chiqadilar"},{ar:"يَصْعَدُ قَرَابَةَ خَمْسَةِ كِيلُومِتْرَاتٍ عَمُودِيًّا",uz:"u qariyb besh kilometr tik balandlikka ko‘tariladi"}],full_uz:"Ziyoratchilar qariyb besh kilometr tik balandlikka ko‘tariladigan kanat yo‘liga chiqadilar.",note:"تِلْفَرِيكٌ — kanat yo‘li, teleferik. يَسْتَقِلُّ — minmoq, foydalanmoq."},
{num:292,time:"00:27:11,320 --> 00:27:15,200",arabic:"لِيَصِلُوا إِلَى أَحَدِ أَعْلَى الْمُنْشَآتِ الْبَشَرِيَّةِ فِي أُورُوبَّا",segs:[{ar:"لِيَصِلُوا إِلَى أَحَدِ أَعْلَى الْمُنْشَآتِ الْبَشَرِيَّةِ",uz:"inson yaratgan eng baland inshootlardan biriga yetish uchun"},{ar:"فِي أُورُوبَّا",uz:"Yevropadagi"}],full_uz:"Yevropadagi inson yaratgan eng baland inshootlardan biriga yetish uchun.",note:"مُنْشَأَةٌ — inshoot."},
{num:293,time:"00:27:15,200 --> 00:27:20,140",arabic:"مُجَمَّعٌ مِنَ الشُّرُفَاتِ وَالْمَمَرَّاتِ الْفُولَاذِيَّةِ",segs:[{ar:"مُجَمَّعٌ مِنَ الشُّرُفَاتِ",uz:"ayvonlar majmuasi"},{ar:"وَالْمَمَرَّاتِ الْفُولَاذِيَّةِ",uz:"va po‘lat yo‘laklardan"}],full_uz:"Ayvonlar va po‘lat yo‘laklardan iborat majmua.",note:"مُجَمَّعٌ — majmua."},
{num:294,time:"00:27:20,140 --> 00:27:23,140",arabic:"مُثَبَّتٌ مُبَاشَرَةً فِي الصَّخْرِ",segs:null,full_uz:"To‘g‘ridan-to‘g‘ri qoyaga mahkamlangan.",note:"مُثَبَّتٌ — mahkamlangan."},
{num:295,time:"00:27:23,140 --> 00:27:28,340",arabic:"يُتِيحُ لِلنَّاسِ الْوُقُوفَ فِي مَكَانٍ لَمْ يَكُنْ يَبْلُغُهُ سَابِقًا",segs:[{ar:"يُتِيحُ لِلنَّاسِ الْوُقُوفَ فِي مَكَانٍ",uz:"odamlarga bir joyda turish imkonini beradi"},{ar:"لَمْ يَكُنْ يَبْلُغُهُ سَابِقًا",uz:"ilgari unga yetib bo‘lmagan"}],full_uz:"Odamlarga ilgari yetib borib bo‘lmagan joyda turish imkonini beradi.",note:"أَتَاحَ — imkon bermoq."},
{num:296,time:"00:27:28,340 --> 00:27:33,520",arabic:"إِلَّا مُتَسَلِّقُ الْجِبَالِ الْمُحْتَرِفُونَ",segs:null,full_uz:"Faqat professional alpinistlar yetib borgan joyda.",note:"مُتَسَلِّقُ الْجِبَالِ — alpinist. الْمُحْتَرِفُونَ — professionallar."},
{num:297,time:"00:27:33,520 --> 00:27:40,940",arabic:"عِنْدَ هَذَا الِارْتِفَاعِ يَلْتَقِي الْمُنَاخُ الْقَاسِي بِالْجِيُولُوجْيَا الْعَتِيقَةِ",segs:[{ar:"عِنْدَ هَذَا الِارْتِفَاعِ",uz:"bu balandlikda"},{ar:"يَلْتَقِي الْمُنَاخُ الْقَاسِي",uz:"qattiq iqlim uchrashadi"},{ar:"بِالْجِيُولُوجْيَا الْعَتِيقَةِ",uz:"qadimiy geologiya bilan"}],full_uz:"Bu balandlikda qattiq iqlim qadimiy geologiya bilan uchrashadi.",note:"قَاسٍ — qattiq, og‘ir."},
{num:298,time:"00:27:40,940 --> 00:27:46,140",arabic:"فِي تَجْرِبَةٍ تَكْشِفُ حُدُودَ الْإِنْسَانِ أَمَامَ عَظَمَةِ الْخَلْقِ",segs:[{ar:"فِي تَجْرِبَةٍ تَكْشِفُ حُدُودَ الْإِنْسَانِ",uz:"inson imkoniyatlari chegaralarini ochib beradigan tajribada"},{ar:"أَمَامَ عَظَمَةِ الْخَلْقِ",uz:"yaratilish ulug‘vorligi oldida"}],full_uz:"Yaratilish ulug‘vorligi oldida inson imkoniyatlari chegaralarini ochib beradigan tajribada.",note:"عَظَمَةٌ — ulug‘vorlik, buyuklik."},
{num:299,time:"00:26:46,700 --> 00:27:50,140",arabic:"بَلْدَةُ فَنْغْ هُوَانْغَ الْقَدِيمَةُ",segs:null,full_uz:"Qadimiy Feng Huang shaharchasi.",note:"Vaqt kodi manba matnida 00:27:46,700 deb berilgan, keyingi satr 00:27:50,140 dan boshlanadi."},
{num:300,time:"00:27:50,140 --> 00:27:55,660",arabic:"تَشَكَّلَتْ بَلْدَةُ فَنْغْ هُوَانْغَ عَلَى مَدَى أَكْثَرَ مِنْ ثَلَاثَةِ قُرُونٍ",segs:[{ar:"تَشَكَّلَتْ بَلْدَةُ فَنْغْ هُوَانْغَ",uz:"Feng Huang shaharchasi shakllangan"},{ar:"عَلَى مَدَى أَكْثَرَ مِنْ ثَلَاثَةِ قُرُونٍ",uz:"uch asrdan ortiq vaqt davomida"}],full_uz:"Feng Huang shaharchasi uch asrdan ortiq vaqt davomida shakllangan.",note:null},
{num:301,time:"00:27:55,660 --> 00:27:59,180",arabic:"وَتَسْتَقِرُّ بِهُدُوءٍ عَلَى ضِفَافِ نَهْرِ تُو",segs:[{ar:"وَتَسْتَقِرُّ بِهُدُوءٍ",uz:"sokin joylashgan"},{ar:"عَلَى ضِفَافِ نَهْرِ تُو",uz:"Tuo daryosi qirg‘oqlarida"}],full_uz:"Va Tuo daryosi qirg‘oqlarida sokin joylashgan.",note:"تَسْتَقِرُّ — joylashmoq, qaror topmoq."},
{num:302,time:"00:27:59,180 --> 00:28:04,920",arabic:"حَيْثُ تَنْحَتُ الْجِبَالُ وَالْمِيَاهُ حِضْنًا طَبِيعِيًّا",segs:[{ar:"حَيْثُ تَنْحَتُ الْجِبَالُ وَالْمِيَاهُ",uz:"u yerda tog‘lar va suv o‘yadi"},{ar:"حِضْنًا طَبِيعِيًّا",uz:"tabiiy bag‘irni"}],full_uz:"U yerda tog‘lar va suv tabiiy bir bag‘irni o‘yib yaratgan.",note:"تَنْحَتُ — o‘ymoq, shakllantirmoq."},
{num:303,time:"00:28:04,920 --> 00:28:09,280",arabic:"لِوَاحِدٍ مِنْ أَفْضَلِ الْمَشَاهِدِ الثَّقَافِيَّةِ الْمَحْفُوظَةِ فِي الصِّينِ",segs:[{ar:"لِوَاحِدٍ مِنْ أَفْضَلِ الْمَشَاهِدِ الثَّقَافِيَّةِ الْمَحْفُوظَةِ",uz:"eng yaxshi saqlangan madaniy manzaralardan biriga"},{ar:"فِي الصِّينِ",uz:"Xitoydagi"}],full_uz:"Xitoydagi eng yaxshi saqlangan madaniy manzaralardan biriga.",note:"مَحْفُوظٌ — saqlangan."},
{num:304,time:"00:28:09,280 --> 00:28:14,560",arabic:"تَتَشَابَكُ الْأَزِقَّةُ الْحَجَرِيَّةُ",segs:null,full_uz:"Tosh tor ko‘chalar bir-biriga tutashib ketadi.",note:"تَتَشَابَكُ — bir-biriga chirmashmoq, tutashmoq."},
{num:305,time:"00:28:14,560 --> 00:28:17,480",arabic:"الَّتِي وُضِعَتْ فِي عَهْدِ أُسْرَةِ تْشِينْغ",segs:null,full_uz:"Sin sulolasi davrida yotqizilgan.",note:"أُسْرَةٌ — sulola."},
{num:306,time:"00:28:17,480 --> 00:28:20,980",arabic:"بَيْنَ الْجُدْرَانِ الْعَتِيقَةِ وَالْجُسُورِ الْمُقَوَّسَةِ",segs:[{ar:"بَيْنَ الْجُدْرَانِ الْعَتِيقَةِ",uz:"qadimiy devorlar orasida"},{ar:"وَالْجُسُورِ الْمُقَوَّسَةِ",uz:"va ravoqli ko‘priklar orasida"}],full_uz:"Qadimiy devorlar va ravoqli ko‘priklar orasida.",note:"الْمُقَوَّسُ — ravoqli, yoy shaklidagi."},
{num:307,time:"00:28:20,980 --> 00:28:27,660",arabic:"كُلَّ يَوْمٍ يَسِيرُ الزُّوَّارُ عَلَى هَذِهِ الدُّرُوبِ الَّتِي طَوَاهَا الزَّمَنُ",segs:[{ar:"كُلَّ يَوْمٍ يَسِيرُ الزُّوَّارُ",uz:"har kuni ziyoratchilar yuradilar"},{ar:"عَلَى هَذِهِ الدُّرُوبِ الَّتِي طَوَاهَا الزَّمَنُ",uz:"zamon bosib ketgan bu yo‘llarda"}],full_uz:"Har kuni ziyoratchilar zamon bosib ketgan bu yo‘llarda yuradilar.",note:"طَوَى الزَّمَنُ — vaqt bosib ketdi, tarix qa’riga singdirdi."},
{num:308,time:"00:28:27,660 --> 00:28:31,759",arabic:"أَوْ يَنْسَابُونَ فِي قَوَارِبَ خَشَبِيَّةٍ ضَيِّقَةٍ",segs:[{ar:"أَوْ يَنْسَابُونَ",uz:"yoki ravon suzib boradilar"},{ar:"فِي قَوَارِبَ خَشَبِيَّةٍ ضَيِّقَةٍ",uz:"tor yog‘och qayiqlarda"}],full_uz:"Yoki tor yog‘och qayiqlarda ravon suzib boradilar.",note:"يَنْسَابُ — ravon suzmoq, sirg‘alib o‘tmoq."},
{num:309,time:"00:28:31,759 --> 00:28:36,599",arabic:"يُرَاقِبُونَ انْعِكَاسَ الْفَوَانِيسِ وَهِيَ تَرْتَجِفُ فَوْقَ سَطْحِ الْمَاءِ",segs:[{ar:"يُرَاقِبُونَ انْعِكَاسَ الْفَوَانِيسِ",uz:"ular fonuslarning aksini kuzatadilar"},{ar:"وَهِيَ تَرْتَجِفُ فَوْقَ سَطْحِ الْمَاءِ",uz:"ular suv yuzida titrab turgan paytda"}],full_uz:"Ular suv yuzida titrab turgan fonuslarning aksini kuzatadilar.",note:"تَرْتَجِفُ — titramoq."},
{num:310,time:"00:28:36,599 --> 00:28:40,500",arabic:"تُحِيطُ بِهَا تِلَالٌ يَغْمُرُهَا الضَّبَابُ",segs:[{ar:"تُحِيطُ بِهَا تِلَالٌ",uz:"uni tepaliklar o‘rab turadi"},{ar:"يَغْمُرُهَا الضَّبَابُ",uz:"ularni tuman qoplaydi"}],full_uz:"Uni tuman qoplagan tepaliklar o‘rab turadi.",note:"يَغْمُرُ — qoplamoq, o‘rab olmoq."},
{num:311,time:"00:28:40,500 --> 00:28:44,819",arabic:"وَمُنَاخٌ مُعْتَدِلٌ مُعْظَمَ أَيَّامِ السَّنَةِ",segs:null,full_uz:"Yilning aksariyat kunlarida mo‘tadil iqlim.",note:"مُعْظَمُ — aksariyat, ko‘pchilik."},
{num:312,time:"00:28:44,819 --> 00:28:47,579",arabic:"فَتَتَحَرَّكُ فَنْغْ هُوَانْغَ بِإِيقَاعٍ هَادِئٍ",segs:[{ar:"فَتَتَحَرَّكُ فَنْغْ هُوَانْغَ",uz:"shunda Feng Huang yashaydi/harakat qiladi"},{ar:"بِإِيقَاعٍ هَادِئٍ",uz:"sokin bir maromda"}],full_uz:"Shunda Feng Huang sokin bir maromda hayot kechiradi.",note:"إِيقَاعٌ — marom, ritm."},
{num:313,time:"00:28:47,579 --> 00:28:51,519",arabic:"تَمْزِجُ الْجِيُولُوجْيَا بِالتَّارِيخِ وَالْعِمَارَةِ",segs:null,full_uz:"Geologiyani tarix va me’morchilik bilan uyg‘unlashtiradi.",note:"يَمْزِجُ — uyg‘unlashtirmoq."},
{num:314,time:"00:28:51,519 --> 00:28:55,319",arabic:"فِي مُتْحَفٍ حَيٍّ لِلْجَمَالِ الصَّامِتِ وَالدَّائِمِ",segs:[{ar:"فِي مُتْحَفٍ حَيٍّ",uz:"tirik muzeyda"},{ar:"لِلْجَمَالِ الصَّامِتِ وَالدَّائِمِ",uz:"sokin va bardavom go‘zallik uchun"}],full_uz:"Sokin va bardavom go‘zallikning tirik muzeyida.",note:"الدَّائِمُ — doimiy, bardavom."},
{num:315,time:"00:28:55,319 --> 00:29:00,539",arabic:"رَاجَا أَمْبَاتْ فِي إِنْدُونِيسْيَا",segs:null,full_uz:"Indoneziyadagi Raja Ampat.",note:null},
{num:316,time:"00:29:00,539 --> 00:29:03,899",arabic:"لَيْسَتْ رَاجَا أَمْبَاتْ مُجَرَّدَ فِرْدَوْسٍ بَحْرِيٍّ",segs:[{ar:"لَيْسَتْ رَاجَا أَمْبَاتْ",uz:"Raja Ampat shunchaki"},{ar:"مُجَرَّدَ فِرْدَوْسٍ بَحْرِيٍّ",uz:"dengiz jannati emas"}],full_uz:"Raja Ampat shunchaki dengiz jannati emas.",note:"فِرْدَوْسٌ — jannat, jannatmakon."},
{num:317,time:"00:29:03,899 --> 00:29:07,319",arabic:"بَلْ نَسِيجٌ حَيٌّ مِنَ الثَّقَافَةِ وَالطَّبِيعَةِ",segs:[{ar:"بَلْ نَسِيجٌ حَيٌّ",uz:"balki tirik to‘qima"},{ar:"مِنَ الثَّقَافَةِ وَالطَّبِيعَةِ",uz:"madaniyat va tabiatdan iborat"}],full_uz:"Balki madaniyat va tabiatdan iborat tirik bir to‘qimadir.",note:"نَسِيجٌ — to‘qima, uyg‘un tizim."},
{num:318,time:"00:29:07,319 --> 00:29:10,839",arabic:"تَشَكَّلَ عَبْرَ عَشَرَاتِ آلَافِ السِّنِينَ",segs:[{ar:"تَشَكَّلَ",uz:"shakllangan"},{ar:"عَبْرَ عَشَرَاتِ آلَافِ السِّنِينَ",uz:"o‘n minglab yillar davomida"}],full_uz:"O‘n minglab yillar davomida shakllangan.",note:null},
{num:319,time:"00:29:10,839 --> 00:29:14,159",arabic:"عَلَى يَدِ مُجْتَمَعَاتٍ بَابُوِيَّةٍ أَصْلِيَّةٍ",segs:null,full_uz:"Mahalliy papuas jamoalari qo‘li bilan.",note:"عَلَى يَدِ — qo‘li bilan, tomonidan. أَصْلِيٌّ — tubjoy, mahalliy."},
{num:320,time:"00:29:14,160 --> 00:29:20,400",arabic:"جُزُرُهَا الْمَنْحُوتَةُ مِنْ حَجَرٍ جِيرِيٍّ قَدِيمٍ",segs:[{ar:"جُزُرُهَا الْمَنْحُوتَةُ",uz:"uning o‘yilgan orollari"},{ar:"مِنْ حَجَرٍ جِيرِيٍّ قَدِيمٍ",uz:"qadimiy ohaktoshdan"}],full_uz:"Uning qadimiy ohaktoshdan o‘yilgan orollari.",note:"مَنْحُوتٌ — o‘yilgan."},
{num:321,time:"00:29:20,400 --> 00:29:22,759",arabic:"تَنْهَضُ فَجْأَةً مِنَ الْبَحْرِ",segs:null,full_uz:"Dengizdan to‘satdan qad rostlaydi.",note:"فَجْأَةً — to‘satdan."},
{num:322,time:"00:29:22,759 --> 00:29:27,580",arabic:"تَحْتَضِنُ قُرًى نَائِيَةً تَصْطَفُّ فِيهَا الْبُيُوتُ الْخَشَبِيَّةُ",segs:[{ar:"تَحْتَضِنُ قُرًى نَائِيَةً",uz:"uzoqlashgan qishloqlarni bag‘riga oladi"},{ar:"تَصْطَفُّ فِيهَا الْبُيُوتُ الْخَشَبِيَّةُ",uz:"ularda yog‘och uylar tizilib turadi"}],full_uz:"U uzoq qishloqlarni bag‘riga oladi, ularda yog‘och uylar tizilib turadi.",note:"نَائِيٌّ — olis, uzoq."},
{num:323,time:"00:29:27,580 --> 00:29:31,840",arabic:"عَلَى رَكَائِزَ فَوْقَ مِيَاهٍ شَفَّافَةٍ كَالْكِرِسْتَالِ",segs:[{ar:"عَلَى رَكَائِزَ",uz:"tayanchlar ustida"},{ar:"فَوْقَ مِيَاهٍ شَفَّافَةٍ كَالْكِرِسْتَالِ",uz:"billurdek tiniq suvlar ustida"}],full_uz:"Billurdek tiniq suvlar ustidagi tayanchlar ustida.",note:"شَفَّافٌ — tiniq, shaffof."},
{num:324,time:"00:29:31,840 --> 00:29:37,400",arabic:"هُنَا مَا زَالَتِ التَّقَالِيدُ نَابِضَةً بِالْحَيَاةِ",segs:[{ar:"هُنَا مَا زَالَتِ التَّقَالِيدُ",uz:"bu yerda an’analar hamon"},{ar:"نَابِضَةً بِالْحَيَاةِ",uz:"hayot bilan jo‘shqin"}],full_uz:"Bu yerda an’analar hamon hayot bilan jo‘shqin.",note:"نَابِضٌ بِالْحَيَاةِ — hayotga to‘la, jo‘shqin."},
{num:325,time:"00:29:37,400 --> 00:29:39,820",arabic:"مَهْرَجَانَاتُ الطُّبُولِ الْإِيقَاعِيَّةِ",segs:null,full_uz:"Jo‘shqin doira/baraban festivallari.",note:"إِيقَاعِيٌّ — ritmik."},
{num:326,time:"00:29:39,820 --> 00:29:42,660",arabic:"الْأَقْنِعَةُ الْمَنْحُوتَةُ يَدَوِيًّا",segs:null,full_uz:"Qo‘lda o‘yilgan niqoblar.",note:"مَنْحُوتٌ — o‘yilgan. يَدَوِيًّا — qo‘lda."},
{num:327,time:"00:29:42,660 --> 00:29:48,340",arabic:"وَالْوَلَائِمُ الْجَمَاعِيَّةُ الَّتِي تَحْتَفِي بِالْبَحْرِ كَمَصْدَرٍ لِلْحَيَاةِ",segs:[{ar:"وَالْوَلَائِمُ الْجَمَاعِيَّةُ",uz:"va jamoaviy ziyofatlar"},{ar:"الَّتِي تَحْتَفِي بِالْبَحْرِ",uz:"dengizni ulug‘laydigan"},{ar:"كَمَصْدَرٍ لِلْحَيَاةِ",uz:"hayot manbai sifatida"}],full_uz:"Va dengizni hayot manbai sifatida ulug‘laydigan jamoaviy ziyofatlar.",note:"وَلِيمَةٌ — ziyofat, katta dasturxon."},
{num:328,time:"00:29:48,340 --> 00:29:53,440",arabic:"يَلْعَبُ الْأَطْفَالُ فِي بُحَيْرَاتٍ دَافِئَةٍ طَوَالَ الْعَامِ",segs:[{ar:"يَلْعَبُ الْأَطْفَالُ",uz:"bolalar o‘ynaydilar"},{ar:"فِي بُحَيْرَاتٍ دَافِئَةٍ طَوَالَ الْعَامِ",uz:"yil bo‘yi iliq ko‘llarda"}],full_uz:"Bolalar yil bo‘yi iliq ko‘llarda o‘ynaydilar.",note:null},
{num:329,time:"00:29:53,440 --> 00:30:01,600",arabic:"وَيَتَسَابَقُونَ بِقَوَارِبَ مَصْنُوعَةٍ يَدَوِيًّا فَوْقَ مِيَاهٍ تَحْتَضِنُ أَكْثَرَ مِنْ 75%",segs:[{ar:"وَيَتَسَابَقُونَ بِقَوَارِبَ مَصْنُوعَةٍ يَدَوِيًّا",uz:"va qo‘lda yasalgan qayiqlarda poygalashadilar"},{ar:"فَوْقَ مِيَاهٍ تَحْتَضِنُ أَكْثَرَ مِنْ 75%",uz:"suvlar ustida, ular 75 foizdan ortig‘ini o‘z ichiga oladi"}],full_uz:"Va 75 foizdan ortiq ... o‘z ichiga olgan suvlar ustida qo‘lda yasalgan qayiqlarda poygalashadilar.",note:"Matn 330-raqamda gapni davom ettiradi; shu sabab bu yerda segs gapning mazmuniy davomi sifatida qoldirildi."},
{num:330,time:"00:30:01,600 --> 00:30:05,820",arabic:"مِنْ أَنْوَاعِ الشُّعُبِ الْمَرْجَانِيَّةِ الْمَعْرُوفَةِ فِي الْعَالَمِ",segs:null,full_uz:"Dunyoda ma’lum bo‘lgan marjon riflari turlarining 75 foizidan ortig‘i.",note:null},
{num:331,time:"00:30:05,819 --> 00:30:12,579",arabic:"غُوكَايَامَا فِي الْيَابَانِ",segs:null,full_uz:"Yaponiyadagi Gokayama.",note:null},
{num:332,time:"00:30:12,579 --> 00:30:17,839",arabic:"تَخْتَبِئُ غُوكَايَامَا عَمِيقًا فِي مُحَافَظَةِ تُويَامَا الْيَابَانِيَّةِ",segs:[{ar:"تَخْتَبِئُ غُوكَايَامَا",uz:"Gokayama yashirinib yotadi"},{ar:"عَمِيقًا فِي مُحَافَظَةِ تُويَامَا الْيَابَانِيَّةِ",uz:"Yaponiyaning Toyama prefekturasining ichkarisida"}],full_uz:"Gokayama Yaponiyaning Toyama prefekturasining ichkarisida yashirinib yotadi.",note:"تَخْتَبِئُ — yashirinmoq."},
{num:333,time:"00:30:17,839 --> 00:30:23,079",arabic:"دَاخِلَ وَادٍ نَحَتَتْهُ الْأَنْهَارُ قَبْلَ أَكْثَرَ مِنْ عَشَرَةِ آلَافِ عَامٍ",segs:[{ar:"دَاخِلَ وَادٍ نَحَتَتْهُ الْأَنْهَارُ",uz:"daryolar o‘ygan vodiy ichida"},{ar:"قَبْلَ أَكْثَرَ مِنْ عَشَرَةِ آلَافِ عَامٍ",uz:"o‘n ming yildan ko‘proq oldin"}],full_uz:"Daryolar o‘n ming yildan ko‘proq oldin o‘ygan vodiy ichida.",note:"نَحَتَ — o‘ymoq, eroziya bilan shakllantirmoq."},
{num:334,time:"00:30:23,079 --> 00:30:27,259",arabic:"فَرَضَتْ تَضَارِيسُهَا الْقَاسِيَةُ",segs:null,full_uz:"Uning og‘ir relyefi shuni taqozo qildi.",note:"فَرَضَتْ — majbur qildi, taqozo qildi. تَضَارِيسُ — relyef, yer shakllari."},
{num:335,time:"00:30:27,259 --> 00:30:31,079",arabic:"بِمُنْحَدَرَاتٍ تَرْتَفِعُ حَتَّى خَمْسِمِائَةِ مِتْرٍ",segs:null,full_uz:"Balandligi besh yuz metrgacha yetadigan yonbag‘irlar bilan.",note:"مُنْحَدَرٌ — yonbag‘ir, qiya sath."},
{num:336,time:"00:30:31,079 --> 00:30:36,220",arabic:"عَلَى السُّكَّانِ بِنَاءَ مَنَازِلِ غَاشُو زُكُورِيَا الشَّهِيرَةِ",segs:[{ar:"عَلَى السُّكَّانِ",uz:"aholiga"},{ar:"بِنَاءَ مَنَازِلِ غَاشُو زُكُورِيَا الشَّهِيرَةِ",uz:"mashhur Gasho-zukuri uylarini qurish"}],full_uz:"Aholiga mashhur Gasho-zukuri uylarini qurishga to‘g‘ri kelgan.",note:"مَنَازِلُ غَاشُو زُكُورِيَا — manba matnidagi nom; izohlashda o‘zgartirilmagan."},
{num:337,time:"00:30:36,220 --> 00:30:41,099",arabic:"بِأَسْقُفٍ مَائِلَةٍ بِزَاوِيَةٍ تُقَارِبُ سِتِّينَ دَرَجَةً",segs:[{ar:"بِأَسْقُفٍ مَائِلَةٍ",uz:"qiya tomlar bilan"},{ar:"بِزَاوِيَةٍ تُقَارِبُ سِتِّينَ دَرَجَةً",uz:"qariyb oltmish darajali burchak ostida"}],full_uz:"Qariyb oltmish darajali burchak ostidagi qiya tomlar bilan.",note:"مَائِلٌ — qiya, egilgan."},
{num:338,time:"00:30:41,099 --> 00:30:44,319",arabic:"لِتَتَحَمَّلَ ثِقَلَ الثُّلُوجِ الشِّتَوِيَّةِ",segs:[{ar:"لِتَتَحَمَّلَ ثِقَلَ الثُّلُوجِ",uz:"qorning og‘irligiga bardosh berish uchun"},{ar:"الشِّتَوِيَّةِ",uz:"qishki"}],full_uz:"Qishki qorning og‘irligiga bardosh berish uchun.",note:"تَتَحَمَّلُ — bardosh bermoq, ko‘tara olmoq."},
{num:339,time:"00:30:44,319 --> 00:30:52,039",arabic:"بَعْضُ هَذِهِ الْبُيُوتِ الْخَشَبِيَّةِ صَامِدٌ مُنْذُ أَكْثَرَ مِنْ ثَلَاثَةِ قُرُونٍ",segs:[{ar:"بَعْضُ هَذِهِ الْبُيُوتِ الْخَشَبِيَّةِ",uz:"bu yog‘och uylarning ba’zilari"},{ar:"صَامِدٌ مُنْذُ أَكْثَرَ مِنْ ثَلَاثَةِ قُرُونٍ",uz:"uch asrdan ortiq vaqtdan beri saqlanib turibdi"}],full_uz:"Bu yog‘och uylarning ba’zilari uch asrdan ortiq vaqtdan beri saqlanib turibdi.",note:"صَامِدٌ — mustahkam turgan, saqlanib qolgan."},
{num:340,time:"00:30:52,039 --> 00:30:57,039",arabic:"كِكَبْسُولَاتٍ زَمَنِيَّةٍ لِهَنْدَسَةٍ رِيفِيَّةٍ عَبْقَرِيَّةٍ",segs:[{ar:"كِكَبْسُولَاتٍ زَمَنِيَّةٍ",uz:"vaqt kapsulalaridek"},{ar:"لِهَنْدَسَةٍ رِيفِيَّةٍ عَبْقَرِيَّةٍ",uz:"g‘oyat mohir qishloq me’morchiligining"}],full_uz:"Ular mohir qishloq me’morchiligining vaqt kapsulalaridek.",note:"كَبْسُولَةٌ زَمَنِيَّةٌ — vaqt kapsulasi. عَبْقَرِيٌّ — dahosifat, nihoyatda mohir."},
{num:341,time:"00:30:57,039 --> 00:31:01,659",arabic:"يَتَجَوَّلُ الزُّوَّارُ سَيْرًا فِي الْأَزِقَّةِ الضَّيِّقَةِ",segs:[{ar:"يَتَجَوَّلُ الزُّوَّارُ سَيْرًا",uz:"ziyoratchilar piyoda kezadilar"},{ar:"فِي الْأَزِقَّةِ الضَّيِّقَةِ",uz:"tor ko‘chalarda"}],full_uz:"Ziyoratchilar tor ko‘chalarda piyoda kezadilar.",note:null},
{num:342,time:"00:31:01,659 --> 00:31:07,159",arabic:"حَيْثُ يَمْتَزِجُ دُخَانُ الْمَوَاقِدِ بِرَائِحَةِ الْأَرُزِّ وَهَوَاءِ الْجِبَالِ",segs:[{ar:"حَيْثُ يَمْتَزِجُ دُخَانُ الْمَوَاقِدِ",uz:"u yerda o‘choqlar tutuni qorishadi"},{ar:"بِرَائِحَةِ الْأَرُزِّ",uz:"guruch hidiga"},{ar:"وَهَوَاءِ الْجِبَالِ",uz:"va tog‘ havosiga"}],full_uz:"U yerda o‘choqlar tutuni guruch hidi va tog‘ havosiga qorishadi.",note:"الْمَوْقِدُ — o‘choq."},
{num:343,time:"00:31:07,159 --> 00:31:14,539",arabic:"لِيَخْتَبِرُوا قَرْيَةً شَكَّلَهَا الْتِقَاءُ الْجِيُولُوجْيَا بِالْمُنَاخِ وَبِصُمُودِ الْإِنْسَانِ",segs:[{ar:"لِيَخْتَبِرُوا قَرْيَةً",uz:"ular bir qishloqni boshdan kechirishlari uchun"},{ar:"شَكَّلَهَا الْتِقَاءُ الْجِيُولُوجْيَا بِالْمُنَاخِ",uz:"geologiya va iqlimning tutashuvi shakllantirgan"},{ar:"وَبِصُمُودِ الْإِنْسَانِ",uz:"va inson matonati bilan"}],full_uz:"Ular geologiya, iqlim va inson matonatining tutashuvi shakllantirgan qishloqni boshdan kechiradilar.",note:"صُمُودٌ — matonat, bardoshlilik."},
{num:344,time:"00:31:14,539 --> 00:31:19,339",arabic:"شَلَّالُ بَالُوزْ",segs:null,full_uz:"Paluz sharsharasi.",note:null},
{num:345,time:"00:31:19,339 --> 00:31:24,279",arabic:"نَحَتَ شَلَّالُ بَالُوزْ قَبْلَ أَكْثَرَ مِنْ ثَلَاثَةَ عَشَرَ أَلْفَ عَامٍ",segs:[{ar:"نَحَتَ شَلَّالُ بَالُوزْ",uz:"Paluz sharsharasini o‘ygan"},{ar:"قَبْلَ أَكْثَرَ مِنْ ثَلَاثَةَ عَشَرَ أَلْفَ عَامٍ",uz:"o‘n uch ming yildan ko‘proq oldin"}],full_uz:"Paluz sharsharasi o‘n uch ming yildan ko‘proq oldin shakllangan.",note:"نَحَتَ — o‘ymoq, eroziya bilan shakllantirmoq."},
{num:346,time:"00:31:24,279 --> 00:31:27,220",arabic:"بِفِعْلِ فَيَضَانَاتِ مِيسُولَا الْهَائِلَةِ",segs:[{ar:"بِفِعْلِ فَيَضَانَاتِ مِيسُولَا",uz:"Missoula toshqinlari ta’sirida"},{ar:"الْهَائِلَةِ",uz:"ulkan"}],full_uz:"Ulkan Missoula toshqinlari ta’sirida.",note:"فَيَضَانَاتٌ — toshqinlar. هَائِلٌ — ulkan."},
{num:347,time:"00:31:27,220 --> 00:31:31,539",arabic:"لِيَنْدَفِعَ الْيَوْمَ مِنْ ارْتِفَاعٍ يُقَارِبُ سِتِّينَ مِتْرًا",segs:[{ar:"لِيَنْدَفِعَ الْيَوْمَ",uz:"bugun otilib tushishi uchun"},{ar:"مِنْ ارْتِفَاعٍ يُقَارِبُ سِتِّينَ مِتْرًا",uz:"qariyb oltmish metrlik balandlikdan"}],full_uz:"Bugun qariyb oltmish metrlik balandlikdan otilib tushadi.",note:"يَنْدَفِعُ — otilib chiqmoq, shiddat bilan tushmoq."},
{num:348,time:"00:31:31,539 --> 00:31:33,759",arabic:"دَاخِلَ مُدَرَّجٍ بَازَلْتِيٍّ",segs:null,full_uz:"Bazaltli terassa ichiga.",note:"بَازَلْتِيٌّ — bazaltga oid."},
{num:349,time:"00:31:33,759 --> 00:31:37,200",arabic:"صَاغَتْهُ قُوًى بُرْكَانِيَّةٌ قَدِيمَةٌ",segs:[{ar:"صَاغَتْهُ قُوًى بُرْكَانِيَّةٌ",uz:"uni qadimiy vulqon kuchlari shakllantirgan"},{ar:"قَدِيمَةٌ",uz:"qadimiy"}],full_uz:"Uni qadimiy vulqon kuchlari shakllantirgan.",note:null},
{num:350,time:"00:31:37,200 --> 00:31:42,279",arabic:"يَقَعُ فِي أَخَادِيدِ شَرْقِ وِلَايَةِ وَاشِنْطُن",segs:null,full_uz:"Vashington shtatining sharqidagi daralar ichida joylashgan.",note:"أَخَادِيدٌ — daralar, chuqur o‘yiqlar."},
{num:351,time:"00:31:42,859 --> 00:31:48,259",arabic:"وَيُمَثِّلُ أَحَدَ الشَّوَاهِدِ الْقَلِيلَةِ الْمُتَبَقِّيَةِ عَلَى كَارِثَةٍ أَطْلَقَتْ مِيَاهًا",segs:[{ar:"وَيُمَثِّلُ أَحَدَ الشَّوَاهِدِ الْقَلِيلَةِ الْمُتَبَقِّيَةِ",uz:"u qolgan kam sonli dalillardan biridir"},{ar:"عَلَى كَارِثَةٍ أَطْلَقَتْ مِيَاهًا",uz:"suvlarni bo‘shatgan falokatga oid"}],full_uz:"U suvlarni bo‘shatgan falokatdan qolgan kam sonli dalillardan biridir.",note:"الشَّوَاهِدُ — dalillar, guvohliklar. الْمُتَبَقِّيَةُ — qolgan."},
{num:352,time:"00:31:48,259 --> 00:31:52,460",arabic:"تَفُوقُ تَدَفُّقَ جَمِيعِ أَنْهَارِ الْعَالَمِ الْحَالِيَّةِ",segs:[{ar:"تَفُوقُ تَدَفُّقَ جَمِيعِ أَنْهَارِ الْعَالَمِ",uz:"dunyodagi barcha hozirgi daryolar oqimidan oshadigan"},{ar:"الْحَالِيَّةِ",uz:"hozirgi"}],full_uz:"Dunyodagi barcha hozirgi daryolar oqimidan oshadigan.",note:"تَفُوقُ — oshib ketmoq, ustun kelmoq."},
{num:353,time:"00:31:52,460 --> 00:31:55,799",arabic:"مُجْتَمِعَةً بِأَكْثَرَ مِنْ عَشَرِ مَرَّاتٍ",segs:null,full_uz:"Jamlanma holda o‘n martadan ham ko‘proq.",note:"مُجْتَمِعَةً — jamlangan holda, birgalikda."},
{num:354,time:"00:31:55,799 --> 00:32:01,000",arabic:"هُنَا تَكْشِفُ طَبَقَاتُ اللَّافَا الصُّلْبَةُ",segs:null,full_uz:"Bu yerda qotgan lava qatlamlari ochib beradi.",note:"اللَّافَا — lava."},
{num:355,time:"00:32:01,000 --> 00:32:04,000",arabic:"وَالْمُنْحَدَرَاتُ الَّتِي صَقَلَتْهَا الرِّيَاحُ",segs:[{ar:"وَالْمُنْحَدَرَاتُ",uz:"va yonbag‘irlar"},{ar:"الَّتِي صَقَلَتْهَا الرِّيَاحُ",uz:"shamollar sayqallagan"}],full_uz:"Va shamollar sayqallagan yonbag‘irlar.",note:"صَقَلَ — sayqallamoq."},
{num:356,time:"00:32:04,000 --> 00:32:05,640",arabic:"وَهَدِيرُ الشَّلَّالِ",segs:null,full_uz:"Va sharsharaning gumburlashi.",note:"هَدِيرٌ — gumburlash, kuchli shovqin."},
{num:357,time:"00:32:05,640 --> 00:32:10,059",arabic:"عَنْ مَشْهَدٍ مُتَجَمِّدٍ بَيْنَ الْجِيُولُوجْيَا وَالْأُسْطُورَةِ",segs:[{ar:"عَنْ مَشْهَدٍ مُتَجَمِّدٍ",uz:"muzlab qolgan manzara haqida"},{ar:"بَيْنَ الْجِيُولُوجْيَا وَالْأُسْطُورَةِ",uz:"geologiya va afsona o‘rtasida"}],full_uz:"Geologiya va afsona o‘rtasida muzlab qolgan manzarani ochib beradi.",note:"مُتَجَمِّدٌ — muzlagan, qotib qolgan."},
{num:358,time:"00:32:10,059 --> 00:32:13,319",arabic:"عَجِيبَةٌ مُسْتَحِيلَةٌ وُلِدَتْ مِنَ الْفَوْضَى",segs:[{ar:"عَجِيبَةٌ مُسْتَحِيلَةٌ",uz:"imkonsizdek tuyulgan ajoyibot"},{ar:"وُلِدَتْ مِنَ الْفَوْضَى",uz:"xaosdan tug‘ilgan"}],full_uz:"Xaosdan tug‘ilgan imkonsizdek tuyulgan ajoyibot.",note:"الْفَوْضَى — tartibsizlik, xaos."},
{num:359,time:"00:32:13,319 --> 00:32:15,900",arabic:"وَالتَّحَمُّلِ وَعُمْقِ الزَّمَنِ",segs:null,full_uz:"Va chidamlilik hamda zamonning chuqurligidan.",note:"التَّحَمُّلُ — chidamlilik, bardosh."},
{num:360,time:"00:32:15,900 --> 00:32:19,960",arabic:"شَاطِئُ بَلَانْدْرَا",segs:null,full_uz:"Balandra plyaji.",note:null},
{num:361,time:"00:32:19,960 --> 00:32:21,340",arabic:"الْمَكْسِيك",segs:null,full_uz:"Meksika.",note:null},
{num:362,time:"00:32:21,339 --> 00:32:27,339",arabic:"لَيْسَ شَاطِئُ بَلَانْدْرَا مُجَرَّدَ مَلَاذٍ اسْتِوَائِيٍّ",segs:[{ar:"لَيْسَ شَاطِئُ بَلَانْدْرَا",uz:"Balandra plyaji shunchaki"},{ar:"مُجَرَّدَ مَلَاذٍ اسْتِوَائِيٍّ",uz:"tropik makon emas"}],full_uz:"Balandra plyaji shunchaki tropik makon emas.",note:"مَلَاذٌ — panoh, makon."},
{num:363,time:"00:32:27,339 --> 00:32:34,500",arabic:"بَلْ كَبْسُولَةُ زَمَنٍ جِيُولُوجِيَّةٌ تَشَكَّلَتْ عَلَى مَدَى مَا يُقَارِبُ ثَلَاثَةَ مَلَايِينَ عَامٍ",segs:[{ar:"بَلْ كَبْسُولَةُ زَمَنٍ جِيُولُوجِيَّةٌ",uz:"balki geologik vaqt kapsulasi"},{ar:"تَشَكَّلَتْ عَلَى مَدَى مَا يُقَارِبُ ثَلَاثَةَ مَلَايِينَ عَامٍ",uz:"qariyb uch million yil davomida shakllangan"}],full_uz:"Balki qariyb uch million yil davomida shakllangan geologik vaqt kapsulasidir.",note:null},
{num:364,time:"00:32:34,500 --> 00:32:39,740",arabic:"مُخْتَبِئًا عَلَى طُولِ شِبْهِ جَزِيرَةِ بَاخَا",segs:[{ar:"مُخْتَبِئًا",uz:"yashirinib"},{ar:"عَلَى طُولِ شِبْهِ جَزِيرَةِ بَاخَا",uz:"Baja yarimoroli bo‘ylab"}],full_uz:"Baja yarimoroli bo‘ylab yashirinib yotgan.",note:"مُخْتَبِئٌ — yashirinib turgan."},
{num:365,time:"00:32:39,740 --> 00:32:45,439",arabic:"تَتَلَأْلَأُ هَذِهِ الْبُحَيْرَةُ الضَّحْلَةُ بِمِيَاهٍ فِيرُوزِيَّةٍ صَافِيَةٍ",segs:[{ar:"تَتَلَأْلَأُ هَذِهِ الْبُحَيْرَةُ الضَّحْلَةُ",uz:"bu sayoz ko‘l yaltiraydi"},{ar:"بِمِيَاهٍ فِيرُوزِيَّةٍ صَافِيَةٍ",uz:"tiniq feruza rangli suvlari bilan"}],full_uz:"Bu sayoz ko‘l tiniq feruza rangli suvlari bilan yaltiraydi.",note:"ضَحْلٌ — sayoz."},
{num:366,time:"00:32:45,439 --> 00:32:50,439",arabic:"إِلَى دَرَجَةِ أَنَّكَ تَسْتَطِيعُ رُؤْيَةَ تَمَوُّجَاتِ قَاعِهَا الرَّمْلِيِّ",segs:[{ar:"إِلَى دَرَجَةِ أَنَّكَ تَسْتَطِيعُ رُؤْيَةَ",uz:"shunday darajadaki, siz ko‘ra olasiz"},{ar:"تَمَوُّجَاتِ قَاعِهَا الرَّمْلِيِّ",uz:"uning qumli tubidagi to‘lqinlarni"}],full_uz:"Shunday darajadaki, uning qumli tubidagi to‘lqinlarni ko‘ra olasiz.",note:"تَمَوُّجَاتٌ — to‘lqinlar, mayda to‘lqinsimon shakllar."},
{num:367,time:"00:32:50,440 --> 00:32:54,039",arabic:"مِنْ مَسَافَةٍ تَقْتَرِبُ مِنْ كِيلُومِتْرٍ كَامِلٍ",segs:null,full_uz:"Qariyb bir kilometr uzoqlikdan.",note:null},
{num:368,time:"00:32:54,039 --> 00:32:59,600",arabic:"بِأَعْمَاقٍ لَا تَتَجَاوَزُ مِتْرًا وَاحِدًا تَقْرِيبًا",segs:[{ar:"بِأَعْمَاقٍ",uz:"chuqurliklari"},{ar:"لَا تَتَجَاوَزُ مِتْرًا وَاحِدًا تَقْرِيبًا",uz:"taxminan bir metrdan oshmaydi"}],full_uz:"Chuqurliklari taxminan bir metrdan oshmaydi.",note:null},
{num:369,time:"00:32:59,600 --> 00:33:03,640",arabic:"يُمْكِنُ لِلزَّائِرِ أَنْ يَسِيرَ بَعِيدًا دَاخِلَ الْخَلِيجِ",segs:[{ar:"يُمْكِنُ لِلزَّائِرِ",uz:"ziyoratchi uchun mumkin"},{ar:"أَنْ يَسِيرَ بَعِيدًا دَاخِلَ الْخَلِيجِ",uz:"qo‘ltiq ichiga ancha uzoq yurib kirish"}],full_uz:"Ziyoratchi qo‘ltiq ichiga ancha uzoq yurib kirishi mumkin.",note:"الْخَلِيجُ — qo‘ltiq, qo‘ltiqsohil."},
{num:370,time:"00:33:03,640 --> 00:33:08,940",arabic:"وَكَأَنَّهُ يَمْشِي فَوْقَ مِرْآةٍ طَبِيعِيَّةٍ هَادِئَةٍ",segs:[{ar:"وَكَأَنَّهُ يَمْشِي",uz:"go‘yo u yurayotgandek"},{ar:"فَوْقَ مِرْآةٍ طَبِيعِيَّةٍ هَادِئَةٍ",uz:"sokin tabiiy ko‘zgu ustida"}],full_uz:"Go‘yo sokin tabiiy ko‘zgu ustida yurgandek.",note:null},
{num:371,time:"00:33:08,940 --> 00:33:14,200",arabic:"تُحِيطُ بِهَا تِلَالٌ غَنِيَّةٌ بِالْأَحَافِيرِ",segs:[{ar:"تُحِيطُ بِهَا تِلَالٌ",uz:"uni tepaliklar o‘rab turadi"},{ar:"غَنِيَّةٌ بِالْأَحَافِيرِ",uz:"qazilma qoldiqlarga boy"}],full_uz:"Uni qazilma qoldiqlarga boy tepaliklar o‘rab turadi.",note:"الْأَحَافِيرُ — qazilma qoldiqlar, fos­sillar."},
{num:372,time:"00:33:14,200 --> 00:33:17,680",arabic:"وَمُنْحَدَرَاتٌ نَحَتَتْهَا الرِّيَاحُ عَبْرَ الْعُصُورِ",segs:[{ar:"وَمُنْحَدَرَاتٌ",uz:"va yonbag‘irlar"},{ar:"نَحَتَتْهَا الرِّيَاحُ عَبْرَ الْعُصُورِ",uz:"asrlar davomida shamollar o‘ygan"}],full_uz:"Va asrlar davomida shamollar o‘ygan yonbag‘irlar.",note:null},
{num:373,time:"00:33:17,680 --> 00:33:24,660",arabic:"لِتَبْقَى بَلَانْدْرَا وَاحِدَةً مِنْ أَكْثَرِ الْعَجَائِبِ السَّاحِلِيَّةِ حِمَايَةً فِي الْمَكْسِيك",segs:[{ar:"لِتَبْقَى بَلَانْدْرَا وَاحِدَةً",uz:"shunday qilib Balandra ...lardan biri bo‘lib qoladi"},{ar:"مِنْ أَكْثَرِ الْعَجَائِبِ السَّاحِلِيَّةِ حِمَايَةً فِي الْمَكْسِيك",uz:"Meksikadagi eng yaxshi himoyalangan qirg‘oq ajoyibotlaridan"}],full_uz:"Shunday qilib, Balandra Meksikadagi eng yaxshi himoyalangan qirg‘oq ajoyibotlaridan biri bo‘lib qoladi.",note:"«حِمَايَةً» bu yerda grammatik jihatdan noodatiy; manba matni saqlanib, ma’nosi kontekstga ko‘ra berildi."},
{num:374,time:"00:33:24,660 --> 00:33:32,680",arabic:"بِكْرٌ سَاكِنٌ وَلَا يُقَدَّرُ بِثَمَنٍ مِنَ النَّاحِيَةِ الْعِلْمِيَّةِ",segs:[{ar:"بِكْرٌ سَاكِنٌ",uz:"bokira va sokin"},{ar:"وَلَا يُقَدَّرُ بِثَمَنٍ",uz:"baholab bo‘lmaydigan"},{ar:"مِنَ النَّاحِيَةِ الْعِلْمِيَّةِ",uz:"ilmiy jihatdan"}],full_uz:"Ilmiy jihatdan bokira, sokin va bebaho.",note:"بِكْرٌ — tegilmagan, tabiiy holatdagi. لَا يُقَدَّرُ بِثَمَنٍ — narx bilan baholab bo‘lmaydigan."},
{num:375,time:"00:33:33,580 --> 00:33:38,759",arabic:"سِيرْكْسَلَازِي فِي جَزِيرَةِ رِيُونْيُون",segs:[{ar:"سِيرْكْسَلَازِي",uz:"Sirk de Salazi"},{ar:"فِي جَزِيرَةِ رِيُونْيُون",uz:"Reyunion orolida"}],full_uz:"Reyunion orolidagi Sirk de Salazi.",note:null},
{num:376,time:"00:33:38,759 --> 00:33:43,680",arabic:"يَقَعُ سِيرْكْسَلَازِي دَاخِلَ الْحَوْضِ الْبُرْكَانِيِّ لِجَزِيرَةِ رِيُونْيُون",segs:[{ar:"يَقَعُ سِيرْكْسَلَازِي",uz:"Sirk de Salazi joylashgan"},{ar:"دَاخِلَ الْحَوْضِ الْبُرْكَانِيِّ",uz:"vulqon havzasi ichida"},{ar:"لِجَزِيرَةِ رِيُونْيُون",uz:"Reyunion orolining"}],full_uz:"Sirk de Salazi Reyunion orolining vulqon havzasi ichida joylashgan.",note:null},
{num:377,time:"00:33:43,680 --> 00:33:49,420",arabic:"رِيُونْيُون عَالَمٌ جَبَلِيٌّ نُحِتَ خِلَالَ أَكْثَرَ مِنْ مِلْيُونَيْ عَامٍ",segs:[{ar:"رِيُونْيُون عَالَمٌ جَبَلِيٌّ",uz:"Reyunion tog‘li olamdir"},{ar:"نُحِتَ خِلَالَ أَكْثَرَ مِنْ مِلْيُونَيْ عَامٍ",uz:"ikki million yildan ortiq vaqt davomida o‘yilgan"}],full_uz:"Reyunion ikki million yildan ortiq vaqt davomida shakllangan tog‘li olamdir.",note:"نُحِتَ — o‘yilgan, eroziya bilan shakllangan."},
{num:378,time:"00:33:49,420 --> 00:33:54,660",arabic:"دَاخِلَ أَحَدِ أَكْبَرِ الْبَرَاكِينِ الدِّرْعِيَّةِ الْخَامِدَةِ عَلَى الْأَرْضِ",segs:null,full_uz:"Yer yuzidagi eng katta so‘nib qolgan qalqon vulqonlardan birining ichida.",note:"الْبَرْكَانُ الدِّرْعِيُّ — qalqon vulqon. خَامِدٌ — so‘ngan."},
{num:379,time:"00:33:54,660 --> 00:33:59,740",arabic:"جُدْرَانٌ بَازَلْتِيَّةٌ شَاهِقَةٌ",segs:null,full_uz:"Baland bazalt devorlar.",note:null},
{num:380,time:"00:33:59,740 --> 00:34:03,500",arabic:"يَصِلُ ارْتِفَاعُ بَعْضِهَا إِلَى تِسْعِمِائَةِ مِتْرٍ",segs:null,full_uz:"Ba’zilarining balandligi to‘qqiz yuz metrga yetadi.",note:null},
{num:381,time:"00:34:03,500 --> 00:34:07,700",arabic:"تَحْبِسُ السُّحُبَ الْقَادِمَةَ مِنَ الْمُحِيطِ الْهِنْدِيِّ",segs:[{ar:"تَحْبِسُ السُّحُبَ",uz:"bulutlarni to‘sib qoladi"},{ar:"الْقَادِمَةَ مِنَ الْمُحِيطِ الْهِنْدِيِّ",uz:"Hind okeanidan kelayotgan"}],full_uz:"Hind okeanidan kelayotgan bulutlarni to‘sib qoladi.",note:"تَحْبِسُ — ushlab qolmoq, to‘smoq."},
{num:382,time:"00:34:07,700 --> 00:34:11,680",arabic:"مُوَلِّدَةً مُنَاخًا فَائِقَ الرُّطُوبَةِ",segs:[{ar:"مُوَلِّدَةً مُنَاخًا",uz:"iqlim hosil qilib"},{ar:"فَائِقَ الرُّطُوبَةِ",uz:"nihoyatda nam"}],full_uz:"Nihoyatda nam iqlim hosil qilib.",note:"فَائِقٌ — nihoyatda yuqori, haddan tashqari."},
{num:383,time:"00:34:11,679 --> 00:34:17,039",arabic:"قَدْ يَتَجَاوَزُ فِيهِ هُطُولُ الْأَمْطَارِ سَبْعَةَ أَمْتَارٍ سَنَوِيًّا",segs:[{ar:"قَدْ يَتَجَاوَزُ فِيهِ هُطُولُ الْأَمْطَارِ",uz:"unda yog‘ingarchilik oshishi mumkin"},{ar:"سَبْعَةَ أَمْتَارٍ سَنَوِيًّا",uz:"yiliga yetti metrdan"}],full_uz:"Unda yillik yog‘ingarchilik yetti metrdan oshishi mumkin.",note:"هُطُولُ الْأَمْطَارِ — yog‘ingarchilik miqdori."},
{num:384,time:"00:34:17,039 --> 00:34:23,199",arabic:"هَذِهِ الرُّطُوبَةُ الدَّائِمَةُ تُغَذِّي مِئَاتِ الشَّلَّالَاتِ",segs:[{ar:"هَذِهِ الرُّطُوبَةُ الدَّائِمَةُ",uz:"bu doimiy namlik"},{ar:"تُغَذِّي مِئَاتِ الشَّلَّالَاتِ",uz:"yuzlab sharsharalarni oziqlantiradi"}],full_uz:"Bu doimiy namlik yuzlab sharsharalarni oziqlantiradi.",note:"تُغَذِّي — oziqlantirmoq, suv bilan ta’minlamoq."},
{num:385,time:"00:34:23,199 --> 00:34:26,259",arabic:"أَبْرَزُهَا شَلَّالُ حِجَابِ الْعَرُوسِ",segs:[{ar:"أَبْرَزُهَا",uz:"ularning eng mashhuri"},{ar:"شَلَّالُ حِجَابِ الْعَرُوسِ",uz:"Kelin pardasi sharsharasi"}],full_uz:"Ularning eng mashhuri Kelin pardasi sharsharasidir.",note:"حِجَابُ الْعَرُوسِ — «kelin pardasi» nomi."},
{num:386,time:"00:34:26,259 --> 00:34:31,599",arabic:"الَّذِي يَنْسَابُ بِرِقَّةٍ لِمَسَافَةٍ تُقَارِبُ ثَلَاثَمِائَةِ مِتْرٍ",segs:[{ar:"الَّذِي يَنْسَابُ بِرِقَّةٍ",uz:"u mayin oqadi"},{ar:"لِمَسَافَةٍ تُقَارِبُ ثَلَاثَمِائَةِ مِتْرٍ",uz:"qariyb uch yuz metr masofada"}],full_uz:"U qariyb uch yuz metr masofada mayin oqadi.",note:"بِرِقَّةٍ — mayinlik bilan, nozik tarzda."},
{num:387,time:"00:34:31,599 --> 00:34:35,000",arabic:"عَلَى مُنْحَدَرَاتٍ مُغَطَّاةٍ بِالسَّرَاخِسِ",segs:[{ar:"عَلَى مُنْحَدَرَاتٍ مُغَطَّاةٍ",uz:"qoplangan yonbag‘irlar bo‘ylab"},{ar:"بِالسَّرَاخِسِ",uz:"qirqquloqlar bilan"}],full_uz:"Qirqquloqlar bilan qoplangan yonbag‘irlar bo‘ylab.",note:"السَّرَاخِسُ — qirqquloqlar, paporotniklar."},
{num:388,time:"00:34:35,000 --> 00:34:42,780",arabic:"فِي الْأَعْلَى تَتَشَبَّثُ قُرًى كِرْيُولِيَّةٌ صَغِيرَةٌ بِحَوَافٍّ ضَيِّقَةٍ",segs:[{ar:"فِي الْأَعْلَى",uz:"yuqorida"},{ar:"تَتَشَبَّثُ قُرًى كِرْيُولِيَّةٌ صَغِيرَةٌ",uz:"kichik kreol qishloqlari mahkam yopishib turadi"},{ar:"بِحَوَافٍّ ضَيِّقَةٍ",uz:"tor qirlar bo‘ylab"}],full_uz:"Yuqorida kichik kreol qishloqlari tor qirlarga mahkam yopishib turadi.",note:"كِرْيُولِيٌّ — kreol."},
{num:389,time:"00:34:42,780 --> 00:34:46,079",arabic:"تَشَكَّلَتْ مِنْ تَدَفُّقَاتِ اللَّافَا الْقَدِيمَةِ",segs:null,full_uz:"Qadimiy lava oqimlaridan shakllangan.",note:"تَدَفُّقَاتُ اللَّافَا — lava oqimlari."},
{num:390,time:"00:34:46,079 --> 00:34:52,699",arabic:"حَيْثُ تَقِفُ الْبُيُوتُ الْخَشَبِيَّةُ الْمُلَوَّنَةُ عَلَى مُدَرَّجَاتٍ مَنْحُوتَةٍ يَدَوِيًّا",segs:[{ar:"حَيْثُ تَقِفُ الْبُيُوتُ الْخَشَبِيَّةُ الْمُلَوَّنَةُ",uz:"u yerda rang-barang yog‘och uylar qad rostlaydi"},{ar:"عَلَى مُدَرَّجَاتٍ مَنْحُوتَةٍ يَدَوِيًّا",uz:"qo‘lda o‘yilgan terrasalarda"}],full_uz:"U yerda rang-barang yog‘och uylar qo‘lda o‘yilgan terrasalarda qad rostlaydi.",note:"مُلَوَّنٌ — rang-barang. مَنْحُوتٌ — o‘yilgan."},
{num:391,time:"00:34:52,699 --> 00:34:59,679",arabic:"بِسِحْرٍ جِيُولُوجِيٍّ طَاغٍ",segs:null,full_uz:"Ustun keluvchi geologik sehr bilan.",note:"طَاغٍ — ustun, haddan oshuvchi."},
{num:392,time:"00:34:59,679 --> 00:35:04,539",arabic:"وَشَلَّالَاتٌ تَظْهَرُ عِنْدَ كُلِّ مُنْعَطَفٍ",segs:[{ar:"وَشَلَّالَاتٌ تَظْهَرُ",uz:"va sharsharalar ko‘rinadi"},{ar:"عِنْدَ كُلِّ مُنْعَطَفٍ",uz:"har bir burilishda"}],full_uz:"Va har bir burilishda sharsharalar ko‘rinadi.",note:"مُنْعَطَفٌ — burilish."},
{num:393,time:"00:35:04,539 --> 00:35:10,219",arabic:"يَبْدُو سَلَازِي كَمَمْلَكَةٍ خَفِيَّةٍ مُعَلَّقَةٍ بَيْنَ الْغُيُومِ",segs:[{ar:"يَبْدُو سَلَازِي",uz:"Salazi ko‘rinadi"},{ar:"كَمَمْلَكَةٍ خَفِيَّةٍ مُعَلَّقَةٍ",uz:"yashirin, muallaq qirollikdek"},{ar:"بَيْنَ الْغُيُومِ",uz:"bulutlar orasida"}],full_uz:"Salazi bulutlar orasida muallaq turgan yashirin qirollikdek ko‘rinadi.",note:"مَمْلَكَةٌ — qirollik. مُعَلَّقٌ — muallaq, osilib turgan."},
{num:394,time:"00:35:10,219 --> 00:35:16,599",arabic:"فِي أَعْمَاقِ السُّهُولِ الشَّرْقِيَّةِ لِبُولِيفْيَا",segs:[{ar:"فِي أَعْمَاقِ السُّهُولِ الشَّرْقِيَّةِ",uz:"sharqiy tekisliklarning ichkarisida"},{ar:"لِبُولِيفْيَا",uz:"Boliviyaning"}],full_uz:"Boliviyaning sharqiy tekisliklari ichkarisida.",note:null},
{num:395,time:"00:35:16,599 --> 00:35:20,759",arabic:"تَكْشِفُ شَلَّالَاتُ جَارْدِينْ دِي لَاسْ دِلِيسْيَاسْ",segs:null,full_uz:"Jardín de las Delicias sharsharalari namoyon qiladi.",note:null},
{num:396,time:"00:35:20,759 --> 00:35:25,779",arabic:"عَنْ مَشْهَدٍ صَاغَتْهُ الْحَرَكَاتُ التَّكْتُونِيَّةُ وَتَعْرِيَةُ الْأَنْهَارِ",segs:[{ar:"عَنْ مَشْهَدٍ صَاغَتْهُ الْحَرَكَاتُ التَّكْتُونِيَّةُ",uz:"tektonik harakatlar shakllantirgan manzarani"},{ar:"وَتَعْرِيَةُ الْأَنْهَارِ",uz:"va daryolar eroziyasi"}],full_uz:"Tektonik harakatlar va daryolar eroziyasi shakllantirgan manzarani namoyon qiladi.",note:"تَعْرِيَةٌ — eroziya, yemirilish."},
{num:397,time:"00:35:25,779 --> 00:35:29,079",arabic:"عَلَى مَدَى مَا يُقَارِبُ سِتِّينَ مِلْيُونَ عَامٍ",segs:null,full_uz:"Qariyb oltmish million yil davomida.",note:null},
{num:398,time:"00:35:29,079 --> 00:35:38,500",arabic:"هُنَا تَنْهَمِرُ ثَلَاثَةُ شَلَّالَاتٍ مِنْ مُنْحَدَرَاتٍ مِنَ الْحَجَرِ الرَّمْلِيِّ",segs:[{ar:"هُنَا تَنْهَمِرُ ثَلَاثَةُ شَلَّالَاتٍ",uz:"bu yerda uchta sharshara oqib tushadi"},{ar:"مِنْ مُنْحَدَرَاتٍ مِنَ الْحَجَرِ الرَّمْلِيِّ",uz:"qumtoshli yonbag‘irlardan"}],full_uz:"Bu yerda uchta sharshara qumtoshli yonbag‘irlardan oqib tushadi.",note:"تَنْهَمِرُ — sharros oqmoq, quyilib tushmoq."},
{num:399,time:"00:35:38,500 --> 00:35:41,980",arabic:"تَرْتَفِعُ لِأَكْثَرَ مِنْ خَمْسَةٍ وَأَرْبَعِينَ مِتْرًا",segs:null,full_uz:"Balandligi qirq besh metrdan oshadi.",note:null},
{num:400,time:"00:35:41,980 --> 00:35:44,960",arabic:"نَحَتَ الطَّبَقَةَ بَعْدَ الطَّبَقَةِ",segs:null,full_uz:"Qatlamma-qatlam o‘yilgan.",note:"الطَّبَقَةُ بَعْدَ الطَّبَقَةِ — qatlamma-qatlam."},
{num:401,time:"00:35:44,960 --> 00:35:50,579",arabic:"بِوَاسِطَةِ جَدَاوِلَ مُحَمَّلَةٍ بِرَوَاسِبَ غَنِيَّةٍ بِالْكُوَارْتْز",segs:[{ar:"بِوَاسِطَةِ جَدَاوِلَ مُحَمَّلَةٍ بِرَوَاسِبَ",uz:"cho‘kindilar bilan to‘yingan irmoqlar orqali"},{ar:"غَنِيَّةٍ بِالْكُوَارْتْز",uz:"kvarsga boy"}],full_uz:"Kvarsga boy cho‘kindilar olib keluvchi irmoqlar orqali.",note:"رَوَاسِبُ — cho‘kindilar. جَدْوَلٌ — irmoq."},
{num:402,time:"00:35:50,579 --> 00:35:57,659",arabic:"تَقَعُ الْمِنْطَقَةُ عَلَى حَافَّةِ نِظَامِ أَمْبُورُو الْبِيئِيِّ",segs:[{ar:"تَقَعُ الْمِنْطَقَةُ",uz:"hudud joylashgan"},{ar:"عَلَى حَافَّةِ نِظَامِ أَمْبُورُو الْبِيئِيِّ",uz:"Amboro ekotizimining chekkasida"}],full_uz:"Hudud Amboro ekotizimining chekkasida joylashgan.",note:"نِظَامٌ بِيئِيٌّ — ekotizim."},
{num:403,time:"00:35:57,659 --> 00:36:02,339",arabic:"أَحَدُ أَكْثَرِ مَمَرَّاتِ التَّنَوُّعِ الْحَيَوِيِّ كَثَافَةً فِي الْعَالَمِ",segs:[{ar:"أَحَدُ أَكْثَرِ مَمَرَّاتِ التَّنَوُّعِ الْحَيَوِيِّ",uz:"biologik xilma-xilligi eng zich hududlardan biri"},{ar:"كَثَافَةً فِي الْعَالَمِ",uz:"dunyodagi jihatidan"}],full_uz:"U dunyodagi biologik xilma-xilligi eng zich hududlardan biridir.",note:"التَّنَوُّعُ الْحَيَوِيُّ — biologik xilma-xillik. كَثَافَةٌ — zichlik."},
{num:404,time:"00:36:02,339 --> 00:36:05,679",arabic:"حَيْثُ تَتَجَاوَزُ الرُّطُوبَةُ ثَمَانِينَ فِي الْمِائَةِ",segs:null,full_uz:"U yerda namlik sakson foizdan oshadi.",note:null},
{num:405,time:"00:36:05,679 --> 00:36:11,379",arabic:"مُغَذِّيَةً غَابَاتٍ كَثِيفَةً مِنَ السَّرَاخِسِ وَالْبُرُومِيلِيَا وَأَشْجَارٍ شَاهِقَةٍ",segs:[{ar:"مُغَذِّيَةً غَابَاتٍ كَثِيفَةً",uz:"qalin o‘rmonlarni oziqlantirib"},{ar:"مِنَ السَّرَاخِسِ وَالْبُرُومِيلِيَا",uz:"qirqquloqlar va bromeliyalardan iborat"},{ar:"وَأَشْجَارٍ شَاهِقَةٍ",uz:"va baland daraxtlardan"}],full_uz:"Qirqquloqlar, bromeliyalar va baland daraxtlardan iborat qalin o‘rmonlarni oziqlantirib.",note:"السَّرَاخِسُ — qirqquloqlar. الْبُرُومِيلِيَا — bromeliyalar."},
{num:406,time:"00:36:11,379 --> 00:36:19,480",arabic:"يَسِيرُ الزُّوَّارُ عَبْرَ مَسَارَاتٍ مِنَ التُّرْبَةِ الْحَمْرَاءِ",segs:[{ar:"يَسِيرُ الزُّوَّارُ",uz:"ziyoratchilar yuradilar"},{ar:"عَبْرَ مَسَارَاتٍ مِنَ التُّرْبَةِ الْحَمْرَاءِ",uz:"qizil tuproq yo‘llari orqali"}],full_uz:"Ziyoratchilar qizil tuproq yo‘llari orqali yuradilar.",note:null},
{num:407,time:"00:36:19,480 --> 00:36:25,839",arabic:"عَابِرِينَ بِرَكًا شَفَّافَةً يُمْكِنُ رُؤْيَةُ قَاعِهَا عَلَى عُمْقِ ثَلَاثَةِ أَمْتَارٍ",segs:[{ar:"عَابِرِينَ بِرَكًا شَفَّافَةً",uz:"tiniq hovuzlardan o‘tib"},{ar:"يُمْكِنُ رُؤْيَةُ قَاعِهَا",uz:"ularning tubini ko‘rish mumkin"},{ar:"عَلَى عُمْقِ ثَلَاثَةِ أَمْتَارٍ",uz:"uch metr chuqurlikda"}],full_uz:"Ular tubi uch metr chuqurlikda ko‘rinadigan tiniq hovuzlardan o‘tadilar.",note:"بِرْكَةٌ — hovuz. شَفَّافٌ — tiniq, shaffof."},
{num:408,time:"00:36:25,840 --> 00:36:32,900",arabic:"يَرْتَفِعُ الضَّبَابُ مِنْ أَحْوَاضِ الِارْتِطَامِ لِيُخَفِّضَ الْحَرَارَةَ بِنَحْوِ سِتِّ دَرَجَاتٍ مِئَوِيَّةٍ",segs:[{ar:"يَرْتَفِعُ الضَّبَابُ مِنْ أَحْوَاضِ الِارْتِطَامِ",uz:"zarba havzalaridan tuman ko‘tariladi"},{ar:"لِيُخَفِّضَ الْحَرَارَةَ",uz:"haroratni pasaytirib"},{ar:"بِنَحْوِ سِتِّ دَرَجَاتٍ مِئَوِيَّةٍ",uz:"qariyb olti daraja Selsiyga"}],full_uz:"Zarba havzalaridan tuman ko‘tarilib, haroratni qariyb olti daraja Selsiyga pasaytiradi.",note:"حَوْضُ الِارْتِطَامِ — suv uriladigan havza, zarba havzasi."},
{num:409,time:"00:36:32,900 --> 00:36:39,600",arabic:"مُكَوِّنًا مُدَرَّجًا طَبِيعِيًّا مِنْ أَقْوَاسِ قُزَحٍ وَأَصْوَاتِ الطُّيُورِ الْمُتَرَدِّدَةِ",segs:[{ar:"مُكَوِّنًا مُدَرَّجًا طَبِيعِيًّا",uz:"tabiiy terassa hosil qilib"},{ar:"مِنْ أَقْوَاسِ قُزَحٍ",uz:"kamalaklardan"},{ar:"وَأَصْوَاتِ الطُّيُورِ الْمُتَرَدِّدَةِ",uz:"va aks-sado beruvchi qushlar ovozlaridan"}],full_uz:"Kamalaklar va aks-sado beruvchi qushlar ovozlaridan tabiiy terassa hosil qilib.",note:"الْمُتَرَدِّدُ — takrorlanib/aks-sado berib turuvchi."},
{num:410,time:"00:36:39,600 --> 00:36:45,519",arabic:"إِنَّهَا بَوَّابَةٌ حَيَّةٌ إِلَى مَاضِي الْأَرْضِ الْبِدَائِيِّ",segs:[{ar:"إِنَّهَا بَوَّابَةٌ حَيَّةٌ",uz:"u tirik darvozadir"},{ar:"إِلَى مَاضِي الْأَرْضِ الْبِدَائِيِّ",uz:"Yerning ibtidoiy o‘tmishiga"}],full_uz:"U Yerning ibtidoiy o‘tmishiga ochiladigan tirik darvozadir.",note:"الْبِدَائِيٌّ — ibtidoiy, qadimgi."},
{num:411,time:"00:36:48,960 --> 00:36:53,579",arabic:"تَنْهَضُ كُوبَانِيَهْ مِنْ خَلِيجِ فَانْجْنَا فِي تَايْلَانْد",segs:[{ar:"تَنْهَضُ كُوبَانِيَهْ",uz:"Kubanix ko‘tarilib turadi"},{ar:"مِنْ خَلِيجِ فَانْجْنَا فِي تَايْلَانْد",uz:"Tailanddagi Phang Nga qo‘ltig‘idan"}],full_uz:"Kubanix Tailanddagi Phang Nga qo‘ltig‘idan qad rostlab turadi.",note:null},
{num:412,time:"00:36:53,579 --> 00:36:56,139",arabic:"كَعَمُودٍ مِنَ الْحَجَرِ الْجِيرِيِّ",segs:null,full_uz:"Ohaktosh ustundek.",note:"عَمُودٌ — ustun."},
{num:413,time:"00:36:56,139 --> 00:37:00,079",arabic:"تَشَكَّلَ عَبْرَ أَكْثَرَ مِنْ مِائَتَيْ مِلْيُونِ عَامٍ",segs:[{ar:"تَشَكَّلَ",uz:"shakllangan"},{ar:"عَبْرَ أَكْثَرَ مِنْ مِائَتَيْ مِلْيُونِ عَامٍ",uz:"ikki yuz million yildan ortiq vaqt davomida"}],full_uz:"Ikki yuz million yildan ortiq vaqt davomida shakllangan.",note:null},
{num:414,time:"00:37:00,079 --> 00:37:02,719",arabic:"مِنَ الْحَرَكَاتِ التَّكْتُونِيَّةِ وَالتَّعْرِيَةِ",segs:null,full_uz:"Tektonik harakatlar va eroziya natijasida.",note:"التَّعْرِيَةُ — eroziya, yemirilish."},
{num:415,time:"00:37:02,719 --> 00:37:05,340",arabic:"عِنْدَ قَاعِدَتِهِ",segs:null,full_uz:"Uning etagida.",note:"قَاعِدَةٌ — asos, etak."},
{num:416,time:"00:37:05,340 --> 00:37:11,699",arabic:"تَطْفُو وَاحِدَةٌ مِنْ أَكْثَرِ الْقُرَى الْمَبْنِيَّةِ عَلَى رَكَائِزَ إِثَارَةً فِي الْعَالَمِ",segs:[{ar:"تَطْفُو وَاحِدَةٌ مِنْ أَكْثَرِ الْقُرَى",uz:"eng ... qishloqlardan biri suzib turadi"},{ar:"الْمَبْنِيَّةِ عَلَى رَكَائِزَ",uz:"tayanchlar ustiga qurilgan"},{ar:"إِثَارَةً فِي الْعَالَمِ",uz:"dunyodagi eng hayratlanarlilaridan"}],full_uz:"Uning etagida tayanchlar ustiga qurilgan dunyodagi eng hayratlanarli qishloqlardan biri suzib turadi.",note:"Manba jumlasidagi «إِثَارَةً» bu o‘rinda grammatik jihatdan noodatiy; mazmun kontekst asosida berildi."},
{num:417,time:"00:37:11,699 --> 00:37:14,679",arabic:"شُيِّدَتْ بِالْكَامِلِ فَوْقَ الْمَاءِ",segs:null,full_uz:"U butunlay suv ustiga qurilgan.",note:"شُيِّدَ — qurilgan, bunyod etilgan."},
{num:418,time:"00:37:14,679 --> 00:37:19,019",arabic:"عَلَى أَعْمِدَةٍ خَشَبِيَّةٍ وَخَرَسَانِيَّةٍ مَغْرُوسَةٍ",segs:[{ar:"عَلَى أَعْمِدَةٍ خَشَبِيَّةٍ وَخَرَسَانِيَّةٍ",uz:"yog‘och va beton ustunlar ustiga"},{ar:"مَغْرُوسَةٍ",uz:"qoqilgan"}],full_uz:"Qoqilgan yog‘och va beton ustunlar ustiga.",note:"خَرَسَانَةٌ — beton."},
{num:419,time:"00:37:19,019 --> 00:37:21,719",arabic:"حَتَّى عُمْقِ سِتَّةِ أَمْتَارٍ",segs:null,full_uz:"Olti metr chuqurlikkacha.",note:null},
{num:420,time:"00:37:21,719 --> 00:37:28,599",arabic:"أَسَّسَهَا صَيَّادُونَ إِنْدُونِيسِيُّونَ فِي أَوَاخِرِ الْقَرْنِ الثَّامِنَ عَشَرَ",segs:[{ar:"أَسَّسَهَا صَيَّادُونَ إِنْدُونِيسِيُّونَ",uz:"uni indoneziyalik baliqchilar asos solgan"},{ar:"فِي أَوَاخِرِ الْقَرْنِ الثَّامِنَ عَشَرَ",uz:"o‘n sakkizinchi asr oxirida"}],full_uz:"Unga o‘n sakkizinchi asr oxirida indoneziyalik baliqchilar asos solgan.",note:"أَوَاخِرُ — oxirgi qismlar, oxiri."},
{num:421,time:"00:37:28,599 --> 00:37:37,299",arabic:"ثُمَّ تَحَوَّلَتْ إِلَى مُتَاهَةٍ مِنَ الْبُيُوتِ الْمُعَلَّقَةِ وَالْمَمَرَّاتِ وَالْأَسْوَاقِ الْعَائِمَةِ",segs:[{ar:"ثُمَّ تَحَوَّلَتْ إِلَى مُتَاهَةٍ",uz:"so‘ng labirintga aylandi"},{ar:"مِنَ الْبُيُوتِ الْمُعَلَّقَةِ",uz:"muallaq uylar"},{ar:"وَالْمَمَرَّاتِ وَالْأَسْوَاقِ الْعَائِمَةِ",uz:"yo‘laklar va suzuvchi bozorlardan iborat"}],full_uz:"So‘ng muallaq uylar, yo‘laklar va suzuvchi bozorlardan iborat labirintga aylandi.",note:null},
{num:422,time:"00:37:37,299 --> 00:37:43,959",arabic:"شَاطِئُ فِسْتْرَاهُورْن فِي أَيْسْلَنْدَا",segs:null,full_uz:"Islandiyadagi Vestrahorn plyaji.",note:null},
{num:423,time:"00:37:43,959 --> 00:37:50,759",arabic:"يَقَعُ شَاطِئُ فِسْتْرَاهُورْن فِي شِبْهِ جَزِيرَةِ سْتُوكْسِنَ الْأَيْسْلَنْدِيَّةِ",segs:[{ar:"يَقَعُ شَاطِئُ فِسْتْرَاهُورْن",uz:"Vestrahorn plyaji joylashgan"},{ar:"فِي شِبْهِ جَزِيرَةِ سْتُوكْسِنَ الْأَيْسْلَنْدِيَّةِ",uz:"Islandiyaning Stoksnes yarimorolida"}],full_uz:"Vestrahorn plyaji Islandiyaning Stoksnes yarimorolida joylashgan.",note:null},
{num:424,time:"00:37:50,760 --> 00:37:54,720",arabic:"تُحْفَةٌ قَاسِيَةٌ صَاغَتْهَا النَّارُ وَالْجَلِيدُ",segs:[{ar:"تُحْفَةٌ قَاسِيَةٌ",uz:"qattiq va vahimali durdona"},{ar:"صَاغَتْهَا النَّارُ وَالْجَلِيدُ",uz:"uni olov va muz shakllantirgan"}],full_uz:"Uni olov va muz shakllantirgan qattiq va vahimali durdona.",note:"قَاسٍ — qattiq, keskin."},
{num:425,time:"00:37:54,720 --> 00:37:57,040",arabic:"وَرِيَاحُ الْمُحِيطِ الْعَاتِيَةُ",segs:null,full_uz:"Va okeanning shiddatli shamollari.",note:"عَاتٍ — shiddatli, kuchli."},
{num:426,time:"00:37:57,040 --> 00:38:04,400",arabic:"تَشَكَّلَ جَبَلُ فَسْتْرَاهُورْنَ قَبْلَ نَحْوِ ثَمَانِيَةِ مَلَايِينَ عَامٍ",segs:[{ar:"تَشَكَّلَ جَبَلُ فَسْتْرَاهُورْنَ",uz:"Vestrahorn tog‘i shakllangan"},{ar:"قَبْلَ نَحْوِ ثَمَانِيَةِ مَلَايِينَ عَامٍ",uz:"taxminan sakkiz million yil oldin"}],full_uz:"Vestrahorn tog‘i taxminan sakkiz million yil oldin shakllangan.",note:null},
{num:427,time:"00:38:04,400 --> 00:38:06,280",arabic:"مِنْ صَهَارَةٍ مُتَصَلِّبَةٍ",segs:null,full_uz:"Qotib qolgan magmadan.",note:"صَهَارَةٌ — magma."},
{num:428,time:"00:38:06,280 --> 00:38:12,380",arabic:"وَتَرْتَفِعُ قِمَمُهُ الْمُسَنَّنَةُ أَكْثَرَ مِنْ أَرْبَعِمِائَةٍ وَثَلَاثِينَ مِتْرًا",segs:[{ar:"وَتَرْتَفِعُ قِمَمُهُ الْمُسَنَّنَةُ",uz:"uning tishsimon cho‘qqilari ko‘tariladi"},{ar:"أَكْثَرَ مِنْ أَرْبَعِمِائَةٍ وَثَلَاثِينَ مِتْرًا",uz:"to‘rt yuz o‘ttiz metrdan ortiq"}],full_uz:"Uning tishsimon cho‘qqilari to‘rt yuz o‘ttiz metrdan ortiq ko‘tariladi.",note:"مُسَنَّنٌ — tishsimon, arrasimon."},
{num:429,time:"00:38:12,380 --> 00:38:14,800",arabic:"فَوْقَ شَاطِئِ الرِّمَالِ السَّوْدَاءِ",segs:null,full_uz:"Qora qumli sohil ustida.",note:null},
{num:430,time:"00:38:14,800 --> 00:38:22,460",arabic:"هَذِهِ الرِّمَالُ الدَّاكِنَةُ هِيَ نَتَاجُ تَدَفُّقَاتِ لَافَا بُرْكَانِيَّةٍ قَدِيمَةٍ",segs:[{ar:"هَذِهِ الرِّمَالُ الدَّاكِنَةُ",uz:"bu qoramtir qumlar"},{ar:"هِيَ نَتَاجُ تَدَفُّقَاتِ لَافَا بُرْكَانِيَّةٍ قَدِيمَةٍ",uz:"qadimiy vulqon lava oqimlarining mahsuli"}],full_uz:"Bu qoramtir qumlar qadimiy vulqon lava oqimlarining mahsulidir.",note:"نَتَاجٌ — mahsul, natija."},
{num:431,time:"00:38:22,460 --> 00:38:28,120",arabic:"حَطَّمَتْهَا الْأَمْوَاجُ وَالْأَنْهَارُ الْجَلِيدِيَّةُ عَبْرَ آلَافِ السِّنِينَ",segs:[{ar:"حَطَّمَتْهَا الْأَمْوَاجُ وَالْأَنْهَارُ الْجَلِيدِيَّةُ",uz:"to‘lqinlar va muzliklar ularni maydalagan"},{ar:"عَبْرَ آلَافِ السِّنِينَ",uz:"minglab yillar davomida"}],full_uz:"To‘lqinlar va muzliklar ularni minglab yillar davomida maydalagan.",note:"حَطَّمَ — maydalamoq, parchalamoq."},
{num:432,time:"00:38:28,120 --> 00:38:34,640",arabic:"هُنَا تَهُبُّ رِيَاحُ الْأَطْلَسِيِّ بِسُرَعٍ تَتَجَاوَزُ أَحْيَانًا",segs:[{ar:"هُنَا تَهُبُّ رِيَاحُ الْأَطْلَسِيِّ",uz:"bu yerda Atlantika shamollari esadi"},{ar:"بِسُرَعٍ تَتَجَاوَزُ أَحْيَانًا",uz:"ba’zan oshadigan tezliklarda"}],full_uz:"Bu yerda Atlantika shamollari ba’zan oshib ketadigan tezliklarda esadi.",note:null},
{num:433,time:"00:38:34,640 --> 00:38:37,460",arabic:"ثَمَانِينَ كِيلُومِتْرًا فِي السَّاعَةِ",segs:null,full_uz:"Soatiga sakson kilometr.",note:null},
{num:434,time:"00:38:37,460 --> 00:38:42,620",arabic:"فَتَنْحَتُ كُثْبَانًا تَتَحَرَّكُ عِدَّةَ سَنْتِيمِتْرَاتٍ فِي يَوْمٍ وَاحِدٍ",segs:[{ar:"فَتَنْحَتُ كُثْبَانًا",uz:"shunda ular qumtepalarni shakllantiradi"},{ar:"تَتَحَرَّكُ عِدَّةَ سَنْتِيمِتْرَاتٍ فِي يَوْمٍ وَاحِدٍ",uz:"bir kunda bir necha santimetr siljiydigan"}],full_uz:"Shunda ular bir kunda bir necha santimetr siljiydigan qumtepalarni shakllantiradi.",note:"كُثْبَانٌ — qumtepalar."},
{num:435,time:"00:38:42,619 --> 00:38:46,259",arabic:"لِتَخْلُقَ مَشْهَدًا لَا يَتَكَرَّرُ مَرَّتَيْنِ",segs:[{ar:"لِتَخْلُقَ مَشْهَدًا",uz:"bir manzara yaratib"},{ar:"لَا يَتَكَرَّرُ مَرَّتَيْنِ",uz:"ikki marta takrorlanmaydigan"}],full_uz:"Ikki marta takrorlanmaydigan manzarani yaratib.",note:"يَتَكَرَّرُ — takrorlanmoq."},
{num:436,time:"00:38:46,259 --> 00:38:53,920",arabic:"عِنْدَ الْجَزْرِ تَنْتَشِرُ طَبَقَاتٌ رَقِيقَةٌ مِنْ مِيَاهِ الْبَحْرِ فَوْقَ السُّهُولِ",segs:[{ar:"عِنْدَ الْجَزْرِ",uz:"suv qaytganda"},{ar:"تَنْتَشِرُ طَبَقَاتٌ رَقِيقَةٌ مِنْ مِيَاهِ الْبَحْرِ",uz:"dengiz suvining yupqa qatlamlari yoyiladi"},{ar:"فَوْقَ السُّهُولِ",uz:"tekisliklar ustida"}],full_uz:"Suv qaytganda dengiz suvining yupqa qatlamlari tekisliklar ustiga yoyiladi.",note:"الْجَزْرُ — suvning qaytishi, pasayishi."},
{num:437,time:"00:38:53,920 --> 00:38:59,779",arabic:"تَعْكِسُ سِلْوَاتِ الْجَبَلِ الْحَادِّ كَمِرْآةٍ طَبِيعِيَّةٍ مُذْهِلَةٍ",segs:[{ar:"تَعْكِسُ سِلْوَاتِ الْجَبَلِ الْحَادِّ",uz:"o‘tkir tog‘ shakllarini aks ettiradi"},{ar:"كَمِرْآةٍ طَبِيعِيَّةٍ مُذْهِلَةٍ",uz:"hayratlanarli tabiiy ko‘zgudek"}],full_uz:"Ular o‘tkir tog‘ shakllarini hayratlanarli tabiiy ko‘zgudek aks ettiradi.",note:"Manba matnidagi «سَلَوَاتِ» so‘zi noaniq; kontekstga ko‘ra tog‘ shakllari ma’nosida berildi."},
{num:438,time:"00:38:59,779 --> 00:39:06,980",arabic:"يَدْرُسُ الْعُلَمَاءُ فِسْتْرَاهُورْنَ كَنَمُوذَجٍ حَيٍّ لِلتَّشَكُّلِ السَّاحِلِيِّ السَّرِيعِ",segs:[{ar:"يَدْرُسُ الْعُلَمَاءُ فِسْتْرَاهُورْنَ",uz:"olimlar Vestrahornni o‘rganadilar"},{ar:"كَنَمُوذَجٍ حَيٍّ",uz:"tirik namuna sifatida"},{ar:"لِلتَّشَكُّلِ السَّاحِلِيِّ السَّرِيعِ",uz:"tezkor qirg‘oq shakllanishi uchun"}],full_uz:"Olimlar Vestrahornni tezkor qirg‘oq shakllanishining tirik namunasi sifatida o‘rganadilar.",note:"التَّشَكُّلُ السَّاحِلِيُّ — qirg‘oqning shakllanishi."},
{num:439,time:"00:39:06,980 --> 00:39:12,139",arabic:"بَيْنَمَا يَأْتِي الزُّوَّارُ بَحْثًا عَنْ ذَلِكَ السُّكُونِ السُّرْيَالِيِّ",segs:[{ar:"بَيْنَمَا يَأْتِي الزُّوَّارُ",uz:"ayni paytda ziyoratchilar keladilar"},{ar:"بَحْثًا عَنْ ذَلِكَ السُّكُونِ السُّرْيَالِيِّ",uz:"o‘sha syurreal sokinlikni izlab"}],full_uz:"Ayni paytda ziyoratchilar o‘sha syurreal sokinlikni izlab keladilar.",note:"سُكُونٌ — sokinlik, sukunat."},
{num:440,time:"00:39:12,139 --> 00:39:21,539",arabic:"حَيْثُ يَلْتَقِي مَاضِي الْأَرْضِ الْبُرْكَانِيُّ بِحَاضِرِهَا الْمُتَقَلِّبِ فِي مَشْهَدٍ وَاحِدٍ يَخْطَفُ الْأَنْفَاسَ",segs:[{ar:"حَيْثُ يَلْتَقِي مَاضِي الْأَرْضِ الْبُرْكَانِيُّ",uz:"u yerda yerning vulqonli o‘tmishi uchrashadi"},{ar:"بِحَاضِرِهَا الْمُتَقَلِّبِ",uz:"uning o‘zgaruvchan buguni bilan"},{ar:"فِي مَشْهَدٍ وَاحِدٍ يَخْطَفُ الْأَنْفَاسَ",uz:"nafasni bo‘g‘adigan yagona manzarada"}],full_uz:"U yerda Yerning vulqonli o‘tmishi uning o‘zgaruvchan buguni bilan nafasni bo‘g‘uvchi yagona manzarada uchrashadi.",note:"الْمُتَقَلِّبُ — o‘zgaruvchan, beqaror. يَخْطَفُ الْأَنْفَاسَ — hayratdan nafasni bo‘g‘moq."},
{num:441,time:"00:39:21,539 --> 00:39:28,920",arabic:"نَهْرُ سِينَافْلَسْيُوكُلْ الْجَلِيدِيُّ فِي أَيْسْلَنْدَا",segs:null,full_uz:"Islandiyadagi Snafellsjokull muzlik daryosi.",note:null},
{num:442,time:"00:39:28,920 --> 00:39:35,779",arabic:"يُعَدُّ سِينَافْلَسْيُوكُلْ أَحَدَ مَخَارِجِ الْغِطَاءِ الْجَلِيدِيِّ الْهَائِلِ فَاتْنَايُوكُل",segs:[{ar:"يُعَدُّ سِينَافْلَسْيُوكُلْ أَحَدَ مَخَارِجِ الْغِطَاءِ الْجَلِيدِيِّ الْهَائِلِ",uz:"Snafellsjokull ulkan muz qoplamining chiqishlaridan biri hisoblanadi"},{ar:"فَاتْنَايُوكُل",uz:"Vatnajokull"}],full_uz:"Snafellsjokull ulkan Vatnajokull muz qoplamining chiqishlaridan biri hisoblanadi.",note:"مَخْرَجٌ — chiqish joyi, tashqi yo‘l."},
{num:443,time:"00:39:35,779 --> 00:39:41,659",arabic:"أَرْشِيفًا طَبِيعِيًّا تَشَكَّلَ عَبْرَ عَشَرَاتِ آلَافِ السِّنِينَ",segs:[{ar:"أَرْشِيفًا طَبِيعِيًّا",uz:"tabiiy arxiv"},{ar:"تَشَكَّلَ عَبْرَ عَشَرَاتِ آلَافِ السِّنِينَ",uz:"o‘n minglab yillar davomida shakllangan"}],full_uz:"O‘n minglab yillar davomida shakllangan tabiiy arxiv.",note:"أَرْشِيفٌ — arxiv."},
{num:444,time:"00:39:41,659 --> 00:39:46,940",arabic:"مِنْ تَسَاقُطِ الثُّلُوجِ وَانْضِغَاطِهَا إِلَى جَلِيدٍ أَزْرَقَ كَثِيفٍ",segs:[{ar:"مِنْ تَسَاقُطِ الثُّلُوجِ وَانْضِغَاطِهَا",uz:"qorning yog‘ishi va siqilishidan"},{ar:"إِلَى جَلِيدٍ أَزْرَقَ كَثِيفٍ",uz:"qalin moviy muzga aylanguncha"}],full_uz:"Qorning yog‘ishi va siqilishidan qalin moviy muzga aylanguncha.",note:"انْضِغَاطٌ — siqilish, zichlashish."},
{num:445,time:"00:39:46,940 --> 00:39:54,739",arabic:"يَمْتَدُّ هَذَا النَّهْرُ الْمُتَجَمِّدُ لِمَسَافَةٍ تُقَارِبُ أَحَدَ عَشَرَ كِيلُومِتْرًا",segs:[{ar:"يَمْتَدُّ هَذَا النَّهْرُ الْمُتَجَمِّدُ",uz:"bu muzlagan daryo cho‘ziladi"},{ar:"لِمَسَافَةٍ تُقَارِبُ أَحَدَ عَشَرَ كِيلُومِتْرًا",uz:"qariyb o‘n bir kilometr masofaga"}],full_uz:"Bu muzlagan daryo qariyb o‘n bir kilometr masofaga cho‘ziladi.",note:null},
{num:446,time:"00:39:54,739 --> 00:40:00,739",arabic:"قَاطِعًا طَرِيقَهُ بَيْنَ جِبَالٍ بُرْكَانِيَّةٍ مُكَوَّنَةٍ مِنَ الْبَازَلْتِ وَالرَّمَادِ",segs:[{ar:"قَاطِعًا طَرِيقَهُ بَيْنَ جِبَالٍ بُرْكَانِيَّةٍ",uz:"vulqonli tog‘lar orasidan yo‘l kesib"},{ar:"مُكَوَّنَةٍ مِنَ الْبَازَلْتِ وَالرَّمَادِ",uz:"bazalt va kuldan tashkil topgan"}],full_uz:"Bazalt va kuldan tashkil topgan vulqonli tog‘lar orasidan yo‘l kesib o‘tadi.",note:"قَاطِعٌ طَرِيقَهُ — yo‘lini kesib o‘tuvchi."},
{num:447,time:"00:40:00,739 --> 00:40:05,920",arabic:"تَحْمِلُ طَبَقَاتُهَا سِجِلًّا لِأَعْنَفِ ثَوَرَاتِ الْأَرْضِ",segs:[{ar:"تَحْمِلُ طَبَقَاتُهَا سِجِلًّا",uz:"uning qatlamlari qaydni saqlaydi"},{ar:"لِأَعْنَفِ ثَوَرَاتِ الْأَرْضِ",uz:"Yerning eng kuchli otilishlari haqida"}],full_uz:"Uning qatlamlari Yerning eng kuchli vulqon otilishlari haqida qayd saqlaydi.",note:"ثَوَرَاتٌ — otilishlar, vulqon portlashlari. أَعْنَفُ — eng shiddatli."},
{num:448,time:"00:40:05,920 --> 00:40:12,940",arabic:"تَتَحَرَّكُ شُقُوقُهُ الْحَادَّةُ وَجُدْرَانُهُ الْجَلِيدِيَّةُ الشَّاهِقَةُ بِبُطْءٍ شَدِيدٍ",segs:[{ar:"تَتَحَرَّكُ شُقُوقُهُ الْحَادَّةُ",uz:"uning o‘tkir yoriqlari harakatlanadi"},{ar:"وَجُدْرَانُهُ الْجَلِيدِيَّةُ الشَّاهِقَةُ",uz:"va baland muz devorlari"},{ar:"بِبُطْءٍ شَدِيدٍ",uz:"nihoyatda sekin"}],full_uz:"Uning o‘tkir yoriqlari va baland muz devorlari nihoyatda sekin harakatlanadi.",note:"شُقُوقٌ — yoriqlar. شَاهِقٌ — juda baland."},
{num:449,time:"00:40:12,940 --> 00:40:16,039",arabic:"أَحْيَانًا أَمْتَارًا قَلِيلَةً فِي السَّنَةِ",segs:null,full_uz:"Ba’zan yiliga atigi bir necha metr.",note:"أَمْتَارٌ قَلِيلَةٌ — bir necha metr."},
{num:450,time:"00:40:16,039 --> 00:40:20,280",arabic:"بِفِعْلِ الْجَاذِبِيَّةِ وَالْمُنَاخِ شِبْهِ الْقُطْبِيِّ",segs:[{ar:"بِفِعْلِ الْجَاذِبِيَّةِ",uz:"tortishish kuchi ta’sirida"},{ar:"وَالْمُنَاخِ شِبْهِ الْقُطْبِيِّ",uz:"va qutbga yaqin iqlim"}],full_uz:"Tortishish kuchi va qutbga yaqin iqlim ta’sirida.",note:"الْجَاذِبِيَّةُ — tortishish kuchi. شِبْهُ الْقُطْبِيِّ — qutbga yaqin, subarktik."},
{num:451,time:"00:40:20,280 --> 00:40:24,400",arabic:"حَيْثُ تَبْقَى الْحَرَارَةُ قُرْبَ الصِّفْرِ مُعْظَمَ الْعَامِ",segs:[{ar:"حَيْثُ تَبْقَى الْحَرَارَةُ قُرْبَ الصِّفْرِ",uz:"u yerda harorat nolga yaqin qoladi"},{ar:"مُعْظَمَ الْعَامِ",uz:"yilning katta qismida"}],full_uz:"U yerda yilning katta qismida harorat nolga yaqin bo‘lib qoladi.",note:"قُرْبَ الصِّفْرِ — nolga yaqin."},
{num:452,time:"00:40:24,400 --> 00:40:29,820",arabic:"سَطْحُهُ الْمَرْشُوشُ بِالْغُبَارِ الْبُرْكَانِيِّ الْأَسْوَدِ",segs:[{ar:"سَطْحُهُ الْمَرْشُوشُ",uz:"uning sepilgan yuzasi"},{ar:"بِالْغُبَارِ الْبُرْكَانِيِّ الْأَسْوَدِ",uz:"qora vulqon changi bilan"}],full_uz:"Uning yuzasi qora vulqon changi bilan sepilgan.",note:"مَرْشُوشٌ — sepilgan. الْغُبَارُ الْبُرْكَانِيُّ — vulqon changi."},
{num:453,time:"00:40:29,820 --> 00:40:34,440",arabic:"تَحَوَّلَ إِلَى مُخْتَبَرٍ مَفْتُوحٍ لِدِرَاسَةِ تَغَيُّرِ الْمُنَاخِ",segs:[{ar:"تَحَوَّلَ إِلَى مُخْتَبَرٍ مَفْتُوحٍ",uz:"ochiq laboratoriyaga aylandi"},{ar:"لِدِرَاسَةِ تَغَيُّرِ الْمُنَاخِ",uz:"iqlim o‘zgarishini o‘rganish uchun"}],full_uz:"Iqlim o‘zgarishini o‘rganish uchun ochiq laboratoriyaga aylandi.",note:"تَغَيُّرُ الْمُنَاخِ — iqlim o‘zgarishi."},
{num:454,time:"00:40:34,440 --> 00:40:43,400",arabic:"هُنَا يَلْتَقِي نَارُ الْأَرْضِ بِجَلِيدِهَا فِي أَحَدِ أَكْثَرِ الْمَشَاهِدِ سُرْيَالِيَّةً عَلَى الْكَوْكَبِ",segs:[{ar:"هُنَا يَلْتَقِي نَارُ الْأَرْضِ بِجَلِيدِهَا",uz:"bu yerda yer olovi uning muzligi bilan uchrashadi"},{ar:"فِي أَحَدِ أَكْثَرِ الْمَشَاهِدِ سُرْيَالِيَّةً عَلَى الْكَوْكَبِ",uz:"sayyoradagi eng syurreal manzaralardan birida"}],full_uz:"Bu yerda yer olovi uning muzligi bilan sayyoradagi eng syurreal manzaralardan birida uchrashadi.",note:"جَلِيدٌ — muz, muzlik."},
{num:455,time:"00:40:43,400 --> 00:40:49,659",arabic:"عَلَى طُولِ طَرِيقِ الْمُحِيطِ الْعَظِيمِ جَنُوبَ أُسْتُرَالِيَا",segs:[{ar:"عَلَى طُولِ طَرِيقِ الْمُحِيطِ الْعَظِيمِ",uz:"Buyuk Okean yo‘li bo‘ylab"},{ar:"جَنُوبَ أُسْتُرَالِيَا",uz:"Janubiy Avstraliyada"}],full_uz:"Janubiy Avstraliyadagi Buyuk Okean yo‘li bo‘ylab.",note:null},
{num:456,time:"00:40:49,659 --> 00:40:53,639",arabic:"تَنْهَضُ الرُّسُلُ الِاثْنَا عَشَرَ مِنْ بَحْرٍ هَائِجٍ",segs:[{ar:"تَنْهَضُ الرُّسُلُ الِاثْنَا عَشَرَ",uz:"O‘n ikki havoriy qad rostlaydi"},{ar:"مِنْ بَحْرٍ هَائِجٍ",uz:"to‘lqinlanayotgan dengizdan"}],full_uz:"O‘n ikki havoriy to‘lqinlanayotgan dengizdan qad rostlaydi.",note:"الرُّسُلُ الِاثْنَا عَشَرَ — O‘n ikki havoriylar. هَائِجٌ — to‘lqinlangan, jo‘shqin."},
{num:457,time:"00:40:53,639 --> 00:40:56,380",arabic:"لَا كَنُصُبٍ صَنَعَهَا الْإِنْسَانُ",segs:null,full_uz:"Inson yasagan yodgorliklar kabi emas.",note:"نُصُبٌ — yodgorlik, monument."},
{num:458,time:"00:40:56,380 --> 00:41:03,420",arabic:"بَلْ كَآثَارٍ نَحَتَتْهَا الطَّبِيعَةُ عَبْرَ عِشْرِينَ مِلْيُونَ عَامٍ مِنَ الرِّيَاحِ وَالْأَمْوَاجِ",segs:[{ar:"بَلْ كَآثَارٍ نَحَتَتْهَا الطَّبِيعَةُ",uz:"balki tabiat o‘ygan yodgorliklar kabi"},{ar:"عَبْرَ عِشْرِينَ مِلْيُونَ عَامٍ",uz:"yigirma million yil davomida"},{ar:"مِنَ الرِّيَاحِ وَالْأَمْوَاجِ",uz:"shamollar va to‘lqinlar ta’sirida"}],full_uz:"Balki tabiat shamol va to‘lqinlar ta’sirida yigirma million yil davomida o‘ygan yodgorliklardir.",note:"آثَارٌ — qoldiqlar, yodgorliklar."},
{num:459,time:"00:41:03,420 --> 00:41:10,940",arabic:"بَدَأَتِ الْقِصَّةُ بِأَقْوَاسٍ بَحْرِيَّةٍ نُحِتَتْ فِي الْجُرُوفِ",segs:[{ar:"بَدَأَتِ الْقِصَّةُ بِأَقْوَاسٍ بَحْرِيَّةٍ",uz:"voqea dengiz ravoqlaridan boshlangan"},{ar:"نُحِتَتْ فِي الْجُرُوفِ",uz:"qoyalarda o‘yilgan"}],full_uz:"Voqea qoyalarda o‘yilgan dengiz ravoqlaridan boshlangan.",note:"قَوْسٌ بَحْرِيٌّ — dengiz ravoqi, tabiiy ark."},
{num:460,time:"00:41:10,940 --> 00:41:20,880",arabic:"وَمَعَ انْهِيَارِهَا بَقِيَتْ أَعْمِدَةٌ صَخْرِيَّةٌ مُنْفَصِلَةٌ تَرْتَفِعُ الْيَوْمَ حَتَّى خَمْسَةٍ وَسَبْعِينَ مِتْرًا فِي السَّمَاءِ",segs:[{ar:"وَمَعَ انْهِيَارِهَا بَقِيَتْ أَعْمِدَةٌ صَخْرِيَّةٌ مُنْفَصِلَةٌ",uz:"ular qulagach alohida qoyali ustunlar qolgan"},{ar:"تَرْتَفِعُ الْيَوْمَ حَتَّى خَمْسَةٍ وَسَبْعِينَ مِتْرًا",uz:"bugun yetmish besh metrgacha ko‘tariladi"},{ar:"فِي السَّمَاءِ",uz:"osmonga tomon"}],full_uz:"Ular qulagach, alohida qoyali ustunlar qolgan va bugun yetmish besh metrgacha osmonga ko‘tariladi.",note:"انْهِيَارٌ — qulash, yemirilish. مُنْفَصِلٌ — alohida ajralgan."},
{num:461,time:"00:41:20,880 --> 00:41:26,680",arabic:"تَتَغَيَّرُ أَشْكَالُهَا بِاسْتِمْرَارٍ",segs:null,full_uz:"Ularning shakllari doimo o‘zgarib turadi.",note:"بِاسْتِمْرَارٍ — uzluksiz, doimo."},
{num:462,time:"00:41:26,680 --> 00:41:35,119",arabic:"إِذْ يَتَآكَلُ الْحَجَرُ الْجِيرِيُّ بِمَعَدَّلٍ يُقَارِبُ 2.5 سَنْتِيمِتْرًا كُلَّ سِتِّ سَنَوَاتٍ",segs:[{ar:"إِذْ يَتَآكَلُ الْحَجَرُ الْجِيرِيُّ",uz:"ohaktosh yemiriladi"},{ar:"بِمَعَدَّلٍ يُقَارِبُ 2.5 سَنْتِيمِتْرًا",uz:"qariyb 2,5 santimetr tezlikda"},{ar:"كُلَّ سِتِّ سَنَوَاتٍ",uz:"har olti yilda"}],full_uz:"Chunki ohaktosh har olti yilda qariyb 2,5 santimetr tezlikda yemiriladi.",note:"يَتَآكَلُ — yemirilmoq. بِمَعَدَّلٍ — tezlikda, sur’atda."},
{num:463,time:"00:41:35,119 --> 00:41:39,559",arabic:"الْيَوْمَ لَمْ يَبْقَ سِوَى ثَمَانِيَةِ أَعْمِدَةٍ رَئِيسِيَّةٍ",segs:[{ar:"الْيَوْمَ لَمْ يَبْقَ سِوَى ثَمَانِيَةِ أَعْمِدَةٍ",uz:"bugun atigi sakkizta ustun qolgan"},{ar:"رَئِيسِيَّةٍ",uz:"asosiy"}],full_uz:"Bugun atigi sakkizta asosiy ustun qolgan.",note:"لَمْ يَبْقَ سِوَى — faqat ... qolgan."},
{num:464,time:"00:41:39,559 --> 00:41:45,280",arabic:"لَكِنَّ لَوْنَهَا الذَّهَبِيَّ عِنْدَ الشُّرُوقِ وَتَوَهُّجَهَا النَّارِيَّ عِنْدَ الْغُرُوبِ",segs:[{ar:"لَكِنَّ لَوْنَهَا الذَّهَبِيَّ عِنْدَ الشُّرُوقِ",uz:"ammo ularning quyosh chiqishidagi oltin rangi"},{ar:"وَتَوَهُّجَهَا النَّارِيَّ عِنْدَ الْغُرُوبِ",uz:"va botish paytidagi olovdek yarqirashi"}],full_uz:"Ammo ularning quyosh chiqishidagi oltin rangi va botish paytidagi olovdek yarqirashi.",note:"الشُّرُوقُ — quyosh chiqishi. الْغُرُوبُ — quyosh botishi."},
{num:465,time:"00:41:45,280 --> 00:41:48,019",arabic:"يَمْنَحُهَا مَظْهَرًا أُسْطُورِيًّا",segs:null,full_uz:"Ularga afsonaviy ko‘rinish beradi.",note:"مَظْهَرٌ — ko‘rinish, qiyofa."},
{num:466,time:"00:41:48,019 --> 00:41:53,699",arabic:"وَأَنْتَ تَقِفُ عَلَى حَافَّةِ الْجُرْفِ",segs:null,full_uz:"Siz jarlik chetida turganingizda.",note:"حَافَّةٌ — chekka, qir. جُرْفٌ — jarlik."},
{num:467,time:"00:41:53,699 --> 00:41:59,199",arabic:"يُمْكِنُكَ سَمَاعُ الْمُحِيطِ وَهُوَ لَا يَزَالُ يَنْحَتُ رُسُلَهُ الْقَادِمَةَ",segs:[{ar:"يُمْكِنُكَ سَمَاعُ الْمُحِيطِ",uz:"okeanni eshitishingiz mumkin"},{ar:"وَهُوَ لَا يَزَالُ يَنْحَتُ رُسُلَهُ الْقَادِمَةَ",uz:"u esa hali ham kelajakdagi ustunlarini o‘yishda davom etmoqda"}],full_uz:"Siz okeanni eshitishingiz mumkin; u hali ham kelajakdagi ustunlarini o‘yishda davom etmoqda.",note:"رُسُلُهُ الْقَادِمَةُ — bu yerda kelajakda paydo bo‘ladigan qoyali ustunlar ma’nosida."},
{num:468,time:"00:41:59,199 --> 00:42:01,599",arabic:"مَوْجَةً بَعْدَ مَوْجَةٍ",segs:null,full_uz:"To‘lqin ortidan to‘lqin.",note:"مَوْجَةٌ بَعْدَ مَوْجَةٍ — ketma-ket to‘lqinlar."},
{num:469,time:"00:42:05,519 --> 00:42:09,280",arabic:"وَادِي نَهْرِ بْلَايْد فِي جَنُوبِ أَفْرِيقِيَا",segs:null,full_uz:"Janubiy Afrikadagi Blyde daryosi vodiysi.",note:null},
{num:470,time:"00:42:09,280 --> 00:42:15,860",arabic:"يُعَدُّ وَادِي نَهْرِ بْلَايْد وَاحِدًا مِنَ الْقَلَائِلِ الْخَضْرَاءِ عَلَى كَوْكَبِ الْأَرْضِ",segs:[{ar:"يُعَدُّ وَادِي نَهْرِ بْلَايْد وَاحِدًا مِنَ الْقَلَائِلِ الْخَضْرَاءِ",uz:"Blyde daryosi vodiysi kam sonli yashil joylardan biri hisoblanadi"},{ar:"عَلَى كَوْكَبِ الْأَرْضِ",uz:"Yer sayyorasida"}],full_uz:"Blyde daryosi vodiysi Yer sayyorasidagi kam sonli yam-yashil joylardan biri hisoblanadi.",note:null},
{num:471,time:"00:42:15,860 --> 00:42:21,800",arabic:"وَقَدْ نُحِتَ عَلَى مَدَى أَكْثَرَ مِنْ عِشْرِينَ مِلْيُونَ عَامٍ بِفِعْلِ الْمَاءِ وَالرِّيَاحِ",segs:[{ar:"وَقَدْ نُحِتَ عَلَى مَدَى أَكْثَرَ مِنْ عِشْرِينَ مِلْيُونَ عَامٍ",uz:"u yigirma million yildan ortiq vaqt davomida o‘yilgan"},{ar:"بِفِعْلِ الْمَاءِ وَالرِّيَاحِ",uz:"suv va shamol ta’sirida"}],full_uz:"U yigirma million yildan ortiq vaqt davomida suv va shamol ta’sirida o‘yilgan.",note:null},
{num:472,time:"00:42:21,800 --> 00:42:28,099",arabic:"يَمْتَدُّ لِمَسَافَةٍ تُقَارِبُ سِتَّةً وَعِشْرِينَ كِيلُومِتْرًا",segs:null,full_uz:"Qariyb yigirma olti kilometr masofaga cho‘ziladi.",note:null},
{num:473,time:"00:42:28,099 --> 00:42:32,400",arabic:"وَيَغُوصُ بِعُمْقٍ يَزِيدُ عَنْ ثَمَانِمِائَةِ مِتْرٍ",segs:[{ar:"وَيَغُوصُ بِعُمْقٍ",uz:"va chuqurlikka tushadi"},{ar:"يَزِيدُ عَنْ ثَمَانِمِائَةِ مِتْرٍ",uz:"sakkiz yuz metrdan oshadigan"}],full_uz:"Va sakkiz yuz metrdan oshadigan chuqurlikka tushadi.",note:"يَغُوصُ — chuqurlashmoq, pastga botmoq."},
{num:474,time:"00:42:32,400 --> 00:42:35,800",arabic:"لِتُشَكِّلَ جُدْرَانُهُ الْكُوَارْتْزِيتِيَّةُ الشَّاهِقَةُ",segs:null,full_uz:"Uning baland kvarsit devorlari hosil qilib.",note:"الْكُوَارْتْزِيتُ — kvarsit."},
{num:475,time:"00:42:35,800 --> 00:42:40,900",arabic:"مُدَرَّجًا طَبِيعِيًّا مِنَ الْغَابَاتِ الزُّمُرُّدِيَّةِ وَالضَّبَابِ الْمُتَصَاعِدِ",segs:[{ar:"مُدَرَّجًا طَبِيعِيًّا",uz:"tabiiy terassa"},{ar:"مِنَ الْغَابَاتِ الزُّمُرُّدِيَّةِ",uz:"zumrad rangli o‘rmonlardan"},{ar:"وَالضَّبَابِ الْمُتَصَاعِدِ",uz:"va ko‘tarilayotgan tumandan"}],full_uz:"Zumrad rangli o‘rmonlar va ko‘tarilayotgan tumandan iborat tabiiy terassani hosil qilib.",note:"مُتَصَاعِدٌ — ko‘tarilayotgan."},
{num:476,time:"00:42:40,900 --> 00:42:47,260",arabic:"مِنْ نُقَاطِ الْمُرَاقَبَةِ مِثْلَ الدَّوَائِرِ الثَّلَاثِ",segs:[{ar:"مِنْ نُقَاطِ الْمُرَاقَبَةِ",uz:"kuzatuv nuqtalaridan"},{ar:"مِثْلَ الدَّوَائِرِ الثَّلَاثِ",uz:"masalan, Uchta doira nuqtalaridan"}],full_uz:"Uchta doira kabi kuzatuv nuqtalaridan.",note:"نُقْطَةُ الْمُرَاقَبَةِ — kuzatuv nuqtasi."},
{num:477,time:"00:42:47,260 --> 00:42:54,400",arabic:"يَشْعُرُ الزَّائِرُ بِضَآلَتِهِ أَمَامَ مَشْهَدٍ صَاغَتْهُ الْحَرَكَاتُ التَّكْتُونِيَّةُ الْقَدِيمَةُ",segs:[{ar:"يَشْعُرُ الزَّائِرُ بِضَآلَتِهِ",uz:"ziyoratchi o‘zining kichikligini his qiladi"},{ar:"أَمَامَ مَشْهَدٍ صَاغَتْهُ الْحَرَكَاتُ التَّكْتُونِيَّةُ الْقَدِيمَةُ",uz:"qadimiy tektonik harakatlar shakllantirgan manzara oldida"}],full_uz:"Ziyoratchi qadimiy tektonik harakatlar shakllantirgan manzara oldida o‘zining kichikligini his qiladi.",note:"ضَآلَةٌ — kichiklik, ojizlik hissi."},
{num:478,time:"00:42:54,400 --> 00:42:59,539",arabic:"وَمِنْ حَافَّةِ الْوَادِي يَلْمَعُ النَّهْرُ بَعِيدًا فِي الْأَسْفَلِ",segs:[{ar:"وَمِنْ حَافَّةِ الْوَادِي",uz:"vodiy chetidan"},{ar:"يَلْمَعُ النَّهْرُ بَعِيدًا فِي الْأَسْفَلِ",uz:"daryo pastda uzoqda yaltirab ko‘rinadi"}],full_uz:"Vodiy chetidan daryo pastda uzoqda yaltirab ko‘rinadi.",note:null},
{num:479,time:"00:42:59,539 --> 00:43:04,539",arabic:"تَذْكِيرًا مَهِيبًا بِقُوَّةِ الْأَرْضِ الْجِيُولُوجِيَّةِ الْخَامِ",segs:[{ar:"تَذْكِيرًا مَهِيبًا",uz:"ulug‘vor eslatma"},{ar:"بِقُوَّةِ الْأَرْضِ الْجِيُولُوجِيَّةِ الْخَامِ",uz:"Yerning sof geologik qudrati haqida"}],full_uz:"Bu Yerning sof geologik qudrati haqidagi ulug‘vor eslatmadir.",note:"خَامٌ — sof, ishlov berilmagan."},
{num:480,time:"00:43:04,539 --> 00:43:07,960",arabic:"جَبَلُ كَايْلَاشَ بِالتِّبْتِ",segs:null,full_uz:"Tibetdagi Kailash tog‘i.",note:null},
{num:481,time:"00:43:07,960 --> 00:43:15,139",arabic:"يَرْتَفِعُ جَبَلُ كَايْلَاشَ لِأَكْثَرَ مِنْ سِتَّةِ آلَافٍ وَأَرْبَعِمِائَةِ مِتْرٍ فَوْقَ هَضْبَةِ التِّبْتِ",segs:[{ar:"يَرْتَفِعُ جَبَلُ كَايْلَاشَ",uz:"Kailash tog‘i ko‘tariladi"},{ar:"لِأَكْثَرَ مِنْ سِتَّةِ آلَافٍ وَأَرْبَعِمِائَةِ مِتْرٍ",uz:"olti ming to‘rt yuz metrdan ortiq"},{ar:"فَوْقَ هَضْبَةِ التِّبْتِ",uz:"Tibet platosidan"}],full_uz:"Kailash tog‘i Tibet platosidan olti ming to‘rt yuz metrdan ortiq baland ko‘tariladi.",note:null},
{num:482,time:"00:43:15,139 --> 00:43:21,380",arabic:"لِيُعَدَّ مِنْ أَكْثَرِ التَّكَوُّنَاتِ الْجِيُولُوجِيَّةِ غُمُوضًا عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"لِيُعَدَّ مِنْ أَكْثَرِ التَّكَوُّنَاتِ الْجِيُولُوجِيَّةِ",uz:"eng sirli geologik shakllanishlardan biri hisoblanishi uchun"},{ar:"غُمُوضًا عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzidagi jihatdan"}],full_uz:"U yer yuzidagi eng sirli geologik shakllanishlardan biri hisoblanadi.",note:"تَكَوُّنٌ — shakllanish, geologik hosila."},
{num:483,time:"00:43:21,380 --> 00:43:26,920",arabic:"قِمَّةٌ شِبْهُ مُثَالِيَّةٍ فِي تَمَاثُلِهَا",segs:[{ar:"قِمَّةٌ شِبْهُ مُثَالِيَّةٍ",uz:"deyarli mukammal cho‘qqi"},{ar:"فِي تَمَاثُلِهَا",uz:"o‘zining simmetriyasi jihatidan"}],full_uz:"O‘zining simmetriyasi jihatidan deyarli mukammal cho‘qqi.",note:"تَمَاثُلٌ — simmetriya, mutanosiblik."},
{num:484,time:"00:43:26,920 --> 00:43:33,720",arabic:"نُحِتَتْ بِفِعْلِ الْحَرَكَاتِ التَّكْتُونِيَّةِ عَلَى مَدَى عَشَرَاتِ الْمَلَايِينَ مِنَ السِّنِينَ",segs:[{ar:"نُحِتَتْ بِفِعْلِ الْحَرَكَاتِ التَّكْتُونِيَّةِ",uz:"tektonik harakatlar ta’sirida o‘yilgan"},{ar:"عَلَى مَدَى عَشَرَاتِ الْمَلَايِينَ مِنَ السِّنِينَ",uz:"o‘nlab million yillar davomida"}],full_uz:"O‘nlab million yillar davomida tektonik harakatlar ta’sirida o‘yilgan.",note:null},
{num:485,time:"00:43:33,719 --> 00:43:39,019",arabic:"يُلْفِتُ الْعُلَمَاءُ إِلَى شَكْلِهِ الْفَرِيدِ ذِي الْجَوَانِبِ الْأَرْبَعَةِ",segs:[{ar:"يُلْفِتُ الْعُلَمَاءُ إِلَى شَكْلِهِ الْفَرِيدِ",uz:"olimlar uning noyob shakliga e’tibor qaratadilar"},{ar:"ذِي الْجَوَانِبِ الْأَرْبَعَةِ",uz:"to‘rt qirrali"}],full_uz:"Olimlar uning to‘rt qirrali noyob shakliga e’tibor qaratadilar.",note:"ذُو الْجَوَانِبِ — qirralarga ega."},
{num:486,time:"00:43:39,019 --> 00:43:43,959",arabic:"الْمُصْطَفَّةِ بِدِقَّةٍ مُذْهِلَةٍ مَعَ الِاتِّجَاهَاتِ الْأَصْلِيَّةِ",segs:[{ar:"الْمُصْطَفَّةِ بِدِقَّةٍ مُذْهِلَةٍ",uz:"hayratlanarli aniqlik bilan joylashgan"},{ar:"مَعَ الِاتِّجَاهَاتِ الْأَصْلِيَّةِ",uz:"asosiy yo‘nalishlarga nisbatan"}],full_uz:"Ular asosiy yo‘nalishlarga nisbatan hayratlanarli aniqlik bilan joylashgan.",note:"الِاتِّجَاهَاتُ الْأَصْلِيَّةُ — asosiy yo‘nalishlar."},
{num:487,time:"00:43:43,959 --> 00:43:51,819",arabic:"يَقَعُ الْجَبَلُ فِي مُنَاخٍ صَحْرَاوِيٍّ بَارِدٍ عَلَى ارْتِفَاعٍ شَاهِقٍ",segs:[{ar:"يَقَعُ الْجَبَلُ فِي مُنَاخٍ صَحْرَاوِيٍّ بَارِدٍ",uz:"tog‘ sovuq cho‘l iqlimida joylashgan"},{ar:"عَلَى ارْتِفَاعٍ شَاهِقٍ",uz:"nihoyatda balandlikda"}],full_uz:"Tog‘ nihoyatda balandlikdagi sovuq cho‘l iqlimida joylashgan.",note:"صَحْرَاوِيٌّ — cho‘lga oid. شَاهِقٌ — juda baland."},
{num:488,time:"00:43:51,819 --> 00:43:58,019",arabic:"حَيْثُ تَهْبِطُ دَرَجَاتُ الْحَرَارَةِ إِلَى مَا دُونَ سَالِبِ ثَلَاثِينَ دَرَجَةً مِئَوِيَّةً",segs:[{ar:"حَيْثُ تَهْبِطُ دَرَجَاتُ الْحَرَارَةِ",uz:"u yerda harorat tushadi"},{ar:"إِلَى مَا دُونَ سَالِبِ ثَلَاثِينَ دَرَجَةً مِئَوِيَّةً",uz:"minus o‘ttiz daraja Selsiydan ham pastga"}],full_uz:"U yerda harorat minus o‘ttiz daraja Selsiydan ham pastga tushadi.",note:"مَا دُونَ — ...dan past."},
{num:489,time:"00:43:58,019 --> 00:44:03,139",arabic:"بَيْنَمَا تُغَذِّي الْأَنْهَارُ الْجَلِيدِيَّةُ الْمُحِيطَةُ بِهِ أَنْهَارًا",segs:[{ar:"بَيْنَمَا تُغَذِّي الْأَنْهَارُ الْجَلِيدِيَّةُ الْمُحِيطَةُ بِهِ",uz:"ayni paytda uni o‘rab turgan muzliklar daryolarni oziqlantiradi"},{ar:"أَنْهَارًا",uz:"daryolarni"}],full_uz:"Ayni paytda uni o‘rab turgan muzliklar daryolarni oziqlantiradi.",note:"الْأَنْهَارُ الْجَلِيدِيَّةُ — muzliklar."},
{num:490,time:"00:44:03,139 --> 00:44:06,879",arabic:"تُوَفِّرُ الْمِيَاهَ لِأَكْثَرَ مِنْ مِلْيَارِ إِنْسَانٍ",segs:[{ar:"تُوَفِّرُ الْمِيَاهَ",uz:"suv bilan ta’minlaydi"},{ar:"لِأَكْثَرَ مِنْ مِلْيَارِ إِنْسَانٍ",uz:"bir milliarddan ortiq insonni"}],full_uz:"Bir milliarddan ortiq insonni suv bilan ta’minlaydi.",note:"تُوَفِّرُ — ta’minlamoq."},
{num:491,time:"00:44:06,879 --> 00:44:15,679",arabic:"غَيْرُ مَمَسٍّ، غَيْرُ مُتَسَلَّقٍ، وَمُحَاطٌ بِهَالَةٍ مِنَ الْأَسَاطِيرِ الْقَدِيمَةِ",segs:[{ar:"غَيْرُ مَمَسٍّ",uz:"tegib bo‘lmaydigan"},{ar:"غَيْرُ مُتَسَلَّقٍ",uz:"chiqilmagan"},{ar:"وَمُحَاطٌ بِهَالَةٍ مِنَ الْأَسَاطِيرِ الْقَدِيمَةِ",uz:"qadimiy afsonalar halosi bilan o‘ralgan"}],full_uz:"U tegib bo‘lmaydigan, zabt etilmagan va qadimiy afsonalar halosi bilan o‘ralgan.",note:"مَمَسٌّ — tegilgan, borilgan. مُتَسَلَّقٌ — tirmashib chiqilgan."},
{num:492,time:"00:44:15,679 --> 00:44:22,059",arabic:"يَظَلُّ كَايْلَاشُ أَعْجُوبَةً جِيُولُوجِيَّةً تَتَجَاوَزُ حُدُودَ الْخَيَالِ",segs:[{ar:"يَظَلُّ كَايْلَاشُ أَعْجُوبَةً جِيُولُوجِيَّةً",uz:"Kailash geologik ajoyibot bo‘lib qoladi"},{ar:"تَتَجَاوَزُ حُدُودَ الْخَيَالِ",uz:"tasavvur chegaralaridan oshib ketadigan"}],full_uz:"Kailash tasavvur chegaralaridan oshib ketadigan geologik ajoyibot bo‘lib qoladi.",note:null},
{num:493,time:"00:44:22,059 --> 00:44:25,679",arabic:"جِسْرُ دُوجِي فِي الصِّينِ",segs:null,full_uz:"Xitoydagi Dujie ko‘prigi.",note:null},
{num:494,time:"00:44:25,679 --> 00:44:29,799",arabic:"مُعَلَّقًا عَلَى ارْتِفَاعٍ شَاهِقٍ فِي جَنُوبِ غَرْبِ الصِّينِ",segs:[{ar:"مُعَلَّقًا عَلَى ارْتِفَاعٍ شَاهِقٍ",uz:"nihoyatda balandlikda muallaq holda"},{ar:"فِي جَنُوبِ غَرْبِ الصِّينِ",uz:"Xitoyning janubi-g‘arbida"}],full_uz:"Xitoyning janubi-g‘arbida nihoyatda balandlikda muallaq turib.",note:"مُعَلَّقٌ — muallaq, osilgan."},
{num:495,time:"00:44:29,800 --> 00:44:35,539",arabic:"يَقِفُ جِسْرُ دُوجِي كَتُحْفَةٍ هَنْدَسِيَّةٍ وُلِدَتْ مِنْ جُغْرَافِيَا مُتَطَرِّفَةٍ",segs:[{ar:"يَقِفُ جِسْرُ دُوجِي كَتُحْفَةٍ هَنْدَسِيَّةٍ",uz:"Dujie ko‘prigi muhandislik durdonasi sifatida qad rostlaydi"},{ar:"وُلِدَتْ مِنْ جُغْرَافِيَا مُتَطَرِّفَةٍ",uz:"g‘oyat keskin geografik sharoitdan tug‘ilgan"}],full_uz:"Dujie ko‘prigi g‘oyat keskin geografik sharoitdan tug‘ilgan muhandislik durdonasi sifatida qad rostlaydi.",note:"مُتَطَرِّفٌ — o‘ta keskin, ekstremal."},
{num:496,time:"00:44:35,539 --> 00:44:41,080",arabic:"يَمْتَدُّ فَوْقَ وَادٍ نُحِتَ عَبْرَ عَشَرَاتِ الْمَلَايِينَ مِنَ السِّنِينَ",segs:[{ar:"يَمْتَدُّ فَوْقَ وَادٍ",uz:"u vodiy ustidan cho‘ziladi"},{ar:"نُحِتَ عَبْرَ عَشَرَاتِ الْمَلَايِينَ مِنَ السِّنِينَ",uz:"o‘nlab million yillar davomida o‘yilgan"}],full_uz:"U o‘nlab million yillar davomida o‘yilgan vodiy ustidan cho‘ziladi.",note:null},
{num:497,time:"00:44:41,080 --> 00:44:46,280",arabic:"وَيَرْتَفِعُ سَطْحُهُ قَرَابَةَ سِتِّمِائَةِ مِتْرٍ فَوْقَ نَهْرِ بَيَان",segs:[{ar:"وَيَرْتَفِعُ سَطْحُهُ قَرَابَةَ سِتِّمِائَةِ مِتْرٍ",uz:"uning yuzasi qariyb olti yuz metr baland ko‘tariladi"},{ar:"فَوْقَ نَهْرِ بَيَان",uz:"Bian daryosi ustida"}],full_uz:"Uning yuzasi Bian daryosi ustidan qariyb olti yuz metr baland ko‘tariladi.",note:null},
{num:498,time:"00:44:46,280 --> 00:44:49,460",arabic:"لِيُعَدَّ مِنْ أَعْلَى الْجُسُورِ فِي الْعَالَمِ",segs:null,full_uz:"U dunyodagi eng baland ko‘priklardan biri hisoblanadi.",note:null},
{num:499,time:"00:44:49,460 --> 00:44:56,000",arabic:"ثُبِّتَتْ أَبْرَاجُهُ فِي مُنْحَدَرَاتٍ مِنَ الْحَجَرِ الْجِيرِيِّ الْوَعِرِ",segs:[{ar:"ثُبِّتَتْ أَبْرَاجُهُ",uz:"uning minoralari mahkamlangan"},{ar:"فِي مُنْحَدَرَاتٍ مِنَ الْحَجَرِ الْجِيرِيِّ الْوَعِرِ",uz:"notekis ohaktosh yonbag‘irlarida"}],full_uz:"Uning minoralari notekis ohaktosh yonbag‘irlariga mahkamlangan.",note:"وَعِرٌ — notekis, o‘tish qiyin."},
{num:500,time:"00:44:56,000 --> 00:45:02,679",arabic:"حَيْثُ حُفِرَتِ الْأَسَاسَاتُ لِمِئَاتِ الْأَمْتَارِ دَاخِلَ الصَّخْرِ لِضَمَانِ الِاسْتِقْرَارِ",segs:[{ar:"حَيْثُ حُفِرَتِ الْأَسَاسَاتُ لِمِئَاتِ الْأَمْتَارِ دَاخِلَ الصَّخْرِ",uz:"u yerda poydevorlar qoyaning yuzlab metr ichiga qazilgan"},{ar:"لِضَمَانِ الِاسْتِقْرَارِ",uz:"barqarorlikni ta’minlash uchun"}],full_uz:"Barqarorlikni ta’minlash uchun poydevorlar qoyaning yuzlab metr ichiga qazilgan.",note:"الِاسْتِقْرَارُ — barqarorlik."},
{num:501,time:"00:45:02,679 --> 00:45:07,860",arabic:"اسْتَغْرَقَ الْمَشْرُوعُ نَحْوَ ثَلَاثِ سَنَوَاتٍ",segs:null,full_uz:"Loyiha taxminan uch yil davom etdi.",note:"اسْتَغْرَقَ — vaqt talab qilmoq, davom etmoq."},
{num:502,time:"00:45:07,860 --> 00:45:13,000",arabic:"مُسْتَخْدِمًا كَابِلَاتٍ يَتَجَاوَزُ طُولُهَا الْإِجْمَالِيُّ أَلْفَيْ مِتْرٍ",segs:[{ar:"مُسْتَخْدِمًا كَابِلَاتٍ",uz:"kabellardan foydalanib"},{ar:"يَتَجَاوَزُ طُولُهَا الْإِجْمَالِيُّ أَلْفَيْ مِتْرٍ",uz:"umumiy uzunligi ikki ming metrdan oshadigan"}],full_uz:"Umumiy uzunligi ikki ming metrdan oshadigan kabellardan foydalanib.",note:"الْإِجْمَالِيُّ — umumiy, jami."},
{num:503,time:"00:45:13,000 --> 00:45:21,199",arabic:"الْيَوْمَ يَقِفُ هَذَا الْبِنَاءُ مُتَحَدِّيًا الْجَاذِبِيَّةَ كَشَاهِدٍ عَلَى تَزَاوُجِ الْجِيُولُوجْيَا",segs:[{ar:"الْيَوْمَ يَقِفُ هَذَا الْبِنَاءُ مُتَحَدِّيًا الْجَاذِبِيَّةَ",uz:"bugun bu inshoot gravitatsiyaga qarshi turgan holda"},{ar:"كَشَاهِدٍ عَلَى تَزَاوُجِ الْجِيُولُوجْيَا",uz:"geologiyaning uyg‘unlashuviga guvoh sifatida"}],full_uz:"Bugun bu inshoot geologiyaning uyg‘unlashuviga guvoh bo‘lib, gravitatsiyaga qarshi turgandek.",note:"تَزَاوُجٌ — qo‘shilish, uyg‘unlashuv."},
{num:504,time:"00:45:21,199 --> 00:45:24,900",arabic:"مَعَ طُمُوحِ الْهَنْدَسَةِ الْبَشَرِيَّةِ فِي قَهْرِ الْمُسْتَحِيلِ",segs:[{ar:"مَعَ طُمُوحِ الْهَنْدَسَةِ الْبَشَرِيَّةِ",uz:"inson muhandisligi intilishi bilan"},{ar:"فِي قَهْرِ الْمُسْتَحِيلِ",uz:"imkonsizni yengishda"}],full_uz:"Inson muhandisligining imkonsizni yengishga bo‘lgan intilishi bilan.",note:"قَهْرٌ — yengish, bo‘ysundirish."},
{num:505,time:"00:45:26,000 --> 00:45:32,280",arabic:"وَفِي نِهَايَةِ هَذِهِ الرِّحْلَةِ عَبْرَ أَطْرَافِ الْأَرْضِ الْقُصْوَى",segs:[{ar:"وَفِي نِهَايَةِ هَذِهِ الرِّحْلَةِ",uz:"bu sayohat oxirida"},{ar:"عَبْرَ أَطْرَافِ الْأَرْضِ الْقُصْوَى",uz:"Yerning eng chekka nuqtalari bo‘ylab"}],full_uz:"Yerning eng chekka nuqtalari bo‘ylab qilgan bu sayohatimiz oxirida.",note:"الْقُصْوَى — eng chekka, eng uzoq."},
{num:506,time:"00:45:32,280 --> 00:45:36,579",arabic:"نُدْرِكُ أَنَّ عَالَمَنَا لَا يُقَاسُ فَقَطْ بِالْمَسَافَاتِ",segs:[{ar:"نُدْرِكُ أَنَّ عَالَمَنَا",uz:"biz anglaymizki, dunyomiz"},{ar:"لَا يُقَاسُ فَقَطْ بِالْمَسَافَاتِ",uz:"faqat masofalar bilan o‘lchanmaydi"}],full_uz:"Biz dunyomiz faqat masofalar bilan o‘lchanmasligini anglaymiz.",note:"أَدْرَكَ — anglamoq, tushunmoq."},
{num:507,time:"00:45:36,579 --> 00:45:40,280",arabic:"بَلْ بِالدَّهْشَةِ الَّتِي يَزْرَعُهَا فِي أَعْمَاقِنَا",segs:[{ar:"بَلْ بِالدَّهْشَةِ",uz:"balki hayrat bilan"},{ar:"الَّتِي يَزْرَعُهَا فِي أَعْمَاقِنَا",uz:"u bizning ichimizga ekadigan"}],full_uz:"Balki u qalblarimizga ekadigan hayrat bilan o‘lchanadi.",note:"يَزْرَعُ — ekmoq; majozan uyg‘otmoq."},
{num:508,time:"00:45:40,280 --> 00:45:46,579",arabic:"أَمَاكِنُ بَدَتْ مُسْتَحِيلَةً",segs:null,full_uz:"Imkonsizdek ko‘ringan joylar.",note:"بَدَا — ko‘rinmoq, namoyon bo‘lmoq."},
{num:509,time:"00:45:46,579 --> 00:45:50,360",arabic:"تَشَكَّلَتْ عَبْرَ مَلَايِينَ السِّنِينَ مِنَ الصَّبْرِ الْكَوْنِيِّ",segs:[{ar:"تَشَكَّلَتْ عَبْرَ مَلَايِينَ السِّنِينَ",uz:"millionlab yillar davomida shakllangan"},{ar:"مِنَ الصَّبْرِ الْكَوْنِيِّ",uz:"koinotning sabr-toqati bilan"}],full_uz:"Millionlab yillar davomida koinotning sabr-toqati bilan shakllangan.",note:"كَوْنِيٌّ — koinotga oid, kosmik."},
{num:510,time:"00:45:50,360 --> 00:45:56,140",arabic:"لِتَقِفَ الْيَوْمَ شَاهِدًا عَلَى قُوَّةِ الطَّبِيعَةِ وَفُضُولِ الْإِنْسَانِ",segs:[{ar:"لِتَقِفَ الْيَوْمَ شَاهِدًا",uz:"bugun guvoh bo‘lib turishi uchun"},{ar:"عَلَى قُوَّةِ الطَّبِيعَةِ وَفُضُولِ الْإِنْسَانِ",uz:"tabiat qudrati va inson qiziquvchanligiga"}],full_uz:"Bugun tabiat qudrati va inson qiziquvchanligiga guvoh bo‘lib turishi uchun.",note:"فُضُولٌ — qiziquvchanlik, bilishga intilish."},
{num:511,time:"00:45:56,140 --> 00:46:06,240",arabic:"مِنْ قِمَمٍ تُعَانِقُ السَّمَاءَ إِلَى مِيَاهٍ تَنْبِضُ بِالْحَيَاةِ",segs:[{ar:"مِنْ قِمَمٍ تُعَانِقُ السَّمَاءَ",uz:"osmonni quchadigan cho‘qqilardan"},{ar:"إِلَى مِيَاهٍ تَنْبِضُ بِالْحَيَاةِ",uz:"hayot jo‘sh uradigan suvlargacha"}],full_uz:"Osmonni quchadigan cho‘qqilardan hayot jo‘sh uradigan suvlargacha.",note:"تُعَانِقُ — quchmoq, bag‘riga olmoq. تَنْبِضُ — jo‘sh urmoq."},
{num:512,time:"00:46:06,240 --> 00:46:12,360",arabic:"وَمِنْ صُخُورٍ تَحْفَظُ أَسْرَارَ الزَّمَنِ إِلَى قِرَانٍ تَرْوِي حِكَايَاتِ الْبَقَاءِ",segs:[{ar:"وَمِنْ صُخُورٍ تَحْفَظُ أَسْرَارَ الزَّمَنِ",uz:"zamon sirlarini saqlaydigan qoyalardan"},{ar:"إِلَى قِرَانٍ تَرْوِي حِكَايَاتِ الْبَقَاءِ",uz:"omon qolish hikoyalarini so‘zlaydigan ...gacha"}],full_uz:"Zamon sirlarini saqlaydigan qoyalardan omon qolish hikoyalarini so‘zlaydigan ...gacha.",note:"Manba matnidagi «قِرَانٍ» so‘zi kontekstda noaniq va ehtimol xatolik bilan yozilgan; shu sabab mazmuni to‘liq aniqlashtirilmadi."},
{num:513,time:"00:46:12,360 --> 00:46:18,320",arabic:"تُذَكِّرُنَا هَذِهِ الْعَجَائِبُ بِأَنَّ الْأَرْضَ لَيْسَتْ مُجَرَّدَ مَوْطِنٍ",segs:[{ar:"تُذَكِّرُنَا هَذِهِ الْعَجَائِبُ",uz:"bu ajoyibotlar bizga eslatadi"},{ar:"بِأَنَّ الْأَرْضَ لَيْسَتْ مُجَرَّدَ مَوْطِنٍ",uz:"Yer shunchaki makon emasligini"}],full_uz:"Bu ajoyibotlar bizga Yer shunchaki makon emasligini eslatadi.",note:"مَوْطِنٌ — vatan, yashash makoni."},
{num:514,time:"00:46:18,320 --> 00:46:22,340",arabic:"بَلْ قِصَّةٌ حَيَّةٌ تُرْوَى بِلَا كَلِمَاتٍ",segs:[{ar:"بَلْ قِصَّةٌ حَيَّةٌ",uz:"balki tirik bir hikoya"},{ar:"تُرْوَى بِلَا كَلِمَاتٍ",uz:"so‘zlarsiz aytiladigan"}],full_uz:"Balki so‘zlarsiz aytiladigan tirik bir hikoyadir.",note:null},
{num:515,time:"00:46:22,340 --> 00:46:30,580",arabic:"وَإِنْ لَامَسَ هَذَا الْجَمَالُ شَيْئًا فِي دَاخِلِكَ",segs:[{ar:"وَإِنْ لَامَسَ هَذَا الْجَمَالُ شَيْئًا",uz:"agar bu go‘zallik biror narsaga tegib o‘tgan bo‘lsa"},{ar:"فِي دَاخِلِكَ",uz:"ichingizdagi"}],full_uz:"Agar bu go‘zallik ichingizdagi biror narsaga tegib o‘tgan bo‘lsa.",note:"لَامَسَ — tegmoq, ta’sir qilmoq."},
{num:516,time:"00:46:30,580 --> 00:46:35,500",arabic:"وَإِنْ أَخَذَتْكَ هَذِهِ الرِّحْلَةُ إِلَى أَمَاكِنَ لَمْ تَطَأْهَا مِنْ قَبْلُ",segs:[{ar:"وَإِنْ أَخَذَتْكَ هَذِهِ الرِّحْلَةُ",uz:"agar bu sayohat sizni olib borgan bo‘lsa"},{ar:"إِلَى أَمَاكِنَ لَمْ تَطَأْهَا مِنْ قَبْلُ",uz:"ilgari qadam bosmagan joylarga"}],full_uz:"Agar bu sayohat sizni ilgari qadam bosmagan joylarga olib borgan bo‘lsa.",note:"وَطِئَ — qadam bosmoq."},
{num:517,time:"00:46:35,500 --> 00:46:38,840",arabic:"فَلَا تَنْسَ دَعْمَنَا بِالِاشْتِرَاكِ فِي الْقَنَاةِ",segs:[{ar:"فَلَا تَنْسَ",uz:"shuning uchun unutmang"},{ar:"دَعْمَنَا بِالِاشْتِرَاكِ فِي الْقَنَاةِ",uz:"kanalga obuna bo‘lib bizni qo‘llab-quvvatlashni"}],full_uz:"Shuning uchun kanalga obuna bo‘lib bizni qo‘llab-quvvatlashni unutmang.",note:"الِاشْتِرَاكُ — obuna bo‘lish."},
{num:518,time:"00:46:38,840 --> 00:46:41,140",arabic:"وَتَفْعِيلَ زِرِّ الْإِعْجَابِ",segs:null,full_uz:"Va “like” tugmasini faollashtirishni.",note:"تَفْعِيلٌ — faollashtirish. زِرُّ الْإِعْجَابِ — “like” tugmasi."},
{num:519,time:"00:46:41,140 --> 00:46:47,080",arabic:"فَكُلُّ تَفَاعُلٍ مِنْكَ هُوَ خُطْوَةٌ جَدِيدَةٌ نَحْوَ رِحْلَةٍ قَادِمَةٍ",segs:[{ar:"فَكُلُّ تَفَاعُلٍ مِنْكَ",uz:"sizning har bir faolligingiz"},{ar:"هُوَ خُطْوَةٌ جَدِيدَةٌ نَحْوَ رِحْلَةٍ قَادِمَةٍ",uz:"kelgusi sayohat tomon yangi bir qadamdir"}],full_uz:"Sizning har bir faolligingiz kelgusi sayohat tomon yangi bir qadamdir.",note:"تَفَاعُلٌ — faollik, o‘zaro munosabat."},
{num:520,time:"00:46:47,079 --> 00:46:53,619",arabic:"شَارِكْنَا رَأْيَكَ فِي التَّعْلِيقَاتِ",segs:[{ar:"شَارِكْنَا رَأْيَكَ",uz:"fikringizni biz bilan bo‘lishing"},{ar:"فِي التَّعْلِيقَاتِ",uz:"izohlarda"}],full_uz:"Fikringizni izohlarda biz bilan bo‘lishing.",note:"شَارَكَ — bo‘lishmoq, baham ko‘rmoq."},
{num:521,time:"00:46:53,619 --> 00:46:57,139",arabic:"أَيُّ هَذِهِ الْعَجَائِبِ شَدَّكَ أَكْثَرَ",segs:[{ar:"أَيُّ هَذِهِ الْعَجَائِبِ",uz:"bu ajoyibotlarning qaysi biri"},{ar:"شَدَّكَ أَكْثَرَ",uz:"sizni ko‘proq o‘ziga tortdi"}],full_uz:"Bu ajoyibotlarning qaysi biri sizni ko‘proq o‘ziga tortdi?",note:"شَدَّ — tortmoq, o‘ziga jalb qilmoq."},
{num:522,time:"00:46:57,139 --> 00:47:02,400",arabic:"وَأَيُّ وِجْهَةٍ تَحْلُمُ أَنْ نَزُورَهَا مَعًا فِي الْفِيدْيُو الْقَادِمِ",segs:[{ar:"وَأَيُّ وِجْهَةٍ تَحْلُمُ أَنْ نَزُورَهَا مَعًا",uz:"va qaysi manzilga birga borishimizni orzu qilasiz"},{ar:"فِي الْفِيدْيُو الْقَادِمِ",uz:"keyingi videoda"}],full_uz:"Va keyingi videoda qaysi manzilga birga borishimizni orzu qilasiz?",note:"وِجْهَةٌ — manzil, yo‘nalish."},
{num:523,time:"00:47:02,400 --> 00:47:08,819",arabic:"إِلَى أَنْ نَلْتَقِيَ فِي رِحْلَةٍ أُخْرَى",segs:null,full_uz:"Boshqa bir sayohatda uchrashgunimizcha.",note:"إِلَى أَنْ نَلْتَقِيَ — uchrashgunimizcha."},
{num:524,time:"00:47:08,819 --> 00:47:10,759",arabic:"حَيْثُ يَنْتَظِرُونَ الْمَجْهُولَ",segs:[{ar:"حَيْثُ يَنْتَظِرُونَ",uz:"u yerda ular kutadilar"},{ar:"الْمَجْهُولَ",uz:"noma’lum narsani"}],full_uz:"U yerda noma’lum narsani kutadilar.",note:"الْمَجْهُولُ — noma’lum narsa."},
{num:525,time:"00:47:10,759 --> 00:47:13,659",arabic:"وَتُولَدُ الدَّهْشَةُ مِنْ جَدِيدٍ",segs:null,full_uz:"Va hayrat yangidan tug‘iladi.",note:"تُولَدُ — tug‘iladi. مِنْ جَدِيدٍ — yangidan."}
];

if (typeof module !== "undefined" && module.exports) {
    module.exports = lessons;
}
